AI_LANGUAGES = ["English", "Arabic", "عربي (مصري)", "عربي (عراقي)", "عربي (خليجي)", "دارجة (مغربية)", "عربي (شامي)", "French", "Spanish", "German", "Italian", "Portuguese", "Turkish", "Dutch", "Russian", "Greek", "Croatian", "Serbian", "Bosnian"]
AI_FREQUENCIES = [5, 10, 15, 30, 60]


def get_ai_language_instruction(language):
    """Format the language instruction, supporting dialect specifics."""
    dialect_map = {
        "عربي (مصري)": "Egyptian Arabic",
        "عربي (عراقي)": "Iraqi Arabic",
        "عربي (خليجي)": "Gulf Arabic",
        "دارجة (مغربية)": "Moroccan Darija",
        "عربي (شامي)": "Levantine Arabic"
    }
    if language in dialect_map:
        return "Respond ONLY in {} dialect USING NATIVE ARABIC SCRIPT, casual football fan tone".format(dialect_map[language])

    if "(" in language and ")" in language:
        base_lang = language.split("(")[0].strip()
        dialect = language.split("(")[1].replace(")", "").strip()
        return "Respond ONLY in {} {} dialect USING NATIVE SCRIPT, casual football fan tone".format(dialect, base_lang)

    return "Respond ONLY in {}".format(language)


def fetch_sports_headlines(max_items=6):
    """Fetch latest sports headlines from BBC Sport RSS (no API key needed)."""
    feeds = [
        "https://feeds.bbci.co.uk/sport/football/rss.xml",
        "https://feeds.bbci.co.uk/sport/rss.xml",
    ]
    headlines = []
    for feed_url in feeds:
        if len(headlines) >= max_items:
            break
        try:
            req = Request(feed_url)
            req.add_header("User-Agent", "Mozilla/5.0")
            resp = urlopen(req, timeout=8)
            raw = resp.read().decode("utf-8", errors="ignore")
            # Lightweight XML title extraction (no heavy parser needed)
            import re
            items = re.findall(r"<item>.*?<title>\s*(.*?)\s*</title>", raw, re.DOTALL)
            for title in items:
                clean = re.sub(r"<!\[CDATA\[(.*?)\]\]>", r"\1", title).strip()
                if clean and clean not in headlines:
                    headlines.append(clean)
                    if len(headlines) >= max_items:
                        break
        except Exception as e:
            log_dbg("[AI Mode] News fetch failed for {}: {}".format(feed_url, str(e)))
    return headlines


def fetch_soccer_teams_threaded(league_slug, on_result):
    """
    Fetch teams for a given soccer league.

    Strategy (tried in order):
    1. site.api.espn.com  /v2/sports/soccer/{slug}/teams
       Returns full inline team objects; covers most leagues.
    2. sports.core.api.espn.com  /v2/sports/soccer/leagues/{slug}/teams
       Returns $ref stubs; each is resolved individually (capped at 100).

    Calls on_result(teams_list) on the main thread.
    teams_list is a list of dicts: {id, name, short, logo_url}
    On complete failure calls on_result([]).
    """
    def _run():
        try:
            from urllib2 import urlopen, Request as Req
        except ImportError:
            from urllib.request import urlopen, Request as Req

        def _fetch_json(url, timeout=10):
            req = Req(url)
            req.add_header("Accept", "application/json")
            req.add_header("User-Agent", "Mozilla/5.0")
            resp = urlopen(req, timeout=timeout)
            return json.loads(resp.read().decode("utf-8"))

        def _parse_team_obj(t):
            team_id   = str(t.get("id", ""))
            disp_name = t.get("displayName", t.get("name", ""))
            short     = t.get("shortDisplayName", t.get("abbreviation", ""))
            logos     = t.get("logos", [])
            logo_url  = logos[0].get("href", "") if logos else ""
            if team_id and disp_name:
                return {"id": team_id, "name": disp_name, "short": short, "logo_url": logo_url}
            return None

        teams = []

        if league_slug == "epl.1" or str(league_slug).startswith("epl"):
            teams = [
                {"id": "1", "name": "الأهلي", "short": "الأهلي", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/1.png"},
                {"id": "2", "name": "الزمالك", "short": "الزمالك", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/2.png"},
                {"id": "1451", "name": "بيراميدز", "short": "بيراميدز", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/1451.png"},
                {"id": "12723", "name": "سيراميكا كليوباترا", "short": "سيراميكا", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/12723.png"},
                {"id": "8", "name": "المصري", "short": "المصري", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/8.png"},
                {"id": "13", "name": "الاتحاد السكندري", "short": "الاتحاد", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/13.png"},
                {"id": "860", "name": "سموحة", "short": "سموحة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/860.png"},
                {"id": "1683", "name": "زد", "short": "زد", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/1683.png"},
                {"id": "150", "name": "إنبي", "short": "إنبي", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/150.png"},
                {"id": "617", "name": "الجونة", "short": "الجونة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/617.png"},
                {"id": "304", "name": "طلائع الجيش", "short": "طلائع الجيش", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/304.png"},
                {"id": "12724", "name": "مودرن سبورت", "short": "مودرن سبورت", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/12724.png"},
                {"id": "653", "name": "بتروجت", "short": "بتروجت", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/653.png"},
                {"id": "7", "name": "غزل المحلة", "short": "غزل المحلة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/7.png"},
                {"id": "1016", "name": "وادي دجلة", "short": "وادي دجلة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/1016.png"},
                {"id": "11", "name": "المقاولون العرب", "short": "المقاولون", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/11.png"},
                {"id": "12", "name": "القناة", "short": "القناة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/12.png"},
                {"id": "812", "name": "أبو قير للأسمدة", "short": "أبو قير", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/812.png"},
                {"id": "610", "name": "بترول أسيوط", "short": "بترول أسيوط", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/610.png"},
                {"id": "2188", "name": "البنك الأهلي", "short": "البنك الأهلي", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/2188.png"},
                {"id": "3", "name": "الإسماعيلي", "short": "الإسماعيلي", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/3.png"},
                {"id": "6", "name": "حرس الحدود", "short": "حرس الحدود", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/6.png"},
                {"id": "5", "name": "فاركو", "short": "فاركو", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/5.png"},
                {"id": "10", "name": "بلدية المحلة", "short": "بلدية المحلة", "logo_url": "https://semedia.filgoal.com/Photos/Team/Medium/10.png"},
            ]
            reactor.callFromThread(on_result, teams)
            return
        try:
            site_url = (
                "https://site.api.espn.com/apis/site/v2/sports/soccer"
                "/{slug}/teams".format(slug=league_slug)
            )
            data    = _fetch_json(site_url)
            sports  = data.get("sports", [])
            leagues = sports[0].get("leagues", []) if sports else []
            raw     = leagues[0].get("teams", []) if leagues else []
            for entry in raw:
                t_obj  = entry.get("team", entry)
                parsed = _parse_team_obj(t_obj)
                if parsed:
                    teams.append(parsed)
            log_dbg("[FavTeams] site API returned {} teams for {}".format(len(teams), league_slug))
        except Exception as e:
            log_dbg("[FavTeams] site API failed for {}: {}".format(league_slug, e))

        # Stage 2: Core API + $ref resolution (fallback)
        if not teams:
            log_dbg("[FavTeams] falling back to core API $ref resolution for {}".format(league_slug))
            try:
                core_url = (
                    "https://sports.core.api.espn.com/v2/sports/soccer"
                    "/leagues/{slug}/teams?limit=100&page=1&active=true".format(slug=league_slug)
                )
                data  = _fetch_json(core_url)
                items = data.get("items", [])
                for item in items:
                    parsed = _parse_team_obj(item)
                    if parsed:
                        teams.append(parsed)
                        continue
                    ref = item.get("$ref", "")
                    if not ref:
                        continue
                    try:
                        t_data = _fetch_json(ref, timeout=6)
                        parsed = _parse_team_obj(t_data)
                        if parsed:
                            teams.append(parsed)
                    except Exception as ref_err:
                        log_dbg("[FavTeams] $ref resolve failed {}: {}".format(ref, ref_err))
            except Exception as e:
                log_dbg("[FavTeams] core API fallback failed for {}: {}".format(league_slug, e))

        reactor.callFromThread(on_result, teams)

    import threading
    threading.Thread(target=_run, daemon=True).start()

def resolve_team_ref_threaded(ref_url, on_result):
    """Fetch a single team $ref URL and return a minimal dict (used when inline fields are missing)."""
    def _run():
        try:
            from urllib2 import urlopen, Request as Req
        except ImportError:
            from urllib.request import urlopen, Request as Req
        try:
            req = Req(ref_url)
            req.add_header("Accept", "application/json")
            data = json.loads(urlopen(req, timeout=6).read().decode("utf-8"))
            team = {
                "id":       str(data.get("id", "")),
                "name":     data.get("displayName", data.get("name", "")),
                "short":    data.get("shortDisplayName", data.get("abbreviation", "")),
                "logo_url": (data.get("logos") or [{}])[0].get("href", ""),
            }
            reactor.callFromThread(on_result, team)
        except Exception as e:
            log_dbg("[FavTeams] resolve_team_ref failed: {}".format(e))
            reactor.callFromThread(on_result, None)
    import threading
    threading.Thread(target=_run, daemon=True).start()


def call_ai_api_threaded(api_key, provider, prompt, on_result):
    """
    Calls the chosen AI provider in a background thread.
    Calls on_result(text) on the main thread when done.
    Calls on_result(None) on error so the in-flight flag can be cleared.
    """
    def _run():
        req = None
        try:
            # Fetch real-time sports news and inject into prompt
            full_prompt = prompt
            try:
                news = fetch_sports_headlines(6)
                if news:
                    news_block = "\n\n=== LATEST SPORTS NEWS (from BBC Sport) ===\n"
                    news_block += "\n".join("- " + h for h in news)
                    full_prompt = prompt + news_block
            except Exception:
                pass  # News fetch is optional, don't block AI call

            text = ""
            if provider == "gemini":
                url = (
                    "https://generativelanguage.googleapis.com"
                    "/v1beta/models/gemini-2.0-flash:generateContent"
                    "?key=" + api_key
                )
                payload = json.dumps({
                    "contents": [{"parts": [{"text": full_prompt}]}]
                })
                req = Request(url, data=payload.encode("utf-8"))
                req.add_header("Content-Type", "application/json")
                req.add_header("User-Agent", "Mozilla/5.0")
                resp = urlopen(req, timeout=15)
                data = json.loads(resp.read().decode("utf-8"))
                text = (data["candidates"][0]["content"]["parts"][0]["text"])

            elif provider == "groq":
                url = "https://api.groq.com/openai/v1/chat/completions"
                payload = json.dumps({
                    "model": "llama-3.1-8b-instant",
                    "messages": [{"role": "user", "content": full_prompt}],
                    "max_tokens": 300
                })
                req = Request(url, data=payload.encode("utf-8"))
                req.add_header("Content-Type", "application/json")
                req.add_header("Authorization", "Bearer " + api_key)
                req.add_header("User-Agent", "Mozilla/5.0")
                resp = urlopen(req, timeout=15)
                data = json.loads(resp.read().decode("utf-8"))
                text = data["choices"][0]["message"]["content"]

            else:
                text = ""

            # Schedule callback on main thread via reactor
            if on_result:
                reactor.callFromThread(on_result, text.strip() if text else None)

        except Exception as e:
            # Handle rate limiting with one automatic retry
            err_code = getattr(e, 'code', 0)
            if err_code == 429 and req is not None:
                try:
                    import time
                    log_dbg("[AI Mode] Rate limited (429). Retrying in 30s...")
                    time.sleep(30)
                    # Rebuild request for retry
                    req2 = Request(req.full_url, data=req.data)
                    for hdr, val in req.header_items():
                        if hdr.lower() not in ('host', 'content-length'):
                            req2.add_header(hdr, val)
                    resp = urlopen(req2, timeout=15)
                    data = json.loads(resp.read().decode("utf-8"))
                    if provider == "gemini":
                        text = data["candidates"][0]["content"]["parts"][0]["text"]
                    elif provider == "groq":
                        text = data["choices"][0]["message"]["content"]
                    else:
                        text = ""
                    if on_result:
                        reactor.callFromThread(on_result, text.strip() if text else None)
                    return
                except Exception as retry_e:
                    log_dbg("[AI Mode] Retry also failed: " + str(retry_e))
                if on_result:
                    reactor.callFromThread(
                        on_result,
                        "ERROR: Rate limited by AI provider. "
                        "Please wait a few minutes or switch to Groq provider.")
                return

            err_msg = str(e)
            if hasattr(e, 'read'):
                try:
                    err_msg += " | " + e.read().decode("utf-8")
                except:
                    pass
            log_dbg("[AI Mode] API call failed: " + err_msg)
            if on_result:
                reactor.callFromThread(on_result, "ERROR: " + err_msg)

    t = threading.Thread(target=_run)
    t.daemon = True
    t.start()


def build_ai_prompt(language, cached_events, match_snapshots, ledger=None):
    """Build a compact, structured prompt from live match data (~800 tokens max)."""
    lines = []

    for event in cached_events[:12]:   # cap to 12 events
        snap = match_snapshots.get(str(event.get("id", "")))
        if not snap:
            continue
        state  = snap.get("state", "pre")
        h_name = snap.get("h_name", "Home")
        a_name = snap.get("a_name", "Away")
        score  = snap.get("score_str", "")
        league = snap.get("league_name", "")
        t_str  = snap.get("time_str", "")
        clock  = snap.get("clock", "")

        if state == "in":
            lines.append(
                "LIVE: {} vs {} | {} | {} {}".format(
                    h_name, a_name, score, league, clock))
        elif state == "pre":
            lines.append(
                "UPCOMING: {} vs {} at {} | {}".format(
                    h_name, a_name, t_str, league))
        elif state == "post":
            lines.append(
                "FINISHED: {} vs {} | {} | {}".format(
                    h_name, a_name, score, league))

    # Fallback: if cached_events didn't produce lines, iterate snapshots directly
    if not lines and match_snapshots:
        for mid, snap in list(match_snapshots.items())[:12]:
            state  = snap.get("state", "pre")
            h_name = snap.get("h_name", "Home")
            a_name = snap.get("a_name", "Away")
            score  = snap.get("score_str", "")
            league = snap.get("league_name", "")
            t_str  = snap.get("time_str", "")
            clock  = snap.get("clock", "")
            if state == "in":
                lines.append("LIVE: {} vs {} | {} | {} {}".format(h_name, a_name, score, league, clock))
            elif state == "pre":
                lines.append("UPCOMING: {} vs {} at {} | {}".format(h_name, a_name, t_str, league))
            elif state == "post":
                lines.append("FINISHED: {} vs {} | {} | {}".format(h_name, a_name, score, league))

    match_summary = "\n".join(lines) if lines else "No matches available."
    log_dbg("[AI Mode] Prompt match data ({} lines): {}".format(len(lines), match_summary[:300]))

    # --- Build ledger / user prediction context ---
    ledger_lines = []
    if ledger:
        pending = ledger.get("pending_bets", {})
        if pending and match_snapshots:
            for eid, bet in list(pending.items())[:6]:  # cap to 6 bets
                snap = match_snapshots.get(str(eid))
                prediction = bet.get("prediction", "")
                h_name = bet.get("h_name", "Home")
                a_name = bet.get("a_name", "Away")

                pred_label = (
                    h_name if prediction == "home"
                    else a_name if prediction == "away"
                    else "Draw"
                )
                if snap:
                    state = snap.get("state", "pre")
                    score = snap.get("score_str", "")
                    if state == "in":
                        ledger_lines.append(
                            "USER BET: {} vs {} (LIVE {}) — user picked: {}".format(
                                h_name, a_name, score, pred_label))
                    elif state == "pre":
                        ledger_lines.append(
                            "USER BET: {} vs {} (upcoming) — user picked: {}".format(
                                h_name, a_name, pred_label))
                    # skip 'post' matches — bet already resolved
                else:
                    # Match not in current snapshot window (different league/day)
                    ledger_lines.append(
                        "USER BET (pending): {} vs {} — user picked: {}".format(
                            h_name, a_name, pred_label))

        total_preds = int(ledger.get("total_predictions", 0))
        correct     = int(ledger.get("correct_predictions", 0))
        total_score = int(ledger.get("total_score", 0))
        if total_preds > 0:
            accuracy = int(correct * 100.0 / total_preds)
            ledger_lines.append(
                "USER RECORD: {}/{} correct ({}% accuracy), points: {}".format(
                    correct, total_preds, accuracy, total_score))

    has_ledger = bool(ledger_lines)

    system_instruction = (
        "You are an energetic sports broadcaster and commentator. "
        "I will provide you with TWO data sources:\n"
        "1. MATCH DATA: Live, Upcoming, and Finished matches from the user's watchlist.\n"
        "2. LATEST SPORTS NEWS: Real breaking headlines from BBC Sport.\n\n"
        "Your job is to write EXACTLY 2 short, thrilling notification messages.\n\n"
        "RULES:\n"
        "1. Message 1: A punchy headline about a match from the MATCH DATA "
        "(mention actual team names and scores), OR if no matches exist, "
        "pick the most exciting headline from LATEST SPORTS NEWS and rephrase it.\n"
        "2. Message 2: An exciting question, hype reminder, or breaking news update. "
        "Use MATCH DATA for upcoming matches, or LATEST SPORTS NEWS for transfer rumors, "
        "injuries, or major events."
        "{ledger_rule}"
        "\n3. NEVER invent matches, scores, or facts not present in the provided data.\n"
        "4. {language_instruction}.\n"
        "5. Keep each message under 25 words.\n"
        "6. Separate them with a blank line.\n"
        "7. No markdown, no asterisks, no numbering, no emojis."
    ).format(
        language_instruction=get_ai_language_instruction(language),
        ledger_rule=(
            "\n   USER PREDICTIONS are provided below. If a USER BET matches a LIVE "
            "match, make Message 2 personal: reference the user's pick and the current "
            "score in an exciting way."
        ) if has_ledger else ""
    )

    prompt = system_instruction + "\n\n=== MATCH DATA ===\n" + match_summary
    if ledger_lines:
        prompt += "\n\n=== USER PREDICTIONS ===\n" + "\n".join(ledger_lines)
    log_dbg("[AI Mode] Prompt built: {} match lines, {} ledger lines".format(
        len(lines), len(ledger_lines)))
    return prompt


