# Filtered list of soccer-only DATA_SOURCES — used by FavoriteTeamLeagueSelector.
# Stays automatically in sync whenever new soccer leagues are added to DATA_SOURCES.
SOCCER_DATA_SOURCES = [
    (name, url) for name, url in DATA_SOURCES
    if "/sports/soccer/" in url or url.startswith("epl://")
]

# ==============================================================================
# STABLE SLUG HELPERS  (index-to-slug migration for league selections)
# ==============================================================================
def get_slug_from_url(url):
    """Extract a stable, sport-namespaced slug from an ESPN API URL.
    e.g. 'https://site.api.espn.com/.../sports/soccer/eng.1/scoreboard' -> 'soccer/eng.1'
    EuroLeague sentinel URLs return 'euroleague'.
    EPL sentinel URLs return 'soccer/epl.1'."""
    if url.startswith("euroleague://"):
        return "euroleague"
    if url.startswith("epl://"):
        return "soccer/epl.1"
    try:
        parts = url.split('/sports/')
        if len(parts) > 1:
            return parts[1].split('/scoreboard')[0]  # e.g. "soccer/eng.1"
    except Exception:
        pass
    return url

def _build_slug_maps():
    """Build bidirectional slug <-> DATA_SOURCES index lookup dicts."""
    s2i = {}
    i2s = {}
    for i, (_name, _url) in enumerate(DATA_SOURCES):
        slug = get_slug_from_url(_url)
        s2i[slug] = i
        i2s[i] = slug
    return s2i, i2s

SLUG_TO_IDX, IDX_TO_SLUG = _build_slug_maps()

def _load_discovered_leagues():
    """Load auto-discovered leagues from local cache and append to DATA_SOURCES.
    Called once at module load so discovered leagues are available immediately."""
    global SLUG_TO_IDX, IDX_TO_SLUG
    try:
        if os.path.exists(DISCOVERED_LEAGUES_FILE):
            with open(DISCOVERED_LEAGUES_FILE, "r") as _df:
                discovered = json.load(_df)
            if not isinstance(discovered, list):
                return
            existing_slugs = set(get_slug_from_url(u) for _, u in DATA_SOURCES)
            added = 0
            for entry in discovered:
                d_name = entry.get("name", "")
                d_url  = entry.get("url", "")
                d_slug = get_slug_from_url(d_url)
                if d_slug and d_slug not in existing_slugs and d_name and d_url:
                    DATA_SOURCES.append((d_name, d_url))
                    if "/sports/soccer/" in d_url:
                        SOCCER_DATA_SOURCES.append((d_name, d_url))
                    existing_slugs.add(d_slug)
                    added += 1
            if added > 0:
                SLUG_TO_IDX, IDX_TO_SLUG = _build_slug_maps()
    except Exception:
        pass

_load_discovered_leagues()

# ==============================================================================
# SPORT TYPE CLASSIFICATION
# ==============================================================================
# Defines how to detect and display different sport types appropriately
SPORT_TYPE_TEAM = "team_vs"      # Soccer, Basketball, Football, Hockey, Baseball
SPORT_TYPE_RACING = "racing"     # F1, NASCAR, IndyCar, MotoGP
SPORT_TYPE_GOLF = "golf"         # PGA, LPGA, Euro Tour
SPORT_TYPE_TENNIS = "tennis"     # ATP, WTA, Davis Cup
SPORT_TYPE_COMBAT = "combat"     # UFC/MMA, Boxing
SPORT_TYPE_CRICKET = "cricket"   # IPL, Test, ODI, T20
SPORT_TYPE_RUGBY = "rugby"       # Six Nations, Super Rugby, NRL


def get_soccer_league_slug(url):
    """Extract the league slug from a soccer scoreboard URL or sentinel.
    e.g. 'https://site.api.espn.com/apis/site/v2/sports/soccer/eng.1/scoreboard' -> 'eng.1'
    """
    if str(url).startswith("epl://"):
        return "epl.1"
    try:
        parts = url.rstrip("/").split("/")
        if "soccer" in parts:
            idx = parts.index("soccer")
            if idx + 1 < len(parts):
                return parts[idx + 1]
    except Exception:
        pass
    return None


def get_leaderboard_league_category(league, league_url="", sport="soccer"):
    """
    Map league slug or league URL to its independent Leaderboard category name:
    - Premier League (eng.1)
    - La Liga (esp.1)
    - Serie A (ita.1)
    - Bundesliga (ger.1)
    - Ligue 1 (fra.1)
    - Champions League (uefa.champions)
    - World Cup (fifa.world)
    """
    try:
        l_str = (str(league or "") + " " + str(league_url or "")).lower()
        if "fifa.world" in l_str or "world cup" in l_str or "world.cup" in l_str:
            return "World Cup"
        if "egypt" in l_str or "epl://api" in l_str or "egyptian" in l_str or league == "epl":
            return "Egyptian League"
        if "eng.1" in l_str or "premier" in l_str or "epl" in l_str:
            return "Premier League"
        if "esp.1" in l_str or "la liga" in l_str or "laliga" in l_str or "primera division" in l_str:
            return "La Liga"
        if "ita.1" in l_str or "serie a" in l_str or "serie.a" in l_str or "calcio" in l_str:
            return "Serie A"
        if "ger.1" in l_str or "bundesliga" in l_str:
            return "Bundesliga"
        if "fra.1" in l_str or "ligue 1" in l_str or "ligue.1" in l_str:
            return "Ligue 1"
        if "uefa.champions" in l_str or "champions league" in l_str or "ucl" in l_str:
            return "Champions League"
    except Exception:
        pass
    return None



def get_sport_type(league_url):
    """
    Classify sport type based on the ESPN API URL.
    Returns one of: team_vs, racing, golf, tennis, combat, cricket, rugby
    """
    if not league_url:
        return SPORT_TYPE_TEAM
    url_lower = league_url.lower()
    if "/racing/" in url_lower:
        return SPORT_TYPE_RACING
    elif "/golf/" in url_lower:
        return SPORT_TYPE_GOLF
    elif "/tennis/" in url_lower:
        return SPORT_TYPE_TENNIS
    elif "/mma/" in url_lower or "/boxing/" in url_lower:
        return SPORT_TYPE_COMBAT
    elif "/cricket/" in url_lower:
        return SPORT_TYPE_CRICKET
    elif "/rugby" in url_lower:  # Matches rugby and rugby-league
        return SPORT_TYPE_RUGBY
    else:
        return SPORT_TYPE_TEAM  # Default: two-team match format (soccer, basketball, lacrosse, etc.)


def get_sport_id_prefix(league_url):
    """
    Extract a unique string for the sport from the URL to prevent ID collisions.
    Example: .../soccer/... -> 'soccer_', .../basketball/... -> 'basketball_'
    """
    if not league_url:
        return "team_"
    # EuroLeague sentinel URL
    if league_url.startswith("euroleague://"):
        return "basketball_"
    if league_url.startswith("epl://"):
        return "soccer_"

    url_lower = league_url.lower()
    parts = url_lower.split('/')
    # ESPN URLs usually look like .../apis/site/v2/sports/{sport}/{league}/...
    if 'sports' in parts:
        try:
            idx = parts.index('sports')
            if idx + 1 < len(parts):
                return parts[idx + 1] + "_"
        except:
            pass

    # Fallback to existing classification
    return get_sport_type(league_url) + "_"


def format_logo_id(prefix, logo_id):
    """Ensure logo ID has prefix without duplicating it if already present."""
    if not logo_id:
        return ""
    s_id = str(logo_id)
    if prefix and s_id.startswith(prefix):
        return s_id
    return (prefix or "") + s_id


def extract_team_logo(team_dict, sport_cdn='soccer', team_id=None):
    """
    Robustly extract logo URL from a team JSON dictionary.
    Supports single 'logo' string, 'logos' array of dicts/strings,
    and falls back to constructed CDN image URL if ID is available.
    """
    if not team_dict or not isinstance(team_dict, dict):
        return "https://a.espncdn.com/i/teamlogos/{}/500/{}.png".format(sport_cdn, team_id) if team_id else ""
    logo = team_dict.get('logo', '')
    if logo and isinstance(logo, str):
        return logo
    logos = team_dict.get('logos', [])
    if logos and isinstance(logos, list) and len(logos) > 0:
        if isinstance(logos[0], dict):
            href = logos[0].get('href', '')
            if href: return href
        elif isinstance(logos[0], str):
            return logos[0]
    if team_id:
        return "https://a.espncdn.com/i/teamlogos/{}/500/{}.png".format(sport_cdn, team_id)
    return ""


def calculate_tennis_scores(competitors, state):
    """
    Calculate sets won for tennis based on completed sets.
    Ignores the current set if match is LIVE.
    Returns strings (score1, score2).
    """
    s1, s2 = 0, 0
    try:
        if len(competitors) < 2:
            return "0", "0"

        # Check if score is already explicitly provided
        c1, c2 = competitors[0], competitors[1]
        sc1 = c1.get('score', '')
        sc2 = c2.get('score', '')

        # If valid scores exist (and at least one is non-zero), trust the API
        # But if both are 0 or empty, we may need to calc (or if it's early match)
        # Actually, ESPN sometimes returns '0' for score but has linescores
        # So we only calc if scores are missing or both 0 AND there are linescores indicating play

        has_linescores = c1.get('linescores') or c2.get('linescores')
        trust_api = (sc1 and sc1 != '0') or (sc2 and sc2 != '0')

        if trust_api:
            return sc1 or '0', sc2 or '0'

        if not has_linescores:
            return sc1 or '0', sc2 or '0'

        # fallback calculation
        ls1 = c1.get('linescores', [])
        ls2 = c2.get('linescores', [])
        count = min(len(ls1), len(ls2))

        for i in range(count):
            # If match is LIVE ('in'), the last set in the list is the current playing set -> Don't count it yet
            is_last = (i == count - 1)
            if is_last and state == 'in':
                continue

            val1 = 0
            val2 = 0
            try:
                val1 = float(ls1[i].get('value', 0))
            except:
                pass
            try:
                val2 = float(ls2[i].get('value', 0))
            except:
                pass

            if val1 > val2:
                s1 += 1
            elif val2 > val1:
                s2 += 1

    except:
        pass
    return str(s1), str(s2)


def get_sport_type_display_name(sport_type):
    """Get human-readable name for sport type"""
    names = {
        SPORT_TYPE_TEAM: "Match",
        SPORT_TYPE_RACING: "Race",
        SPORT_TYPE_GOLF: "Tournament",
        SPORT_TYPE_TENNIS: "Match",
        SPORT_TYPE_COMBAT: "Fight"
    }
    return names.get(sport_type, "Event")


