# ==============================================================================
# UNIFIED MATCH SNAPSHOT BUILDER
# ==============================================================================
def build_match_snapshot(event):
    """
    Convert a raw ESPN event dict into a normalized, display-ready MatchSnapshot.
    Called once per event after process_events_data().
    All UI classes read from this -- never parse raw ESPN dicts themselves.
    """
    status      = event.get('status', {})
    s_type      = status.get('type', {})
    state       = s_type.get('state', 'pre')

    # --- Status Flags ---
    is_canceled   = (s_type.get('name') in ['STATUS_CANCELED', 'STATUS_CANCELLED', 'STATUS_ABANDONED'] or
                     any(x in s_type.get('description', '').lower() for x in ['canceled', 'cancelled', 'abandoned', 'forfeit']))
    is_postponed  = (s_type.get('name') == 'STATUS_POSTPONED' or
                     'postponed' in s_type.get('description', '').lower())
    is_suspended  = (s_type.get('name') in ['STATUS_SUSPENDED', 'STATUS_DELAYED'] or
                     'suspended' in s_type.get('description', '').lower() or
                     'resume'    in s_type.get('description', '').lower() or
                     'delay'     in s_type.get('description', '').lower())

    # --- Status Short Label (Single Definition) ---
    if is_canceled:               status_short = 'CAN'
    elif is_postponed:            status_short = 'PPD'
    elif is_suspended:            status_short = 'SUSP'
    elif state == 'in':           status_short = 'LIVE'
    elif state == 'post':         status_short = 'FIN'
    else:                         status_short = 'SCH'

    # --- Penalty Shootout Detection ---
    short_detail_raw = s_type.get('shortDetail', '') or s_type.get('description', '')
    sd_low = short_detail_raw.lower()
    is_pen_shootout = (state == 'in' and
                       any(x in sd_low for x in ['penalty kick', 'penalties', 'pen. kick', 'shootout']))

    # --- League URL (needed for World Cup checks and clock formatting below) ---
    league_url_early = event.get('league_url', '')

    # --- World Cup stage label default (overwritten below for WC events) ---
    stage_label = ''

    # --- World Cup Host Country Flag (from venue city) ---
    host_flag_url = ''
    host_flag_id  = ''
    if 'fifa.world' in league_url_early:
        comp0  = event.get('competitions', [{}])[0]
        venue  = comp0.get('venue', event.get('venue', {}))
        addr   = venue.get('address', {})
        city      = addr.get('city', '').lower().strip()
        addr_state = addr.get('state', '').lower().strip()  # renamed: must not shadow match 'state'
        iso2      = WC_HOST_CITY_FLAGS.get(city) or WC_HOST_CITY_FLAGS.get(addr_state)
        if iso2:
            host_flag_url = 'https://a.espncdn.com/i/teamlogos/countries/500/{}.png'.format(iso2)
            host_flag_id  = 'wc_host_{}'.format(iso2)
    if 'fifa.world' in league_url_early:
        comp0    = event.get('competitions', [{}])[0]
        rnd      = comp0.get('round', {})
        rnd_text = (rnd.get('text', '') or rnd.get('displayName', '') or '').lower()
        rnd_num  = rnd.get('number', 0)

        if 'final' in rnd_text and 'semi' not in rnd_text and 'third' not in rnd_text and 'quarter' not in rnd_text:
            stage_label = 'FINAL'
        elif 'third' in rnd_text or '3rd' in rnd_text:
            stage_label = '3RD PLACE'
        elif 'semi' in rnd_text:
            stage_label = 'SEMI-FINAL'
        elif 'quarter' in rnd_text:
            stage_label = 'QUARTER-FINAL'
        elif '16' in rnd_text:
            stage_label = 'ROUND OF 16'
        elif '32' in rnd_text:
            stage_label = 'ROUND OF 32'
        elif rnd_text in ('round 1', 'first round') or 'playoff' in rnd_text:
            stage_label = 'ROUND OF 32'
        elif 'group' in rnd_text:
            md = rnd_num if rnd_num else 1
            stage_label = 'GROUP \xb7 MD{}'.format(md)    # e.g. "GROUP · MD2"
        else:
            # Fallback: derive from the match's own date (not system date)
            # so browsing future/past days always shows the correct stage.
            ev_date_str = event.get('date', '')
            if ev_date_str and len(ev_date_str) >= 10:
                try:
                    cur_md = ev_date_str[5:10]   # "YYYY-MM-DD..." -> "MM-DD"
                except Exception:
                    cur_md = time.strftime("%m-%d")
            else:
                cur_md = time.strftime("%m-%d")
            if   "06-11" <= cur_md <= "06-27": stage_label = 'GROUP STAGE'
            elif "06-28" <= cur_md <= "07-03": stage_label = 'ROUND OF 32'
            elif "07-04" <= cur_md <= "07-07": stage_label = 'ROUND OF 16'
            elif "07-08" <= cur_md <= "07-11": stage_label = 'QUARTER-FINAL'
            elif "07-14" <= cur_md <= "07-15": stage_label = 'SEMI-FINAL'
            elif "07-18" <= cur_md <= "07-19": stage_label = 'FINAL'
            else:                               stage_label = 'FIFA WORLD CUP'

    # --- Clock (Multi-Sport Support) ---
    raw_clock    = status.get('displayClock', '')
    short_detail = s_type.get('shortDetail', '') or s_type.get('description', '')
    league_url   = event.get('league_url', '')

    if 'soccer' in league_url:
        # Soccer: use ESPN's shortDetail for rich context
        # (e.g. "45+5'" stoppage time, "HT" half-time, "2nd Half 60'")
        if short_detail:
            clock_display = short_detail
        elif raw_clock and ":" in raw_clock:
            clock_display = raw_clock.split(':')[0] + "'"
        else:
            clock_display = raw_clock or ''
    else:
        # American sports / basketball / hockey / baseball:
        # Use ESPN's own human-readable detail ("2nd Qtr 2:34", "Halftime", etc.)
        clock_display = short_detail or raw_clock or ''

    # --- Team / Player Names & Scores ---
    sport_type   = get_sport_type(league_url)
    comps        = event.get('competitions', [{}])[0].get('competitors', [])

    h_name = 'Home'; a_name = 'Away'
    h_name_short = 'Home'; a_name_short = 'Away'
    h_score_str = '0'; a_score_str = '0'
    h_score_int = 0;  a_score_int = 0
    h_team_id = ''; a_team_id = ''
    h_iso2 = ''; a_iso2 = ''
    h_abbrev = ''; a_abbrev = ''

    if len(comps) >= 2:
        # Identify home/away -- handles missing homeAway tags
        if sport_type == SPORT_TYPE_TENNIS:
            team_h, team_a = comps[0], comps[1]
        else:
            team_h = next((c for c in comps if c.get('homeAway') == 'home'), comps[0])
            team_a = next((c for c in comps if c.get('homeAway') == 'away'),
                          comps[1] if len(comps) > 1 else {})

        # Extract names and flags
        if sport_type in [SPORT_TYPE_TENNIS, SPORT_TYPE_COMBAT]:
            ath_h = team_h.get('athlete', {})
            ath_a = team_a.get('athlete', {})
            h_name       = ath_h.get('displayName') or ath_h.get('shortName') or 'Player 1'
            a_name       = ath_a.get('displayName') or ath_a.get('shortName') or 'Player 2'
            h_name_short = ath_h.get('shortName') or h_name
            a_name_short = ath_a.get('shortName') or a_name
            h_team_id    = str(ath_h.get('id', ''))
            a_team_id    = str(ath_a.get('id', ''))
            h_iso2       = str(ath_h.get('flag', {}).get('iso2', '') or '').lower()
            a_iso2       = str(ath_a.get('flag', {}).get('iso2', '') or '').lower()
        else:
            t_h = team_h.get('team', {}); t_a = team_a.get('team', {})
            h_name       = t_h.get('displayName', 'Home')
            a_name       = t_a.get('displayName', 'Away')
            h_name_short = t_h.get('shortDisplayName') or t_h.get('abbreviation') or h_name
            a_name_short = t_a.get('shortDisplayName') or t_a.get('abbreviation') or a_name
            h_team_id    = str(t_h.get('id', ''))
            a_team_id    = str(t_a.get('id', ''))
            
            h_abbrev = str(t_h.get('abbreviation', '') or '')
            a_abbrev = str(t_a.get('abbreviation', '') or '')
            if h_abbrev: h_iso2 = str(_COUNTRY_ISO2.get(h_abbrev.upper(), '') or '').lower()
            if a_abbrev: a_iso2 = str(_COUNTRY_ISO2.get(a_abbrev.upper(), '') or '').lower()
            if not h_iso2:
                h_c_code = t_h.get('countryCode')
                if not h_c_code:
                    h_c_code = t_h.get('country', {}).get('iso2', '')
                h_iso2 = str(h_c_code or '').lower()
            if not a_iso2:
                a_c_code = t_a.get('countryCode')
                if not a_c_code:
                    a_c_code = t_a.get('country', {}).get('iso2', '')
                a_iso2 = str(a_c_code or '').lower()

        # Extract scores
        if sport_type == SPORT_TYPE_TENNIS:
            h_score_str, a_score_str = calculate_tennis_scores(comps, state)
        else:
            h_score_str = str(team_h.get('score', '0') or '0')
            a_score_str = str(team_a.get('score', '0') or '0')

        try:   h_score_int = int(h_score_str)
        except: h_score_int = 0
        try:   a_score_int = int(a_score_str)
        except: a_score_int = 0

    # --- Score Display String (Single Definition) ---
    if is_canceled:
        score_str = 'C - C'
    elif is_postponed:
        score_str = 'P - P'
    elif state in ('in', 'post') or is_suspended:
        score_str = '{} - {}'.format(h_score_str, a_score_str)
    else:
        score_str = 'VS'

    # --- Time Display String (Single Definition) ---
    if state == 'in' and not is_suspended:
        time_str = clock_display or 'LIVE'
    elif state == 'post':
        time_str = get_local_time_str(event.get('date', ''))
    else:
        time_str = get_local_time_str(event.get('date', ''))

    # --- Red Card Counting (from scoreboard details) ---
    h_red_cards = 0
    a_red_cards = 0
    if state in ('in', 'post') and len(comps) >= 2:
        try:
            details = event.get('competitions', [{}])[0].get('details', [])
            for play in details:
                is_rc = play.get('redCard', False)
                text_desc = play.get('type', {}).get('text', '').lower()
                if is_rc or ('card' in text_desc and 'red' in text_desc):
                    t_id = str(play.get('team', {}).get('id', ''))
                    if t_id == h_team_id:
                        h_red_cards += 1
                    elif t_id == a_team_id:
                        a_red_cards += 1
        except:
            pass

    # --- Possession & Percentage Stats Extraction ---
    h_possession = 0.0
    a_possession = 0.0
    h_pct_stats = []
    a_pct_stats = []
    h_shots_total = 0
    a_shots_total = 0
    h_shots_ot = 0
    a_shots_ot = 0

    if state == 'in' and len(comps) >= 2:
        try:
            # Collect raw stats into dicts for derived percentage computation
            h_raw = {}
            a_raw = {}
            for stat in team_h.get('statistics', []):
                name = stat.get('name', '').lower()
                disp = str(stat.get('displayValue', ''))
                if name == 'possessionpct':
                    h_possession = float(disp or 0)
                else:
                    try: h_raw[name] = float(disp)
                    except: pass
            for stat in team_a.get('statistics', []):
                name = stat.get('name', '').lower()
                disp = str(stat.get('displayValue', ''))
                if name == 'possessionpct':
                    a_possession = float(disp or 0)
                else:
                    try: a_raw[name] = float(disp)
                    except: pass

            # Derive percentage stats from raw counts
            # 1. Shot Accuracy: shotsOnTarget / totalShots * 100
            h_shots = h_raw.get('totalshots', 0)
            a_shots = a_raw.get('totalshots', 0)
            h_on_target = h_raw.get('shotsontarget', 0)
            a_on_target = a_raw.get('shotsontarget', 0)
            h_shots_total = int(h_shots)
            a_shots_total = int(a_shots)
            h_shots_ot = int(h_on_target)
            a_shots_ot = int(a_on_target)
            if h_shots > 0:
                h_pct_stats.append(h_on_target / h_shots * 100.0)
            if a_shots > 0:
                a_pct_stats.append(a_on_target / a_shots * 100.0)

            # 2. Shot Dominance: team shots / total shots * 100
            total_shots = h_shots + a_shots
            if total_shots > 0:
                h_pct_stats.append(h_shots / total_shots * 100.0)
                a_pct_stats.append(a_shots / total_shots * 100.0)

            # 3. Corner Dominance: team corners / total corners * 100
            h_corners = h_raw.get('woncorners', 0)
            a_corners = a_raw.get('woncorners', 0)
            total_corners = h_corners + a_corners
            if total_corners > 0:
                h_pct_stats.append(h_corners / total_corners * 100.0)
                a_pct_stats.append(a_corners / total_corners * 100.0)
        except Exception: pass

    return {
        # Identity
        'event_id':      str(event.get('id', '')),
        'league_name':   event.get('league_name', ''),
        'league_url':    league_url,
        'sport_type':    sport_type,
        'date':          event.get('date', ''),

        # State
        'state':         state,
        'h_poss':        h_possession,
        'a_poss':        a_possession,
        'h_pct_stats':   h_pct_stats,
        'a_pct_stats':   a_pct_stats,
        'h_shots':       h_shots_total,
        'a_shots':       a_shots_total,
        'h_on_target':   h_shots_ot,
        'a_on_target':   a_shots_ot,

        'status_short':  status_short,
        'is_live':       state == 'in' and not is_suspended,
        'is_postponed':  is_postponed,
        'is_suspended':  is_suspended,
        'clock':         clock_display,
        'period':        status.get('period', 0),

        # Teams
        'h_name':        h_name,
        'a_name':        a_name,
        'h_name_disp':   _team_name(h_name),
        'a_name_disp':   _team_name(a_name),
        'h_name_short':  h_name_short,
        'a_name_short':  a_name_short,
        'h_team_id':     h_team_id,
        'a_team_id':     a_team_id,
        'h_abbrev':      h_abbrev,
        'a_abbrev':      a_abbrev,

        # Scores
        'h_score_str':   h_score_str,
        'a_score_str':   a_score_str,
        'h_score_int':   h_score_int,
        'a_score_int':   a_score_int,
        'score_str':     score_str,     # "2 - 1" or "VS" or "P - P"
        'time_str':      time_str,      # "45'" or "FT" or "20:30"

        # Logos (already set by process_events_data)
        'h_logo_url':    event.get('h_logo_url', ''),
        'a_logo_url':    event.get('a_logo_url', ''),
        'l_logo_url':    event.get('l_logo_url', ''),
        'h_logo_id':     event.get('h_logo_id', ''),
        'a_logo_id':     event.get('a_logo_id', ''),
        'l_logo_id':     event.get('l_logo_id', ''),

        # Red Cards
        'h_red_cards':   h_red_cards,
        'a_red_cards':   a_red_cards,

        # World Cup extras
        'stage_label':      stage_label,
        'is_pen_shootout':  is_pen_shootout,
        'host_flag_url':    host_flag_url,
        'host_flag_id':     host_flag_id,
        'h_iso2':           h_iso2,
        'a_iso2':           a_iso2,

        # Raw event reference (for GameInfoScreen detail requests only)
        'raw_event':     event,
    }


def snapshot_passes_filter(snap, filter_mode, today, tomorrow, yesterday):
    """Shared filter for all UI screens. filter_mode: 0=Yesterday, 1=Live, 2=Today, 3=Tomorrow, 4=All"""
    import datetime, calendar, time
    state    = snap['state']
    ev_date  = snap['date'][:10] if snap['date'] else ''
    
    # Convert UTC date string (e.g. "2026-06-13T01:00Z") to local date representation
    utc_str = snap.get('date', '')
    if utc_str and 'T' in utc_str:
        try:
            date_part, time_part = utc_str.split('T')
            y, m, d = map(int, date_part.split('-'))
            time_part = time_part.replace('Z', '')
            H, M = map(int, time_part.split(':')[:2])
            dt_utc = datetime.datetime(y, m, d, H, M)
            timestamp = calendar.timegm(dt_utc.timetuple())
            local_dt = datetime.datetime.fromtimestamp(timestamp)
            ev_date = local_dt.strftime("%Y-%m-%d")
        except:
            pass

    # For racing: check date range if endDate exists
    is_racing = snap.get('sport_type') == SPORT_TYPE_RACING
    ev_end_date = ev_date
    if is_racing:
        raw_evt = snap.get('raw_event', {})
        end_utc = raw_evt.get('endDate', '')
        if end_utc and 'T' in end_utc:
            try:
                date_part, time_part = end_utc.split('T')
                y, m, d = map(int, date_part.split('-'))
                time_part = time_part.replace('Z', '')
                H, M = map(int, time_part.split(':')[:2])
                dt_utc = datetime.datetime(y, m, d, H, M)
                timestamp = calendar.timegm(dt_utc.timetuple())
                local_dt = datetime.datetime.fromtimestamp(timestamp)
                ev_end_date = local_dt.strftime("%Y-%m-%d")
            except:
                ev_end_date = end_utc[:10]
        elif end_utc:
            ev_end_date = end_utc[:10]

    if is_racing:
        if filter_mode == 0 and not (ev_date <= yesterday <= ev_end_date): return False
        if filter_mode == 1 and state != 'in': return False
        if filter_mode == 2 and not (ev_date <= today <= ev_end_date) and state != 'in': return False
        if filter_mode == 3 and not (ev_date <= tomorrow <= ev_end_date): return False
    else:
        if filter_mode == 0 and ev_date != yesterday: return False
        if filter_mode == 1 and state != 'in':        return False
        if filter_mode == 2 and ev_date != today and state != 'in': return False
        if filter_mode == 3 and ev_date != tomorrow:  return False
    return True


# ==============================================================================
# EPL LOGO RESOLVER HELPERS (FIRST CHOICE & FALLBACK ARCHITECTURE)
# ==============================================================================
def get_bundled_epl_logo_path():
    """
    First choice resolver for Egyptian Premier League logo.
    Discovers the bundled epl_logo.png shipped with the plugin package.
    """
    candidates = []
    try:
        if 'resolveFilename' in globals() and 'SCOPE_PLUGINS' in globals():
            candidates.append(resolveFilename(SCOPE_PLUGINS, "Extensions/SimplySports/epl_logo.png"))
            candidates.append(resolveFilename(SCOPE_PLUGINS, "Extensions/SimplySports/icons/epl_logo.png"))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.path.dirname(__file__), "epl_logo.png"))
        candidates.append(os.path.join(os.path.dirname(__file__), "icons", "epl_logo.png"))
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "epl_logo.png"))
    except Exception:
        pass
    candidates.append("/usr/lib/enigma2/python/Plugins/Extensions/SimplySports/epl_logo.png")

    for cand in candidates:
        try:
            if cand and os.path.exists(cand) and os.path.getsize(cand) > 100:
                return cand
        except Exception:
            pass
    return None


def is_epl_logo_request(url, img_id):
    """
    Returns True if the requested logo belongs to the Egyptian Premier League.
    """
    s_id = str(img_id or '').lower()
    s_url = str(url or '').lower()
    if s_id in ('league_epl', 'epl') or s_id.startswith('league_epl'):
        return True
    if 'egyptianproleague' in s_url or s_url.startswith('epl://') or 'epl_logo.png' in s_url:
        return True
    return False


# ==============================================================================
# UNIFIED LOGO LOADER
# ==============================================================================
def load_logo_to_widget(screen, widget_name, url, img_id=None, on_loaded=None, keep_existing=False):
    """
    Single shared logo loader used by ALL screens.
    Uses ID-based filename. Falls back to URL hash.
    Checks file cache first, then downloads asynchronously.
    """
    if not url:
        try: screen[widget_name].hide()
        except: pass
        return

    if not img_id or img_id in ('0', ''):
        img_id = hashlib.md5(url.encode('utf-8')).hexdigest()[:12]

    cache_dir = LOGO_CACHE_DIR + "/"
    file_path = cache_dir + str(img_id) + ".png"

    # -------------------------------------------------------------------------
    # CHOICE 1 (PRIMARY): Use bundled epl_logo.png for Egyptian Premier League
    # -------------------------------------------------------------------------
    if is_epl_logo_request(url, img_id):
        bundled_epl = get_bundled_epl_logo_path()
        if bundled_epl:
            import shutil
            try:
                if not os.path.exists(cache_dir): os.makedirs(cache_dir)
                if not os.path.exists(file_path) or os.path.getsize(file_path) < 100:
                    shutil.copyfile(bundled_epl, file_path)
            except Exception:
                pass
            try:
                active_src = file_path if (os.path.exists(file_path) and os.path.getsize(file_path) > 100) else bundled_epl
                ptr = GLOBAL_PIXMAP_CACHE.get(active_src)
                if not ptr and LoadPixmap:
                    ptr = LoadPixmap(cached=True, path=active_src)
                    if ptr: GLOBAL_PIXMAP_CACHE[active_src] = ptr
                if ptr and screen[widget_name].instance:
                    screen[widget_name].instance.setPixmap(ptr)
                    screen[widget_name].instance.setScale(1)
                elif screen[widget_name].instance:
                    screen[widget_name].instance.setPixmapFromFile(active_src)
                    screen[widget_name].instance.setScale(1)
                screen[widget_name].show()
                if on_loaded: on_loaded()
                return
            except Exception:
                pass

    # -------------------------------------------------------------------------
    # CHOICE 2 (FALLBACK): Serve from disk cache (100-byte minimum to reject corrupt files)
    # -------------------------------------------------------------------------
    if os.path.exists(file_path) and os.path.getsize(file_path) > 100:
        # Validate PNG magic bytes (\x89PNG) — a 404/HTML error page saved by a
        # previous failed download passes the size check but cannot be loaded as
        # a pixmap.  Delete it so we fall through to a fresh download.
        try:
            with open(file_path, 'rb') as _f:
                _magic = _f.read(4)
            if _magic != b'\x89PNG':
                os.remove(file_path)
                if file_path in GLOBAL_PIXMAP_CACHE:
                    del GLOBAL_PIXMAP_CACHE[file_path]
                raise ValueError("stale cache")
        except (IOError, ValueError):
            pass  # fall through to download below
        else:
            try:
                ptr = GLOBAL_PIXMAP_CACHE.get(file_path)
                if not ptr and LoadPixmap:
                    ptr = LoadPixmap(cached=True, path=file_path)
                    if ptr: GLOBAL_PIXMAP_CACHE[file_path] = ptr
                if ptr:
                    if screen[widget_name].instance:
                        screen[widget_name].instance.setPixmap(ptr)
                        screen[widget_name].instance.setScale(1)
                elif screen[widget_name].instance:
                    screen[widget_name].instance.setPixmapFromFile(file_path)
                    screen[widget_name].instance.setScale(1)
                screen[widget_name].show()
                if on_loaded: on_loaded()
            except: pass
            return

    # Download asynchronously
    def _on_done(data):
        try:
            if not (os.path.exists(file_path) and os.path.getsize(file_path) > 100):
                return
            # Validate PNG magic bytes (\x89PNG)
            try:
                with open(file_path, 'rb') as _f:
                    _magic = _f.read(4)
                if _magic != b'\x89PNG':
                    os.remove(file_path)
                    return
            except:
                try: os.remove(file_path)
                except: pass
                return
            GLOBAL_VALID_LOGO_PATHS.add(file_path)
            ptr = None
            if LoadPixmap:
                ptr = LoadPixmap(cached=True, path=file_path)
                if ptr: GLOBAL_PIXMAP_CACHE[file_path] = ptr
            if ptr:
                if screen[widget_name].instance:
                    screen[widget_name].instance.setPixmap(ptr)
                    screen[widget_name].instance.setScale(1)
            elif screen[widget_name].instance:
                screen[widget_name].instance.setPixmapFromFile(file_path)
                screen[widget_name].instance.setScale(1)
            screen[widget_name].show()
            if on_loaded: on_loaded()
        except: pass

    if not keep_existing:
        try: screen[widget_name].hide()
        except: pass
    def _fallback_download(err=None):
        def _thread_fallback():
            try:
                import urllib.request as _urllib, ssl as _ssl
                _ctx = _ssl.create_default_context()
                _ctx.check_hostname = False
                _ctx.verify_mode = _ssl.CERT_NONE
                _req = _urllib.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'})
                with _urllib.urlopen(_req, context=_ctx, timeout=8) as _resp:
                    _data = _resp.read()
                    if _data and len(_data) > 100:
                        with open(file_path, 'wb') as _f: _f.write(_data)
                        reactor.callFromThread(_on_done, _data)
            except Exception:
                pass
        _t = threading.Thread(target=_thread_fallback)
        _t.daemon = True
        _t.start()

    try:
        headers = {b'User-Agent': b'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        downloadPage(url.encode('utf-8'), file_path, headers=headers, timeout=10).addCallback(_on_done).addErrback(_fallback_download)
    except:
        try:
            downloadPage(url.encode('utf-8'), file_path).addCallback(_on_done).addErrback(_fallback_download)
        except:
            _fallback_download()


# ==============================================================================
# LOGO CACHE MANAGER (OPTIMIZED: Non-Blocking)
# ==============================================================================
class LogoCacheManager:
    """Manages local caching of team logos with delayed auto-cleanup"""
    @profile_function("LogoCacheManager")
    def __init__(self):
        self.cache_dir = LOGO_CACHE_DIR
        self._ensure_cache_dir()

        # Populate in-memory valid logo paths
        try:
            if os.path.exists(self.cache_dir):
                for filename in os.listdir(self.cache_dir):
                    if filename.endswith('.png'):
                        GLOBAL_VALID_LOGO_PATHS.add(os.path.join(self.cache_dir, filename))
            # Also check /tmp/simplysports/logos
            tmp_dir = "/tmp/simplysports/logos/"
            if os.path.exists(tmp_dir):
                for filename in os.listdir(tmp_dir):
                    if filename.endswith('.png'):
                        GLOBAL_VALID_LOGO_PATHS.add(os.path.join(tmp_dir, filename))
        except: pass

        # OPTIMIZATION: Run pruning 60 seconds AFTER startup to avoid blocking boot
        self.prune_timer = eTimer()
        try:
            self.prune_timer.callback.append(self._prune_cache)
        except AttributeError:
            self.prune_timer.timeout.get().append(self._prune_cache)
        self.prune_timer.start(60000, True)

    def _ensure_cache_dir(self):
        try:
            if not os.path.exists(self.cache_dir):
                os.makedirs(self.cache_dir)
        except: pass

    @profile_function("LogoCacheManager")
    def _prune_cache(self, days=7):
        """Delete files older than 'days'"""
        try:
            now = time.time()
            cutoff = now - (days * 86400)
            if not os.path.exists(self.cache_dir): return

            # Limit the number of files we check to prevent freezing
            count = 0
            for filename in os.listdir(self.cache_dir):
                if count > 50: break # Only check a batch at a time
                file_path = os.path.join(self.cache_dir, filename)
                if os.path.isfile(file_path):
                    if os.path.getmtime(file_path) < cutoff:
                        os.remove(file_path)
                        GLOBAL_VALID_LOGO_PATHS.discard(file_path)
                count += 1
        except: pass


