global_sports_monitor = None


# ==============================================================================
# UTILS
# ==============================================================================
def _spread_to_probs(spread, league_url):
    """Rough WIN/DRAW/WIN estimate from a point spread alone, when no
    moneyline is quoted anywhere (e.g. DraftKings soccer listings that only
    show '-0.5 | O/U 2.5'). This is a genuine statistical approximation, not
    a lookup of a real quoted probability - callers must label it as an
    estimate rather than a 'prediction'.

    Model: assume the eventual (home - away) margin is Normally distributed
    around -spread (ESPN convention: negative spread = home favored) with a
    sport-typical standard deviation, then use the standard continuity
    correction (+/-0.5) to get P(home win) / P(draw) / P(away win) from that
    continuous distribution. Sigma values are commonly-cited rough figures
    for each sport's scoring variance, not precisely calibrated - treat the
    output as a directional estimate, not a hard number.
    """
    try:
        spread = float(spread)
    except (TypeError, ValueError):
        return None
    url_l = (league_url or '').lower()
    if 'soccer' in url_l:
        sigma = 1.3; has_draw = True
    elif 'hockey' in url_l or 'nhl' in url_l:
        sigma = 1.6; has_draw = False
    elif 'basketball' in url_l or 'nba' in url_l or 'ncaab' in url_l or 'fiba' in url_l or 'euroleague' in url_l:
        sigma = 11.0; has_draw = False
    elif 'football' in url_l or 'nfl' in url_l or 'ncaaf' in url_l:
        sigma = 13.5; has_draw = False
    else:
        sigma = 10.0; has_draw = False

    def _phi(x):
        return 0.5 * (1.0 + math.erf(x / math.sqrt(2)))

    mean = -spread  # expected home margin
    if has_draw:
        p_home = 1.0 - _phi((0.5 - mean) / sigma)
        p_away = _phi((-0.5 - mean) / sigma)
    else:
        p_home = 1.0 - _phi((0.0 - mean) / sigma)
        p_away = 1.0 - p_home
    total = p_home + p_away
    if total <= 0:
        return None
    return (p_home / total) * 100.0, (p_away / total) * 100.0


def _moneyline_to_prob(moneyline):
    """Standard American-odds -> implied win probability (still includes the
    book's vig at this point; callers normalize across all quoted outcomes to
    strip it out). Returns None if moneyline isn't a usable number."""
    try:
        ml = float(moneyline)
    except (TypeError, ValueError):
        return None
    if ml == 0:
        return 0.5
    if ml > 0:
        return 100.0 / (ml + 100.0)
    return (-ml) / ((-ml) + 100.0)


def extract_win_prediction_from_event(event):
    if not isinstance(event, dict):
        return 0.0, 0.0

    # 1. Direct predictor inside event
    predictor = event.get('predictor', {})
    if predictor and isinstance(predictor, dict):
        h_pred = predictor.get('homeTeam', {}) or {}
        a_pred = predictor.get('awayTeam', {}) or {}
        h_prob = h_pred.get('gameProjection') or h_pred.get('chanceToWin') or 0
        a_prob = a_pred.get('gameProjection') or a_pred.get('chanceToWin') or 0
        try:
            hv, av = float(h_prob), float(a_prob)
            if hv > 0 or av > 0:
                return hv, av
        except: pass

    # 2. Competitions odds
    comps = event.get('competitions', [{}])
    if comps and isinstance(comps, list):
        comp = comps[0]
        odds_list = comp.get('odds', []) or []
        for odd in odds_list:
            if not isinstance(odd, dict): continue

            # a) winProbability array
            win_prob = odd.get('winProbability', [])
            if win_prob and isinstance(win_prob, list):
                wp = win_prob[0]
                if isinstance(wp, dict) and 'homeWinPercentage' in wp:
                    h_pct = float(wp.get('homeWinPercentage', 0.5)) * 100.0
                    a_pct = (1.0 - float(wp.get('homeWinPercentage', 0.5))) * 100.0
                    return h_pct, a_pct

            # b) homeTeamOdds / awayTeamOdds winPercentage
            h_odds = odd.get('homeTeamOdds', {}) or {}
            a_odds = odd.get('awayTeamOdds', {}) or {}
            if 'winPercentage' in h_odds or 'winPercentage' in a_odds:
                try:
                    hv = float(h_odds.get('winPercentage', 0))
                    av = float(a_odds.get('winPercentage', 0))
                    if hv > 0 or av > 0:
                        return hv, av
                except: pass

            # c) moneyline in odds
            h_ml = h_odds.get('moneyLine')
            a_ml = a_odds.get('moneyLine')
            d_ml = (odd.get('drawOdds', {}) or {}).get('moneyLine')

            # Or nested moneyline object
            ml_obj = odd.get('moneyline', {}) or {}
            if isinstance(ml_obj, dict):
                if not h_ml: h_ml = ml_obj.get('home', {}).get('close', {}).get('odds') or ml_obj.get('home', {}).get('open', {}).get('odds')
                if not a_ml: a_ml = ml_obj.get('away', {}).get('close', {}).get('odds') or ml_obj.get('away', {}).get('open', {}).get('odds')

            h_p = _moneyline_to_prob(h_ml)
            a_p = _moneyline_to_prob(a_ml)
            if h_p is not None and a_p is not None:
                d_p = _moneyline_to_prob(d_ml) if d_ml is not None else 0.0
                tot = h_p + a_p + (d_p or 0.0)
                if tot > 0:
                    return (h_p / tot) * 100.0, (a_p / tot) * 100.0

            # d) details spread (e.g. "ARS -650" or "ALA +135" or "-1.5")
            details = odd.get('details', '')
            if details:
                import re
                m_ml = re.search(r'([A-Z]{2,4})\s*([+-]\d{3,4})', details)
                if m_ml:
                    team_abbr = m_ml.group(1)
                    ml_val = float(m_ml.group(2))
                    fav_prob = _moneyline_to_prob(ml_val)
                    if fav_prob:
                        comps_teams = comp.get('competitors', [])
                        h_abbr = comps_teams[0].get('team', {}).get('abbreviation', '') if len(comps_teams) > 0 else ''
                        if h_abbr == team_abbr:
                            return fav_prob * 100.0, (1.0 - fav_prob) * 100.0
                        else:
                            return (1.0 - fav_prob) * 100.0, fav_prob * 100.0

    return 0.0, 0.0


def parse_espn_date(date_str):
    if not date_str:
        return None
    try:
        clean = str(date_str).replace("Z", "").replace("T", " ").strip()
        if "." in clean:
            clean = clean.split(".")[0]

        import datetime
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d", "%d/%m/%Y %H:%M", "%Y/%m/%d %H:%M"):
            try:
                return datetime.datetime.strptime(clean, fmt)
            except ValueError:
                pass

        parts = clean.split(" ")
        d_parts = parts[0].split("-")
        t_parts = parts[1].split(":") if len(parts) > 1 else [0, 0]
        return datetime.datetime(int(d_parts[0]), int(d_parts[1]), int(d_parts[2]), int(t_parts[0]), int(t_parts[1]))
    except Exception:
        return None


def get_local_datetime(utc_date_str):
    """Same parsing as get_local_time_str but returns a local datetime object
    (or None). Used for the 'Next match in Xm' countdown."""
    try:
        if utc_date_str and 'T' in utc_date_str:
            date_part, time_part = utc_date_str.split('T')
            y, m, d = map(int, date_part.split('-'))
            time_part = time_part.replace('Z', '')
            H, M = map(int, time_part.split(':')[:2])
            dt_utc = datetime.datetime(y, m, d, H, M)
            timestamp = calendar.timegm(dt_utc.timetuple())
            return datetime.datetime.fromtimestamp(timestamp)
    except Exception:
        pass
    return None


def format_countdown(delta_seconds):
    """Compact 'in Xm' / 'in Xh Ym' / 'in Xd' style countdown string."""
    delta_seconds = int(delta_seconds)
    if delta_seconds < 60:
        return _t("in <1m")
    minutes = delta_seconds // 60
    if minutes < 60:
        return _t("in {}m").format(minutes)
    hours, mins = divmod(minutes, 60)
    if hours < 24:
        return _t("in {}h {}m").format(hours, mins) if mins else _t("in {}h").format(hours)
    days = hours // 24
    return _t("in {}d").format(days)


def get_local_time_str(utc_date_str):
    try:
        if 'T' in utc_date_str:
            date_part, time_part = utc_date_str.split('T')
            y, m, d = map(int, date_part.split('-'))
            time_part = time_part.replace('Z', '')
            H, M = map(int, time_part.split(':')[:2])
            dt_utc = datetime.datetime(y, m, d, H, M)
            timestamp = calendar.timegm(dt_utc.timetuple())
            local_dt = datetime.datetime.fromtimestamp(timestamp)
            now = datetime.datetime.now()
            time_str = "{:02d}:{:02d}".format(local_dt.hour, local_dt.minute)
            if local_dt.date() == now.date(): return str(time_str)
            else: return local_dt.strftime("%a %d/%m") + " " + time_str
    except:
        return "--:--"


def get_league_abbr(full_name):
    if not full_name: return ""
    return full_name[:3].upper()


def is_system_screen_active(session):
    """
    Returns True ONLY when an Enigma2 system menu, setup screen, channel list,
    EPG, virtual keyboard, or 3rd-party plugin window is currently active and focused.
    Returns False (= notifications allowed) when the user is on:
      - Live TV / MoviePlayer (idle)
      - Any SimplySport plugin screen or minibar
      - Any SimplySport toast / notification overlay
    """
    if not session:
        return False
    try:
        PLUGIN_SCREENS = {
            # Main screens
            "SimpleSportsScreen",
            "GameInfoScreen",
            "TeamStandingScreen",
            "TeamRostersScreen",
            "LeaderboardScreen",
            "BroadcastingChannelsScreen",
            "AthleteProfileScreen",
            "WatchPartyScreen",
            "PersonalProfileScreen",
            "RacingDriverInfoScreen",
            "SimplePlayer",
            # Selectors & managers
            "LeagueSelector",
            "FavoriteLeagueSelector",
            "FavoriteTeamLeagueSelector",
            "FavoriteTeamPickerScreen",
            "FavoriteTeamsManagerScreen",
            # LiveScore CZ screens
            "LiveScoreCZScreen",
            "LiveScoreCZGameInfoScreen",
            "LiveScoreCZTeamStandingScreen",
            # Mini bars
            "SimpleSportsMiniBar",
            "SimpleSportsMiniBar2",
            "LiveScoreCZMiniBar3",
            "RacingMiniBar",
            # Toasts & notifications (transient overlays)
            "GoalToast",
            "FavTeamToast",
            "AIToast",
            "LiveScoreFollowToast",
            "AIToastSimple",
            "ZapNotificationScreen",
        }

        TV_WATCHING_CLASSES = {
            "InfoBar",
            "MoviePlayer",
            "TimeshiftState",
            "PVRState",
            "Volume",
            "Mute",
            "UnhandledKey",
            "Dish",
            "RdsInfoDisplay",
            "Subtitles",
        }

        # 1. Quick check: Enigma2 topmost focused dialog
        top_dialog = getattr(session, "current_dialog", None)
        if top_dialog:
            cls = top_dialog.__class__.__name__
            if cls in PLUGIN_SCREENS or cls in TV_WATCHING_CLASSES:
                return False

        dialog_stack = getattr(session, "dialog_stack", None)
        if not dialog_stack:
            return False

        # In Enigma2 (openATV, openPLi, VTi, DreamOS), dialog_stack is a list of (dialog, flags) tuples
        for item in reversed(dialog_stack):
            if not item:
                continue
            dialog = item[0] if isinstance(item, (tuple, list)) else item
            if not dialog:
                continue

            # Only check screens that are actively executing / in foreground
            if hasattr(dialog, "execing") and not dialog.execing:
                continue

            cls_name = dialog.__class__.__name__

            # Our own plugin screens / minibars / toasts -> Always allow
            if cls_name in PLUGIN_SCREENS:
                return False

            # Normal TV watching overlays -> Continue checking stack
            if cls_name in TV_WATCHING_CLASSES:
                continue

            # Any other active modal window (Menu, Setup, ChannelSelection, EPG, 3rd party plugins)
            return True

        return False
    except Exception as e:
        print("[SimplySport] is_system_screen_active error: {}".format(e))
        return False


def safe_connect(timer_obj, func):
    """Safely connects a timer function across different Enigma2 versions"""
    if hasattr(timer_obj, 'callback'):
        timer_obj.callback.append(func)
    else:
        try:
            timer_obj.timeout.get().append(func)
        except AttributeError:
            timer_obj.timeout.append(func)


GLOBAL_PIXMAP_CACHE = collections.OrderedDict()
GLOBAL_PIXMAP_CACHE_LIMIT = 500
GLOBAL_VALID_LOGO_PATHS = set()


def get_scaled_pixmap(path, width, height):
    """Load and return a scaled pixmap from file path, cached safely in memory alongside its ePicLoad instance."""
    if not path: return None
    cache_key = "{}_{}x{}".format(path, width, height)

    if cache_key in GLOBAL_PIXMAP_CACHE:
        val = GLOBAL_PIXMAP_CACHE.pop(cache_key)
        GLOBAL_PIXMAP_CACHE[cache_key] = val
        return val[0]

    try:
        from enigma import ePicLoad
        sc = ePicLoad()
        # 6th param = 0 (disable background padding color to force transparent scaling)
        sc.setPara((width, height, 1, 1, 0, 0, "#00000000"))
        if sc.startDecode(path, 0, 0, False) == 0:
            ptr = sc.getData()
            if ptr:
                if len(GLOBAL_PIXMAP_CACHE) >= GLOBAL_PIXMAP_CACHE_LIMIT:
                    GLOBAL_PIXMAP_CACHE.popitem(last=False)
                GLOBAL_PIXMAP_CACHE[cache_key] = (ptr, sc)
                return ptr
    except: pass

    # Fallback to standard LoadPixmap if ePicLoad fails
    if LoadPixmap:
        try:
            ptr = LoadPixmap(cached=True, path=path)
            if ptr:
                if len(GLOBAL_PIXMAP_CACHE) >= GLOBAL_PIXMAP_CACHE_LIMIT:
                    GLOBAL_PIXMAP_CACHE.popitem(last=False)
                GLOBAL_PIXMAP_CACHE[cache_key] = (ptr, None)
                return ptr
        except: pass
    return None


# ==============================================================================
# LIST RENDERERS
# ==============================================================================
def draw_rounded_box(res, x, y, w, h, border_color, fill_color, is_solid):
    """Draw a box with rounded top-left and bottom-right corners (arched from middle height, convex/outward circular curvature from plugin6.4.3.py).
    Groups contiguous scanlines into horizontal rectangle bands for optimal performance."""
    import math
    if h < 6 or w < 6:
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x, y, w, h, 0, RT_HALIGN_CENTER, "", border_color, border_color, border_color, border_color))
        return

    h_half = h // 2
    max_dx = min(15, w // 2)

    scanlines = []
    for i in range(h):
        if i < h_half:
            t = 1.0 - float(i) / h_half
            dx_left = int(round(max_dx * (1.0 - math.sqrt(max(0.0, 1.0 - t ** 2)))))
            dx_right = 0
        else:
            k = h - 1 - i
            t = 1.0 - float(k) / h_half
            dx_left = 0
            dx_right = int(round(max_dx * (1.0 - math.sqrt(max(0.0, 1.0 - t ** 2)))))
        scanlines.append((dx_left, dx_right))

    grouped = []
    curr_left, curr_right = scanlines[0]
    curr_h = 0
    curr_y = 0
    for i, (l, r) in enumerate(scanlines):
        if l == curr_left and r == curr_right:
            curr_h += 1
        else:
            grouped.append((curr_y, curr_h, curr_left, curr_right))
            curr_y = i
            curr_h = 1
            curr_left, curr_right = l, r
    grouped.append((curr_y, curr_h, curr_left, curr_right))

    if is_solid:
        c = border_color
        for gy, gh, dl, dr in grouped:
            res.append((eListboxPythonMultiContent.TYPE_TEXT, x + dl, y + gy, w - dl - dr, gh, 0, RT_HALIGN_CENTER, "", c, c, c, c))
    else:
        c_b = border_color
        c_f = fill_color
        for gy, gh, dl, dr in grouped:
            res.append((eListboxPythonMultiContent.TYPE_TEXT, x + dl, y + gy, w - dl - dr, gh, 0, RT_HALIGN_CENTER, "", c_b, c_b, c_b, c_b))
        if w > 4 and h > 4:
            bw = 1
            for gy, gh, dl, dr in grouped:
                if gy > 0 and gy < h - 1:
                    in_x = x + dl + bw
                    in_w = w - dl - dr - 2 * bw
                    if in_w > 0:
                        res.append((eListboxPythonMultiContent.TYPE_TEXT, in_x, y + gy, in_w, gh, 0, RT_HALIGN_CENTER, "", c_f, c_f, c_f, c_f))


def draw_card(res, x, y, w, h, radius, fill, fill_sel, border=None, border_sel=None, border_w=2):
    """Draw a flat card rectangle (optimised: max 5 TYPE_TEXT tuples instead of one-per-scanline).
    The old per-pixel rounded-corner scanlines generated hundreds of tuples and overflowed
    Enigma2's eListboxPythonMultiContent element limit, silently dropping later elements
    (scoreboxes, status text, stat bars).  A flat rectangle is visually identical at TV distance."""
    if border is None: border = fill
    if border_sel is None: border_sel = fill_sel
    if border_w <= 0 or border == fill:
        # No visible border — single solid fill rectangle
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x, y, w, h, 0, RT_HALIGN_CENTER, "", fill, fill_sel, fill, fill_sel))
    else:
        # Border + fill — 4 border edges + 1 inner fill = 5 tuples
        # Top border
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x, y, w, border_w, 0, RT_HALIGN_CENTER, "", border, border_sel, border, border_sel))
        # Bottom border
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x, y + h - border_w, w, border_w, 0, RT_HALIGN_CENTER, "", border, border_sel, border, border_sel))
        # Left border
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x, y + border_w, border_w, h - 2 * border_w, 0, RT_HALIGN_CENTER, "", border, border_sel, border, border_sel))
        # Right border
        res.append((eListboxPythonMultiContent.TYPE_TEXT, x + w - border_w, y + border_w, border_w, h - 2 * border_w, 0, RT_HALIGN_CENTER, "", border, border_sel, border, border_sel))
        # Inner fill
        inner_w = w - 2 * border_w
        inner_h = h - 2 * border_w
        if inner_w > 0 and inner_h > 0:
            res.append((eListboxPythonMultiContent.TYPE_TEXT, x + border_w, y + border_w, inner_w, inner_h, 0, RT_HALIGN_CENTER, "", fill, fill_sel, fill, fill_sel))


