def SelectionListEntry(name, is_selected, logo_path=None, mode="multi", heart=None):
    """
    heart=None  → no heart shown  (multi / normal single mode)
    heart=False → empty heart ♡  (not yet a favourite — very dim)
    heart=True  → filled heart ♥  (marked as favourite — bright red)
    """
    col_sel = 0x00FF85 if is_selected else 0x9E9E9E
    text_col = 0xFFFFFF if is_selected else 0x9E9E9E
    res = [(name, is_selected)]

    base_x = 15
    if mode == "multi":
        check_mark = "[x]" if is_selected else "[ ]"
        res.append((eListboxPythonMultiContent.TYPE_TEXT, base_x, 5, 40, 40, 0, RT_HALIGN_CENTER|RT_VALIGN_CENTER, check_mark, col_sel, col_sel, None, None))
        base_x += 55
    else:
        text_col = 0xFFFFFF # Always bright for single mode

    # Add logo if available
    text_x = base_x
    if logo_path:
        cache_key = "{}_{}x{}".format(logo_path, 35, 35)
        if cache_key in GLOBAL_PIXMAP_CACHE:
            pixmap = GLOBAL_PIXMAP_CACHE[cache_key][0]
            if pixmap:
                res.append((eListboxPythonMultiContent.TYPE_PIXMAP_ALPHATEST, base_x, 7, 35, 35, pixmap))
                text_x = base_x + 45
        else:
            is_valid = logo_path in GLOBAL_VALID_LOGO_PATHS
            if not is_valid and os.path.exists(logo_path) and os.path.getsize(logo_path) > 0:
                GLOBAL_VALID_LOGO_PATHS.add(logo_path)
                is_valid = True

            if is_valid:
                try:
                    # Resize image to fit 35x35
                    pixmap = get_scaled_pixmap(logo_path, 35, 35)
                    if pixmap:
                        res.append((eListboxPythonMultiContent.TYPE_PIXMAP_ALPHATEST, base_x, 7, 35, 35, pixmap))
                        text_x = base_x + 45  # Shift text after logo
                except:
                    pass

    # Name text — leave space on the right for the heart if needed
    name_width = 700 - (text_x - 70)
    if heart is not None:
        name_width -= 55  # reserve space for heart symbol on the right
    res.append((eListboxPythonMultiContent.TYPE_TEXT, text_x, 5, name_width, 40, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, name, text_col, text_col, None, None))

    # Heart symbol on the right edge
    # heart=True  → filled ♥ in bright red (league IS a favourite)
    # heart=False → empty  ♡ in near-invisible dark (not a favourite — just a placeholder)
    if heart is not None:
        if heart:
            heart_char = u"\u2665"   # ♥ filled  (selected)
            heart_col  = 0xCC2222    # safe dark-red: avoids the ARGB-transparent 0x00xxxxxx trap
        else:
            heart_char = u"\u2661"   # ♡ empty   (not selected)
            heart_col  = 0x2D2D2D    # nearly invisible on dark background
        res.append((eListboxPythonMultiContent.TYPE_TEXT, 820, 5, 50, 40, 0, RT_HALIGN_CENTER|RT_VALIGN_CENTER, heart_char, heart_col, heart_col, None, None))

    return res

def LeaderboardListEntry(rank, name, score, is_me=False):
    # Colors: Gold for 1st, Accent for others. Cyan for ME.
    c_text = 0xffffff
    c_accent = 0x00FF85
    c_gold = 0xFFD700
    c_me = 0xc9a020
    c_sel = c_accent

    res = [(rank, name, score, is_me)]
    h = 60

    # 1. Rank
    rank_color = c_gold if rank == 1 else c_accent
    res.append((eListboxPythonMultiContent.TYPE_TEXT, 20, 0, 100, h, 0, RT_HALIGN_CENTER|RT_VALIGN_CENTER, "#" + str(rank), rank_color, c_sel))

    # 2. Name
    name_color = c_me if is_me else c_text
    res.append((eListboxPythonMultiContent.TYPE_TEXT, 140, 0, 560, h, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, name, name_color, c_sel))

    # 3. Score
    res.append((eListboxPythonMultiContent.TYPE_TEXT, 720, 0, 200, h, 0, RT_HALIGN_RIGHT|RT_VALIGN_CENTER, str(score) + " pts", c_text, c_sel))

    return res


class AIToast(Screen):
    """Non-invasive AI Mode notification ticker that appears at the bottom."""
    def __init__(self, session, text, duration_ms=10000):
        from enigma import eTimer
        Screen.__init__(self, session)
        self.monitor = global_sports_monitor

        # Match the main plugin theme
        theme = getattr(self.monitor, "theme_mode", "default")
        alpha = "33" # 20% transparent, 80% solid (in E2, 00 is opaque, FF is transparent)
        if theme == "ucl":
            bg = "#" + alpha + "071020"
            accent = "#c9a020"
        else:
            bg = "#" + alpha + "0d0d20"
            accent = "#00FF85"

        self.skin = scale_skin_xml((
            u'<screen position="center,952" size="1600,100" flags="wfNoBorder" backgroundColor="#FF000000">'
            u'<eLabel position="0,0" size="1600,100" backgroundColor="{bg}" zPosition="0" />'
            u'<eLabel position="0,0" size="1600,3" backgroundColor="{acc}" zPosition="1" />'
            u'<widget name="msg" position="20,10" size="1560,80" font="Regular;30" '
            u'foregroundColor="#FFFFFF" halign="center" valign="center" transparent="1" zPosition="2" />'
            u'</screen>'
        ).format(bg=bg, acc=accent))
        self["msg"] = Label(text)

        # ActionMap makes it dismissable via ANY standard button
        from Components.ActionMap import ActionMap
        self["actions"] = ActionMap(["SetupActions", "DirectionActions", "OkCancelActions", "ColorActions"], {
            "cancel": self.close,
            "ok":     self.close,
            "up":     self.close,
            "down":   self.close,
            "left":   self.close,
            "right":  self.close,
            "red":    self.close,
            "green":  self.close,
            "yellow": self.close,
            "blue":   self.close
        }, -1)

        self.timer = eTimer()
        self.timer.callback.append(self.close)
        self.timer.start(duration_ms, True)

