class SportsMonitor:
    @profile_function("SportsMonitor")
    def __init__(self):
        self.active = False
        self._boot_initialized = False # Track initial boot sequence
        self.discovery_mode = 0
        self.current_league_index = 0
        self.custom_league_indices = []
        self.is_custom_mode = False
        # Separate storage for the two independent multi-league modes:
        #   saved_custom_league_indices  — last selection made via Custom Leagues (View/Edit)
        #   favorite_league_indices      — last selection made via Favorite Leagues
        #   is_favorite_mode             — True when the main screen is showing favorites
        self.saved_custom_league_indices = []
        self.favorite_league_indices = []
        self.is_favorite_mode = False
        self.last_scores = {}
        self.last_red_cards = {}
        self.goal_flags = {}
        self.score_update_timestamps = {}  # match_id -> time.time() of last score change (for 2s pulse)
        self.last_states = {}
        self.last_periods = {}       # Track halftime/period state per match_id
        self.last_details_seen = {}  # Track VAR/disallowed counts per match_id
        self.predictor_cache = {}    # match_id -> {'h_pct':, 'a_pct':, 'fetched_at':} - ESPN pre-game win prediction
        self.predictor_inflight = set()  # match_ids currently being fetched, to avoid duplicate requests
        self.notified_events = set()  # Track fired notifications: {(match_id, event_type)}
        self.filter_mode = 2
        self.ch_day_offset = 0   # 0 = today; +N = N days ahead; -N = N days ago
        self.theme_mode = "default"
        self.transparency = "59"
        self.main_bg_color = "default"

        self.logo_path_cache = {}
        self.missing_logo_cache = set()
        self.pending_logos = set()
        self.voter_name = "Anonymous"
        self.current_league_index = 0
        self.reminders = []
        self.favorite_teams = []  # list of dicts — {team_id, team_name, short_name, league_slug, league_name, logo_url}
        self.fav_notified = set()   # {(match_id, threshold_label)} — prevents duplicate fav alerts
        self.goal_sound_file = "pop.mp3"  # filename only — must exist in plugin dir
        self.followed_livescore_cz_matches = set()
        self.livescore_cz_states = {}
        self.livescore_cz_scores = {}
        self._livescore_cz_last_check = 0    # epoch timestamp of last fetch
        self._livescore_cz_fetching = False   # guard against concurrent fetches
        self.remote_config = {
            "maintenance_mode": False,
            "announcement_message": "",
            "show_announcement": False,
            "update_whole_repo": False,
        }

        self.timer = eTimer()
        safe_connect(self.timer, self.check_goals)


        # AI Mode state
        self.ai_enabled = False
        self.ai_api_key = ""
        self.ai_provider = "gemini"
        self.ai_language = "English"
        self.ai_frequency = 30  # minutes
        self.wp_commentary_interval = 4  # minutes — Watch Party AI commentary interval
        self.ai_timer = eTimer()
        safe_connect(self.ai_timer, self._ai_timer_fired)
        self._ai_last_call_ts = 0
        self._ai_call_in_flight = False

        self.session = None
        self.cached_events = []
        self.match_snapshots = {}  # Unified snapshots for all UI consumers
        self.callbacks = []
        self.status_message = "Initializing..."
        self.notification_queue = []
        self.notification_active = False
        self.current_toast = None  # Reference to active GoalToast for live updates
        self.current_toast_match = None  # (home, away) tuple of active toast
        self.has_changes = True  # Track if data changed since last UI refresh
        self.all_community_votes = {} # Store all match votes locally

        # Batching variables
        self.batch_queue = []
        self.batch_remaining = 0
        self.batch_is_active = False
        self.batch_timer = eTimer()
        safe_connect(self.batch_timer, self.finalize_batch)
        self.processing_queue = []
        self.processing_active = False

        self.logo_cache = LogoCacheManager()
        self.last_update = 0
        import os
        if os.path.exists("/etc/enigma2"):
            self.cache_file = "/etc/enigma2/simplysports_cache.json"
        else:
            self.cache_file = "/tmp/simplysports/cache.json"

        # Optimization: Persistent Agent with Connection Pool & Request Management & Redirect Handling
        self.pool = HTTPConnectionPool(reactor)
        self.pool.maxPersistentPerHost = 10  # Throttle concurrent connections to prevent CDN WAF rate-limiting
        self.pool._factory.noisy = False
        raw_agent = Agent(reactor, pool=self.pool)
        try:
            from twisted.web.client import BrowserLikeRedirectAgent
            self.agent = BrowserLikeRedirectAgent(raw_agent)
        except Exception:
            try:
                from twisted.web.client import RedirectAgent
                self.agent = RedirectAgent(raw_agent)
            except Exception:
                self.agent = raw_agent
        from twisted.web.http_headers import Headers
        self.default_headers = Headers({
            b'User-Agent': [b'curl/7.68.0'],
            b'Accept': [b'application/json, text/plain, */*'],
            b'Accept-Language': [b'en-US,en;q=0.9']
        })
        self.active_requests = set()
        self.last_cache_save = 0
        self.last_callback_time = 0
        self.pending_callback = None
        self.callback_debounce_timer = eTimer()
        safe_connect(self.callback_debounce_timer, self._execute_pending_callback)
        self.event_map = {} # optimization: O(1) lookup
        self.live_summary_timer = None  # Timer for direct summary fetches for live American
        self._summary_fail_counts = {}   # {eid: consecutive_fail_count}
        self._dead_summary_eids = set()  # EIDs that failed 3+ times, skip for session

        self.load_cache()

        self.load_ledger()   # must precede load_config: ensure_timer_state -> check_goals -> evaluate_pending_bets accesses self.ledger
        self.load_config()

        self.boot_timer = eTimer()

        try: self.boot_timer.callback.append(self.check_goals)
        except AttributeError: self.boot_timer.timeout.get().append(self.check_goals)
        self.boot_timer.start(5000, True)

        self._boot_initialized = True # Mark initialization complete

    def fetch_all_community_votes(self):
        # Only download votes when the main screen is actually open.
        # Background mode has no UI to update, so fetching is pure waste.
        if not self.callbacks:
            return
        try:
            from twisted.web.client import getPage
            url = "{}/matches.json".format(FIREBASE_URL)
            getPage(url.encode('utf-8'), timeout=10).addCallback(self.on_all_votes_received).addErrback(lambda e: None)
        except Exception as e:
            log_dbg("Error starting vote fetch: {}".format(e))

    def on_all_votes_received(self, html):
        try:
            import json
            data = json.loads(html)
            if isinstance(data, dict):
                self.all_community_votes = data
                self.has_changes = True
                self._trigger_callbacks()
        except Exception:
            pass

    def set_session(self, session):
        self.session = session
        self._start_ai_timer()  # Start AI timer when session is available
    def register_callback(self, func):
        if func not in self.callbacks:
            self.callbacks.append(func)
            # If this is the first UI listener, fetch votes immediately so
            # the screen doesn't have to wait up to 60 s for the timer tick.
            self.ensure_timer_state() # Ensure timer starts if it was idle
    def unregister_callback(self, func):
        if func in self.callbacks:
            self.callbacks.remove(func)
            self.ensure_timer_state() # Allow idle shutdown if all UIs closed

    # ==========================================================================
    # AI MODE — SCHEDULER & NOTIFICATION
    # ==========================================================================
    def _start_ai_timer(self):
        """Start or restart the AI timer based on current settings."""
        self.ai_timer.stop()
        if not self.ai_enabled or not self.ai_api_key:
            return
        interval_ms = self.ai_frequency * 60 * 1000
        self.ai_timer.start(interval_ms, False)   # False = repeating
        log_dbg("[AI Mode] Timer started: every {} min".format(self.ai_frequency))

    def _ai_timer_fired(self):
        """Called by the AI timer. Builds prompt and fires API call."""
        if not self.ai_enabled or not self.ai_api_key:
            return
        # Rate-limit guard
        now = int(time.time())
        min_gap = max((self.ai_frequency - 1) * 60, 60)
        if (now - self._ai_last_call_ts) < min_gap:
            return
        # In-flight guard
        if self._ai_call_in_flight:
            return
        # Skip if no data
        if not self.cached_events:
            return

        self._ai_call_in_flight = True
        self._ai_last_call_ts = now

        prompt = build_ai_prompt(
            self.ai_language,
            self.cached_events,
            self.match_snapshots,
            getattr(self, 'ledger', None)
        )

        call_ai_api_threaded(
            self.ai_api_key,
            self.ai_provider,
            prompt,
            self._on_ai_response
        )

    def _on_ai_response(self, text):
        """Called on main thread after AI API returns."""
        self._ai_call_in_flight = False
        if not text:
            return
        if text.startswith("ERROR: "):
            try:
                from Screens.MessageBox import MessageBox
                if self.session:
                    self.session.open(MessageBox, "AI API Error: " + text[7:], MessageBox.TYPE_ERROR, timeout=10)
            except Exception:
                pass
            return

        # Split into individual messages (blank-line separated)
        messages = [m.strip() for m in text.split("\n\n") if m.strip()]
        for msg in messages[:2]:              # show max 2 notifications
            self._show_ai_notification(msg)
        # Also feed to the active SimpleSportsScreen ticker if any
        for cb in self.callbacks:
            try:
                screen = getattr(cb, '__self__', None)
                if screen and hasattr(screen, 'receive_ai_ticker'):
                    screen.receive_ai_ticker(messages[:2])
            except Exception:
                pass

    def _show_ai_notification(self, text):
        """Display an auto-dismissing popup with the AI-generated message."""
        if not self.session or is_system_screen_active(self.session):
            return
        try:
            self.session.open(AIToast, text, 10000)
        except Exception as e:
            log_dbg("[AI Mode] Notification failed: " + str(e))

    def test_ai_now(self):
        """Fire a single AI call immediately (for the Test Now button)."""
        if not self.ai_api_key:
            if self.session:
                self.session.open(MessageBox, "Please set an API key first.", MessageBox.TYPE_ERROR, timeout=3)
            return
        if self._ai_call_in_flight:
            return
        self._ai_call_in_flight = True
        prompt = build_ai_prompt(
            self.ai_language,
            self.cached_events,
            self.match_snapshots,
            getattr(self, 'ledger', None)
        )
        call_ai_api_threaded(
            self.ai_api_key,
            self.ai_provider,
            prompt,
            self._on_ai_response
        )

    def _trigger_ai_goal_commentary(self, match_id, score_display, scorer_text, scoring_team):
        """Fire an immediate AI commentary call when a soccer goal is detected.
        Only called for soccer (see evaluate_goals guard). Reads the full match
        timeline already held in event_map — no additional API request needed.

        Guards:
          - AI Mode must be enabled with a valid key.
          - Per-match cooldown of 90 s prevents double-commentary on rapid polls.
          - Falls through silently on any error so the goal notification itself
            is never affected.
        """
        if not self.ai_enabled or not self.ai_api_key:
            return

        # Per-match cooldown stored as a dynamic attribute (no extra dict needed)
        now = int(time.time())
        cooldown_attr = "_ai_goal_ts_" + str(match_id)
        if now - getattr(self, cooldown_attr, 0) < 90:
            log_dbg("[AI Mode] Goal commentary skipped — cooldown active for {}".format(match_id))
            return
        setattr(self, cooldown_attr, now)

        try:
            snap = self.match_snapshots.get(str(match_id), {})
            h_name = snap.get("h_name", "Home")
            a_name = snap.get("a_name", "Away")
            league = snap.get("league_name", "")
            clock  = snap.get("clock", "")
            scoring_team_name = h_name if scoring_team == "home" else a_name

            # --- Build match event timeline from event_map (no API call needed) ---
            # Uses the same 'details' array that powers the GameInfo screen's
            # timeline view — goals, penalties, own goals, red cards, with
            # scorer, assist, team, and clock all already parsed and in memory.
            timeline_lines = []
            try:
                ev = self.event_map.get(str(match_id), {})
                details = ev.get('competitions', [{}])[0].get('details', [])

                # Resolve home team id so we can label events correctly
                h_id_str = ""
                for c in ev.get('competitions', [{}])[0].get('competitors', []):
                    if c.get('homeAway') == 'home':
                        h_id_str = str(c.get('id', '') or c.get('team', {}).get('id', ''))
                        break

                for play in details:
                    text_desc = play.get('type', {}).get('text', '').lower()
                    is_og    = play.get('ownGoal', False)
                    is_pk    = play.get('penaltyKick', False)
                    is_rc    = play.get('redCard', False)
                    is_score = (play.get('scoringPlay', False) or is_og or is_pk
                                or 'goal' in text_desc)
                    is_red   = is_rc or ('card' in text_desc and 'red' in text_desc)

                    if not (is_score or is_red):
                        continue  # skip yellow cards, subs — keep prompt compact

                    event_clock = play.get('clock', {}).get('displayValue', '?')

                    # Resolve athlete names (two possible ESPN structures)
                    athletes = play.get('athletesInvolved', []) or []
                    if not athletes:
                        athletes = [p.get('athlete', p)
                                    for p in play.get('participants', [])]
                    player = ""
                    assist = ""
                    if athletes:
                        a0 = athletes[0]
                        player = a0.get('displayName') or a0.get('shortName', '')
                        if is_score and len(athletes) > 1:
                            a1 = athletes[1]
                            assist = a1.get('displayName') or a1.get('shortName', '')

                    t_id       = str(play.get('team', {}).get('id', ''))
                    team_label = h_name if t_id == h_id_str else a_name

                    if is_red:
                        badge = "[RC]"
                    elif is_pk:
                        badge = "[Pen]"
                    elif is_og:
                        badge = "[OG]"
                    else:
                        badge = "[Goal]"

                    # Team-level only: no player names to avoid AI confusing old scorers
                    line = "{} {} {}".format(event_clock, badge, team_label)
                    timeline_lines.append(line)

            except Exception as te:
                log_dbg("[AI Mode] Timeline build error: {}".format(str(te)))

            # --- Personal stake note from ledger ---
            personal_note = ""
            if hasattr(self, "ledger"):
                bet = self.ledger.get("pending_bets", {}).get(str(match_id))
                if bet:
                    prediction = bet.get("prediction", "")
                    pred_name  = (h_name if prediction == "home" else
                                  a_name if prediction == "away" else "Draw")
                    if pred_name == scoring_team_name:
                        personal_note = (
                            " The viewer predicted {} to win and their team just scored!".format(pred_name))
                    else:
                        personal_note = (
                            " The viewer predicted {} to win — this goal goes against them.".format(pred_name))

            # --- Build match flow context (team-level, no player names) ---
            timeline_block = ""
            if timeline_lines:
                timeline_block = "\nMATCH FLOW: " + "; ".join(timeline_lines[-8:])

            # --- Assemble prompt (THIS goal + match story) ---
            prompt = (
                "React to THIS goal that JUST happened RIGHT NOW. "
                "Write exactly ONE short sentence, like a real human TV commentator would say it live on air. "
                "Sound natural and conversational, like a friend watching the game.\n\n"
                "THE GOAL: {} scores for {} in minute {}! Score is now {} in {} ({}).{}\n\n"
                "RULES:\n"
                "- The ONLY player you may name is the current scorer: {}.\n"
                "- Do NOT name any other players from previous events.\n"
                "- You MAY reference the match story (comebacks, red cards, drama) "
                "without naming old scorers.\n"
                "- Keep it under 20 words. One sentence only.\n"
                "- No numbering, no emojis, no asterisks, no markdown.\n"
                "- {}.{}"
            ).format(
                scorer_text, scoring_team_name, clock, score_display,
                league, "{} vs {}".format(h_name, a_name),
                personal_note, scorer_text, get_ai_language_instruction(self.ai_language),
                timeline_block
            )

            # Delay so the GoalToast (5 s) has fully dismissed before the AIToast
            # appears. 8 s here + ~3-5 s API latency = commentary arrives ~11-13 s
            # after the goal — well clear of the score notification.
            _key  = self.ai_api_key
            _prov = self.ai_provider
            _cb   = self._on_ai_response
            reactor.callLater(8, lambda: call_ai_api_threaded(_key, _prov, prompt, _cb))
            log_dbg("[AI Mode] Goal commentary scheduled (+8 s) — match {} score {} timeline_events={}".format(
                match_id, score_display, len(timeline_lines)))

        except Exception as e:
            log_dbg("[AI Mode] _trigger_ai_goal_commentary error: {}".format(str(e)))

    def _trigger_ai_match_event_commentary(self, match_id, event_type, score_fmt):
        """Fire AI commentary when a soccer match kicks off ('start') or ends ('end').
        Uses the same delayed delivery pattern as goal commentary so the GoalToast
        notification (kickoff / full-time banner) is fully visible before the AI
        response arrives.

        event_type : 'start' or 'end'
        score_fmt  : compact score string e.g. '2-1'
        """
        if not self.ai_enabled or not self.ai_api_key:
            return

        # 5-minute cooldown prevents double-firing if evaluate_goals runs twice
        now = int(time.time())
        cooldown_attr = "_ai_{}_ts_{}".format(event_type, str(match_id))
        if now - getattr(self, cooldown_attr, 0) < 300:
            log_dbg("[AI Mode] {} commentary skipped — cooldown for {}".format(
                event_type, match_id))
            return
        setattr(self, cooldown_attr, now)

        try:
            snap   = self.match_snapshots.get(str(match_id), {})
            h_name = snap.get("h_name", "Home")
            a_name = snap.get("a_name", "Away")
            league = snap.get("league_name", "")

            # --- Build full timeline for end-of-match summary ---
            timeline_lines = []
            if event_type == 'end':
                try:
                    ev      = self.event_map.get(str(match_id), {})
                    details = ev.get('competitions', [{}])[0].get('details', [])
                    h_id_str = ""
                    for c in ev.get('competitions', [{}])[0].get('competitors', []):
                        if c.get('homeAway') == 'home':
                            h_id_str = str(
                                c.get('id', '') or c.get('team', {}).get('id', ''))
                            break
                    for play in details:
                        text_desc = play.get('type', {}).get('text', '').lower()
                        is_og    = play.get('ownGoal', False)
                        is_pk    = play.get('penaltyKick', False)
                        is_rc    = play.get('redCard', False)
                        is_score = (play.get('scoringPlay', False) or is_og or is_pk
                                    or 'goal' in text_desc)
                        is_red   = is_rc or ('card' in text_desc and 'red' in text_desc)
                        if not (is_score or is_red):
                            continue
                        event_clock = play.get('clock', {}).get('displayValue', '?')
                        athletes = play.get('athletesInvolved', []) or [
                            p.get('athlete', p) for p in play.get('participants', [])]
                        player = ""
                        assist = ""
                        if athletes:
                            a0     = athletes[0]
                            player = a0.get('displayName') or a0.get('shortName', '')
                            if is_score and len(athletes) > 1:
                                a1     = athletes[1]
                                assist = a1.get('displayName') or a1.get('shortName', '')
                        t_id       = str(play.get('team', {}).get('id', ''))
                        team_label = h_name if t_id == h_id_str else a_name
                        badge = ("[RC]"   if is_red  else
                                 "[Pen]"  if is_pk   else
                                 "[OG]"   if is_og   else "[Goal]")
                        line = "{} {} {} ({})".format(
                            event_clock, badge, player, team_label)
                        if assist and is_score and not is_red:
                            line += " assist: {}".format(assist)
                        timeline_lines.append(line)
                except Exception as te:
                    log_dbg("[AI Mode] Match-end timeline error: {}".format(str(te)))

            # --- User prediction context ---
            personal_note = ""
            if hasattr(self, "ledger"):
                bet = self.ledger.get("pending_bets", {}).get(str(match_id))
                if bet:
                    prediction = bet.get("prediction", "")
                    pred_name  = (h_name if prediction == "home" else
                                  a_name if prediction == "away" else "Draw")
                    personal_note = (
                        " The viewer predicted {} to win.".format(pred_name))

            # --- Build prompt ---
            if event_type == 'start':
                prompt = (
                    "The whistle just blew — {} vs {} is kicking off NOW in the {}. "
                    "Write exactly ONE sentence like a real human commentator would say live on TV. "
                    "Sound natural and excited, not robotic. "
                    "Mention both teams. Keep it under 20 words. "
                    "No emojis, no markdown, no numbering. "
                    "{}.{}"
                ).format(h_name, a_name, league, get_ai_language_instruction(self.ai_language), personal_note)

            else:   # 'end'
                timeline_block = ""
                if timeline_lines:
                    timeline_block = (
                        "\nMatch events for context: " + "; ".join(timeline_lines[-6:]))
                prompt = (
                    "Full time! {} vs {} ends {}. {}. "
                    "Write exactly ONE sentence like a real human commentator would say at the final whistle. "
                    "React to the final score. Sound natural, not robotic, not cliche. "
                    "Keep it under 20 words. "
                    "No emojis, no markdown, no numbering. "
                    "{}.{}{}"
                ).format(
                    h_name, a_name, score_fmt, league,
                    get_ai_language_instruction(self.ai_language), personal_note, timeline_block)

            # Delay so the start/end GoalToast banner finishes before AIToast arrives
            _key  = self.ai_api_key
            _prov = self.ai_provider
            _cb   = self._on_ai_response
            reactor.callLater(8, lambda: call_ai_api_threaded(_key, _prov, prompt, _cb))
            log_dbg("[AI Mode] Match {} commentary scheduled (+8 s) — {} {}".format(
                event_type, match_id, score_fmt))

        except Exception as e:
            log_dbg("[AI Mode] _trigger_ai_match_event_commentary error: {}".format(
                str(e)))

    def load_config(self):
        if os.path.exists(CONFIG_FILE):
            try:
                with open(CONFIG_FILE, "r") as f:
                    data = json.load(f)
                    # --- Single league: prefer stable slug, fall back to legacy index ---
                    _league_slug = data.get("league_slug")
                    if _league_slug and _league_slug in SLUG_TO_IDX:
                        self.current_league_index = SLUG_TO_IDX[_league_slug]
                    else:
                        self.current_league_index = int(data.get("league_index", 0))
                    self.filter_mode = int(data.get("filter_mode", 0))
                    self.theme_mode = data.get("theme_mode", "default")
                    self.transparency = data.get("transparency", "59")
                    _bg_col = data.get("main_bg_color", "default")
                    self.main_bg_color = _bg_col if _bg_col in MAIN_THEME_BG_COLORS else "default"
                    self.discovery_mode = int(data.get("discovery_mode", 0))
                    self.active = (self.discovery_mode > 0)
                    # --- Custom leagues: prefer stable slugs, fall back to legacy indices ---
                    _custom_slugs = data.get("custom_league_slugs")
                    if _custom_slugs is not None:
                        self.custom_league_indices = [SLUG_TO_IDX[s] for s in _custom_slugs if s in SLUG_TO_IDX]
                    else:
                        self.custom_league_indices = data.get("custom_indices", [])
                    self.is_custom_mode = bool(data.get("is_custom_mode", False))
                    _saved_slugs = data.get("saved_custom_league_slugs")
                    if _saved_slugs is not None:
                        self.saved_custom_league_indices = [SLUG_TO_IDX[s] for s in _saved_slugs if s in SLUG_TO_IDX]
                    else:
                        self.saved_custom_league_indices = data.get("saved_custom_indices", list(self.custom_league_indices))
                    _fav_slugs = data.get("favorite_league_slugs")
                    if _fav_slugs is not None:
                        self.favorite_league_indices = [SLUG_TO_IDX[s] for s in _fav_slugs if s in SLUG_TO_IDX]
                    else:
                        self.favorite_league_indices = data.get("favorite_league_indices", [])
                    self.is_favorite_mode = bool(data.get("is_favorite_mode", False))
                    self.reminders = data.get("reminders", [])
                    self.menu_section = data.get("menu_section", "all")
                    self.show_in_menu = bool(data.get("show_in_menu", True))
                    self.minibar_color_mode = data.get("minibar_color_mode", "default")
                    self.minibar_1_style = data.get("minibar_1_style", "default")
                    self.voter_name = data.get("voter_name", "Anonymous")
                    self.install_registered = bool(data.get("install_registered", False))
                    # Plugin language
                    global PLUGIN_LANGUAGE
                    PLUGIN_LANGUAGE = data.get("plugin_language", "en")
                    # AI Mode config (safe defaults for older installs without the key)
                    ai_cfg = data.get("ai_mode", {})
                    self.ai_enabled   = ai_cfg.get("enabled", False)
                    self.ai_api_key   = ai_cfg.get("api_key", "")
                    self.ai_provider  = ai_cfg.get("provider", "gemini")
                    self.ai_language  = ai_cfg.get("language", "English")
                    self.ai_frequency = int(ai_cfg.get("frequency_min", 30))
                    self.wp_commentary_interval = int(ai_cfg.get("wp_commentary_interval", 4))

                    # Favorite teams
                    self.favorite_teams = data.get("favorite_teams", [])

                    # Goal sound preference
                    self.goal_sound_file = data.get("goal_sound_file", "pop.mp3")

                    # Notification Toast Animation
                    self.toast_animation = bool(data.get("toast_animation", True))

                    # User-Selected League for Key 8
                    _k8_slug = data.get("key8_league_slug")
                    if _k8_slug and _k8_slug in SLUG_TO_IDX:
                        self.key8_league_index = SLUG_TO_IDX[_k8_slug]
                    elif "key8_league_index" in data:
                        self.key8_league_index = int(data.get("key8_league_index", -1))
                    else:
                        self.key8_league_index = -1

                    # FIX: Ensure timer state is set correctly (handles active and reminders)
                    try:
                        self.ensure_timer_state()
                    except Exception as e:
                        log_dbg("ensure_timer_state error during load_config: " + str(e))

                    # Pre-warm logo cache for saved favourite teams
                    self.prefetch_favorite_logos()
            except Exception as e:
                log_dbg("load_config ERROR: " + str(e))
                self.defaults()
        else: self.defaults()

    def defaults(self):
        self.filter_mode = 2; self.theme_mode = "default"; self.transparency = "59"
        self.main_bg_color = "default"
        self.discovery_mode = 0; self.reminders = []; self.menu_section = "all"
        self.show_in_menu = True; self.minibar_color_mode = "default"; self.minibar_1_style = "default"
        self.voter_name = "Anonymous"
        self.ai_enabled = False; self.ai_api_key = ""; self.ai_provider = "gemini"
        self.ai_language = "English"; self.ai_frequency = 30; self.wp_commentary_interval = 4
        self.install_registered = False
        self.favorite_teams = []
        self.fav_notified = set()
        self.goal_sound_file = "pop.mp3"
        self.toast_animation = True
        self.key8_league_index = -1
        self.saved_custom_league_indices = []
        self.favorite_league_indices = []
        self.is_favorite_mode = False
        # FIX Bug 1: resolved_bets must be a dict (not a list) to support key-based
        # lookups and assignment used throughout the gamification engine.
        # Also ensure total_predictions and correct_predictions are always present.
        self.ledger = {"total_score": 0, "pending_bets": {}, "resolved_bets": {}, "total_predictions": 0, "correct_predictions": 0}

    def fetch_remote_config(self):
        try:
            import ssl
            import json
            from urllib.request import Request, urlopen
            url = "{}/remote_config.json".format(FIREBASE_URL)
            req = Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            try:
                context = ssl._create_unverified_context()
                response = urlopen(req, timeout=5, context=context)
            except AttributeError:
                response = urlopen(req, timeout=5)
            data = response.read()
            if isinstance(data, bytes):
                data = data.decode('utf-8', errors='ignore')
            if data and data != "null":
                parsed = json.loads(data)
                if isinstance(parsed, dict):
                    self.remote_config.update(parsed)
                    log_dbg("[RemoteConfig] Configuration loaded successfully.")
        except Exception as e:
            log_dbg("[RemoteConfig] Fetch failed: " + str(e))

    def save_config(self):
        data = {
            "league_index": self.current_league_index,
            "league_slug": IDX_TO_SLUG.get(self.current_league_index, ""),
            "filter_mode": self.filter_mode,
            "theme_mode": self.theme_mode, "transparency": self.transparency,
            "main_bg_color": getattr(self, "main_bg_color", "default"),
            "discovery_mode": self.discovery_mode, "active": self.active,
            "custom_indices": self.custom_league_indices,
            "custom_league_slugs": [IDX_TO_SLUG[i] for i in self.custom_league_indices if i in IDX_TO_SLUG],
            "is_custom_mode": self.is_custom_mode,
            "saved_custom_indices": self.saved_custom_league_indices,
            "saved_custom_league_slugs": [IDX_TO_SLUG[i] for i in self.saved_custom_league_indices if i in IDX_TO_SLUG],
            "favorite_league_indices": self.favorite_league_indices,
            "favorite_league_slugs": [IDX_TO_SLUG[i] for i in self.favorite_league_indices if i in IDX_TO_SLUG],
            "is_favorite_mode": self.is_favorite_mode,
            "reminders": self.reminders, "menu_section": self.menu_section,
            "show_in_menu": self.show_in_menu, "minibar_color_mode": self.minibar_color_mode,
            "minibar_1_style": self.minibar_1_style,
            "voter_name": self.voter_name,
            "install_registered": getattr(self, "install_registered", False),
            "plugin_language": PLUGIN_LANGUAGE,
            "ai_mode": {
                "enabled": self.ai_enabled,
                "api_key": self.ai_api_key,
                "provider": self.ai_provider,
                "language": self.ai_language,
                "frequency_min": self.ai_frequency,
                "wp_commentary_interval": self.wp_commentary_interval
            },
            "favorite_teams": self.favorite_teams[:10],  # enforce max 10
            "goal_sound_file": self.goal_sound_file,
            "toast_animation": getattr(self, "toast_animation", True),
            "key8_league_index": getattr(self, "key8_league_index", 165),
            "key8_league_slug": IDX_TO_SLUG.get(getattr(self, "key8_league_index", 165), ""),
        }
        try:
            with open(CONFIG_FILE, "w") as f: json.dump(data, f)
        except: pass

    def load_ledger(self):
        try:
            if os.path.exists(LEDGER_FILE):
                with open(LEDGER_FILE, "r") as f:
                    self.ledger = json.load(f)
            else:
                self.ledger = {"total_score": 0, "pending_bets": {}, "resolved_bets": {}, "total_predictions": 0, "correct_predictions": 0}

            # FIX: Ensure resolved_bets is a dictionary (V2 requirement)
            if not isinstance(self.ledger.get("resolved_bets"), dict):
                # Migration: if it was a list, just convert to empty dict (safer than trying to guess structure)
                self.ledger["resolved_bets"] = {}

            # Migration logic for old /tmp votes
            old_votes_file = "/tmp/simplysports_votes.json"
            if os.path.exists(old_votes_file):
                try:
                    with open(old_votes_file, "r") as f:
                        old_data = json.load(f)
                        for eid in old_data:
                            eid_str = str(eid)
                            if eid_str not in self.ledger["resolved_bets"]:
                                self.ledger["resolved_bets"][eid_str] = {"legacy": True}
                    self.save_ledger()
                except: pass
        except:
            self.ledger = {"total_score": 0, "pending_bets": {}, "resolved_bets": {}, "total_predictions": 0, "correct_predictions": 0}

    def save_ledger(self):
        """Saves the current ledger to disk, pruning resolved bets older than 30 days."""
        import json
        import time

        if not hasattr(self, 'ledger') or not self.ledger:
            return

        # --- THE JANITOR: 30-Day Pruning Routine ---
        thirty_days_in_seconds = 30 * 24 * 60 * 60
        current_time = int(time.time())

        resolved = self.ledger.get("resolved_bets", {})
        if isinstance(resolved, dict):
            stale_keys = []

            for event_id, bet_data in resolved.items():
                # Get the timestamp. If it doesn't exist (older bets), assign it today's time
                bet_time = bet_data.get("timestamp")
                if bet_time is None:
                    bet_data["timestamp"] = current_time
                    continue

                # If the bet is older than 30 days, mark it for deletion
                if (current_time - int(bet_time)) > thirty_days_in_seconds:
                    stale_keys.append(event_id)

            # Delete the stale bets from the dictionary
            for event_id in stale_keys:
                del resolved[event_id]
                print("[SimplySports Janitor] Deleted stale bet:", event_id)
        # -------------------------------------------

        try:
            # FIX Bug 4: Always use the module-level LEDGER_FILE constant directly.
            # getattr(self, 'LEDGER_FILE', ...) never resolved to the instance because
            # LEDGER_FILE is not an instance attribute — it is a module-level constant.
            # The silent fallback to the hardcoded string meant any rename of the
            # constant at the top of the file would be ignored here, causing a
            # path mismatch between save and load after a restart.
            with open(LEDGER_FILE, "w") as f:
                json.dump(self.ledger, f)
        except Exception as e:
            print("[SimplySports] Failed to save ledger:", e)
    def add_pending_bet(self, event_id, prediction, sport, league, h_name="Home", a_name="Away", league_url=""):
        eid = str(event_id)
        if eid not in self.ledger["pending_bets"] and eid not in self.ledger["resolved_bets"]:
            self.ledger["pending_bets"][eid] = {
                "prediction": prediction, # 'home', 'away', or 'draw'
                "sport": sport,
                "league": league,
                "league_url": league_url,
                # Store team names at bet time so the Personal Profile screen can
                # show a meaningful "Arsenal vs Chelsea" label even after the match
                # has dropped out of the live event_map cache.
                "h_name": h_name,
                "a_name": a_name,
                "timestamp": int(time.time())
            }
            self.save_ledger()
            self.evaluate_pending_bets()

    def fetch_predictor_async(self, match_id, league_url, event_id):
        """Fetch a pre-game win-probability for one scheduled match in a
        background thread, and cache it. Tries ESPN's own 'predictor' field
        first; if that's not present for this match, falls back to converting
        moneyline odds (from the same response's 'pickcenter' block - no extra
        HTTP call) into an implied, vig-free probability. Spread/handicap and
        Over/Under numbers (e.g. '-0.5 | O/U 2.5') are a different market and
        are deliberately NOT converted - there's no clean, honest way to turn
        a goal handicap alone into a win percentage without a separate
        statistical model, so providers that only offer that are skipped."""
        if not event_id or not league_url:
            return
        self.predictor_inflight.add(match_id)

        def _run():
            try:
                import re
                m = re.search(r'/sports/([^/]+)/([^/]+)/scoreboard', league_url)
                if not m:
                    return
                sport, league = m.group(1), m.group(2)
                url = "https://site.api.espn.com/apis/site/v2/sports/{}/{}/summary?event={}".format(sport, league, event_id)
                try:
                    req = Request(url, headers={'User-Agent': 'Mozilla/5.0'})
                    resp = urlopen(req, timeout=6)
                    data = json.loads(resp.read().decode('utf-8'))
                except Exception:
                    return

                h_val = 0.0; a_val = 0.0; source = None

                # 1) ESPN's own pre-game projection, when available
                predictor = data.get('predictor', {}) or {}
                if predictor:
                    h_team_pred = predictor.get('homeTeam', {}) or {}
                    a_team_pred = predictor.get('awayTeam', {}) or {}
                    h_prob = h_team_pred.get('gameProjection') or h_team_pred.get('chanceToWin') or 0
                    a_prob = a_team_pred.get('gameProjection') or a_team_pred.get('chanceToWin') or 0
                    try:
                        h_val = float(h_prob); a_val = float(a_prob)
                        if h_val > 0 or a_val > 0:
                            source = 'predictor'
                    except (TypeError, ValueError):
                        h_val = 0.0; a_val = 0.0

                # 2) Fallback: moneyline odds -> implied probability (vig removed).
                # Skips any provider that only quotes a spread/O-U with no moneyline.
                if not source:
                    for odd in (data.get('pickcenter', []) or []):
                        h_ml = (odd.get('homeTeamOdds', {}) or {}).get('moneyLine')
                        a_ml = (odd.get('awayTeamOdds', {}) or {}).get('moneyLine')
                        d_ml = (odd.get('drawOdds', {}) or {}).get('moneyLine')
                        h_p = _moneyline_to_prob(h_ml)
                        a_p = _moneyline_to_prob(a_ml)
                        if h_p is None or a_p is None:
                            continue  # spread/O-U only, e.g. "-0.5 | O/U 2.5" - not convertible, skip
                        d_p = _moneyline_to_prob(d_ml) if d_ml is not None else None
                        raw_total = h_p + a_p + (d_p or 0.0)
                        if raw_total <= 0:
                            continue
                        h_val = (h_p / raw_total) * 100.0
                        a_val = (a_p / raw_total) * 100.0
                        source = 'moneyline'
                        break

                # 3) Last resort: no moneyline anywhere either, but a provider quotes
                # a plain point spread (e.g. DraftKings soccer "-0.5 | O/U 2.5").
                # Derive a labeled ESTIMATE from that spread alone (see
                # _spread_to_probs docstring) rather than leaving it blank.
                if not source:
                    for odd in (data.get('pickcenter', []) or []):
                        spread_val = odd.get('spread')
                        if spread_val is None:
                            continue
                        result = _spread_to_probs(spread_val, league_url)
                        if not result:
                            continue
                        h_val, a_val = result
                        source = 'spread_estimate'
                        break

                if not source or (h_val <= 0 and a_val <= 0):
                    return
                self.predictor_cache[match_id] = {'h_pct': h_val, 'a_pct': a_val, 'source': source, 'fetched_at': time.time()}
            except Exception:
                pass
            finally:
                self.predictor_inflight.discard(match_id)

        t = threading.Thread(target=_run, daemon=True)
        t.start()

    def _resolve_epl_bet(self, eid, bet):
        # 1. First check in-memory event_map
        ev = self.event_map.get(str(eid))
        if ev:
            try:
                comp = dict(ev.get('competitions', [{}])[0])
                status_dict = ev.get('status', {}) or comp.get('status', {})
                comp['status'] = status_dict
                state = status_dict.get('type', {}).get('state', 'pre')
                if state == 'post':
                    fake_body = json.dumps({'header': {'competitions': [comp]}}).encode('utf-8')
                    self._on_summary_resolved(fake_body, eid, bet)
                    return
            except Exception as e:
                log_dbg("EPL bet eval error for {}: {}".format(eid, e))

        # 2. If not found in current event_map or not marked post yet, query Azure EPL API
        def _fetch_epl_bet_result():
            try:
                import urllib.request as _urllib
                import ssl as _ssl
                ctx = _ssl.create_default_context()
                ctx.check_hostname = False
                ctx.verify_mode = _ssl.CERT_NONE
                hdrs = {'User-Agent': 'Mozilla/5.0'}

                dates_to_check = []
                today_str = datetime.date.today().strftime('%Y-%m-%d')
                dates_to_check.append(today_str)
                ts = bet.get("timestamp", 0)
                if ts > 0:
                    b_dt = datetime.datetime.fromtimestamp(ts)
                    for day_delta in [0, -1, 1, -2, -3]:
                        d_cand = (b_dt + datetime.timedelta(days=day_delta)).strftime('%Y-%m-%d')
                        if d_cand not in dates_to_check:
                            dates_to_check.append(d_cand)

                h_bet = (bet.get("h_name") or "").strip().lower()
                a_bet = (bet.get("a_name") or "").strip().lower()

                for d_str in dates_to_check:
                    u = "https://egypl-api.azurewebsites.net/Auth/1667/matches/{}".format(d_str)
                    try:
                        req = _urllib.Request(u, headers=hdrs)
                        resp = _urllib.urlopen(req, timeout=6, context=ctx).read().decode('utf-8', errors='ignore')
                        data = json.loads(resp)
                    except Exception:
                        continue

                    if not isinstance(data, list):
                        continue

                    for m in data:
                        m_id = str(m.get('id') or hashlib.md5(str(m).encode('utf-8')).hexdigest()[:10])
                        h_name = (m.get('homeTeamName') or '').strip().lower()
                        a_name = (m.get('awayTeamName') or '').strip().lower()

                        matched = False
                        if m_id == str(eid):
                            matched = True
                        elif h_bet and a_bet and (h_bet in h_name or h_name in h_bet) and (a_bet in a_name or a_name in a_bet):
                            matched = True

                        if matched:
                            h_score = m.get('homeScore')
                            a_score = m.get('awayScore')
                            status_obj = m.get('currentMatchStatus') or {}
                            status_id = status_obj.get('matchStatusId') or status_obj.get('status', 0)
                            status_name = status_obj.get('matchStatusName') or m.get('statusDescription') or ''
                            is_post = (status_id == 9 or status_name in ('انتهت', 'FT', 'Finished') or 
                                       (h_score is not None and a_score is not None and status_id != 1))
                            if is_post and h_score is not None and a_score is not None:
                                comp = {
                                    'status': {'type': {'state': 'post', 'completed': True}},
                                    'competitors': [
                                        {'homeAway': 'home', 'score': int(h_score)},
                                        {'homeAway': 'away', 'score': int(a_score)}
                                    ]
                                }
                                fake_body = json.dumps({'header': {'competitions': [comp]}}).encode('utf-8')
                                reactor.callFromThread(self._on_summary_resolved, fake_body, eid, bet)
                                return
            except Exception as ex:
                log_dbg("EPL bet background fetch error: {}".format(ex))

        t = threading.Thread(target=_fetch_epl_bet_result)
        t.daemon = True
        t.start()

    def evaluate_pending_bets(self):
        if not self.ledger.get("pending_bets"): return

        log_diag("REFREE: Evaluating {} pending bets...".format(len(self.ledger["pending_bets"])))
        for eid, bet in list(self.ledger["pending_bets"].items()):
            sport = bet.get("sport", "soccer")
            league = bet.get("league", "")

            # ── Egyptian Premier League: resolve from EPL engine & Azure API ──
            # EPL event IDs come from the Egyptian Pro League portal, not ESPN.
            # Route them to _resolve_epl_bet so they are checked against event_map
            # and the official EPL archive instead of ESPN.
            is_epl = (league == "epl" or 
                      bet.get("league_url", "") == "epl://api" or 
                      bet.get("league_url", "").startswith("epl") or
                      str(eid).startswith("epl_"))
            if not is_epl:
                ev_check = self.event_map.get(str(eid))
                if ev_check and (ev_check.get("league_url") == "epl://api" or "Egyptian" in ev_check.get("league_name", "")):
                    is_epl = True

            if is_epl:
                self._resolve_epl_bet(eid, bet)
                continue

            url = "https://site.api.espn.com/apis/site/v2/sports/{}/{}/summary?event={}".format(sport, league, eid)

            if url in self.active_requests: continue

            self.active_requests.add(url)
            d = self.agent.request(b'GET', url.encode('utf-8'), self.default_headers)
            d.addCallback(readBody)
            d.addCallback(self._on_summary_resolved, eid, bet)
            d.addErrback(lambda x: log_dbg("Referee error for {}: {}".format(eid, x)))
            d.addBoth(lambda x, u=url: self.active_requests.discard(u))

    def _on_summary_resolved(self, body, eid, bet):
        try:
            # ESPN may return gzip-compressed responses
            if body[:2] == b'\x1f\x8b':
                import gzip
                try:
                    body = gzip.decompress(body)
                except Exception:
                    import io
                    body = gzip.GzipFile(fileobj=io.BytesIO(body)).read()
            data = json.loads(body)
            header = data.get('header', {})
            comps = header.get('competitions', [{}])
            if not comps: return

            comp = comps[0]
            status = comp.get('status', {})
            state = status.get('type', {}).get('state', 'pre')

            if state == 'post':
                # Match finished! Calculate winner from scores (V2 Logic)
                competitors = comp.get('competitors', [])
                h_score = 0
                a_score = 0

                for c in competitors:
                    score_val = int(c.get('score', 0))
                    if c.get('homeAway') == 'home':
                        h_score = score_val
                    else:
                        a_score = score_val

                # Determine actual winner
                if h_score > a_score: actual_winner = 'home'
                elif a_score > h_score: actual_winner = 'away'
                else: actual_winner = 'draw'

                prediction = bet.get("prediction")
                sport = bet.get("sport", "soccer")
                league = bet.get("league", "")
                current_score = int(self.ledger.get("total_score", 0))
                total_preds = int(self.ledger.get("total_predictions", 0)) + 1
                correct_preds = int(self.ledger.get("correct_predictions", 0))

                # Detect if match was decided by penalty shootout
                # (summary body carries the final status shortDetail)
                is_pk_decided = False
                try:
                    summary_comps = body.get('header', {}).get('competitions', [{}])
                    pk_detail = (summary_comps[0].get('status', {})
                                               .get('type', {})
                                               .get('shortDetail', '')).lower()
                    is_pk_decided = any(x in pk_detail for x in ['penalty kick', 'penalties', 'pen. kick', 'shootout'])
                except Exception:
                    pass

                # Initialize sport-specific tracking
                if "sport_stats" not in self.ledger:
                    self.ledger["sport_stats"] = {}
                if sport not in self.ledger["sport_stats"]:
                    self.ledger["sport_stats"][sport] = {"score": 0, "total": 0, "correct": 0}

                # --- Independent League Leaderboard Tracking (PL, La Liga, Serie A, Bundesliga, Ligue 1, World Cup, etc.) ---
                league_cat = get_leaderboard_league_category(league, bet.get("league_url", ""), sport)
                if league_cat:
                    if league_cat not in self.ledger["sport_stats"]:
                        self.ledger["sport_stats"][league_cat] = {"score": 0, "total": 0, "correct": 0}
                    self.ledger["sport_stats"][league_cat]["total"] += 1

                # --- World Cup Progressive Scoring Logic ---
                is_world_cup = (league_cat == "World Cup" or league == "fifa.world")
                points_to_award = 1  # Default points for standard matches

                if is_world_cup:
                    current_date = time.strftime("%m-%d")

                    # 2026 World Cup Schedule Boundaries
                    if "06-11" <= current_date <= "06-27":
                        points_to_award = 2   # Group Stage
                    elif "06-28" <= current_date <= "07-03":
                        points_to_award = 3   # Round of 32
                    elif "07-04" <= current_date <= "07-07":
                        points_to_award = 4   # Round of 16
                    elif "07-08" <= current_date <= "07-11":
                        points_to_award = 5   # Quarter-finals
                    elif "07-14" <= current_date <= "07-15":
                        points_to_award = 6   # Semi-finals
                    elif "07-18" <= current_date <= "07-19":
                        points_to_award = 8   # Final and Third-Place Playoff
                    else:
                        points_to_award = 2   # Fallback
                # ------------------------------------------

                self.ledger["sport_stats"][sport]["total"] += 1

                if prediction == actual_winner:
                    # Award progressive points for winning
                    current_score += points_to_award
                    correct_preds += 1
                    self.ledger["sport_stats"][sport]["score"] += points_to_award
                    self.ledger["sport_stats"][sport]["correct"] += 1

                    if league_cat:
                        self.ledger["sport_stats"][league_cat]["score"] += points_to_award
                        self.ledger["sport_stats"][league_cat]["correct"] += 1

                    log_diag("REFREE: Match {} result ({}) matched prediction! Score: {}".format(eid, actual_winner, current_score))
                else:
                    # Deduct only 1 point for losing (flat rate to maintain engagement)
                    current_score -= 1
                    self.ledger["sport_stats"][sport]["score"] -= 1

                    if league_cat:
                        self.ledger["sport_stats"][league_cat]["score"] -= 1

                    log_diag("REFREE: Match {} result ({}) MISMATCHED prediction ({}). Score: {}".format(eid, actual_winner, prediction, current_score))

                # Update Ledger with detailed results (V2 Requirement)
                self.ledger["total_score"] = current_score
                self.ledger["total_predictions"] = total_preds
                self.ledger["correct_predictions"] = correct_preds

                self.ledger["resolved_bets"][eid] = {
                    "prediction": prediction,
                    "result": actual_winner,
                    "score": "{}-{}".format(h_score, a_score),
                    "points": points_to_award if prediction == actual_winner else -1,
                    "method": "penalties" if is_pk_decided else "normal",
                    # Carry team names from the pending bet so the Personal Profile
                    # screen can show "Arsenal vs Chelsea" after the match is over.
                    "h_name": bet.get("h_name", "Home"),
                    "a_name": bet.get("a_name", "Away"),
                    # FIX Bug 6: Use the current time (moment of resolution) rather than
                    # the original bet placement timestamp.  The 30-day pruning janitor in
                    # save_ledger() measures age from this timestamp.  Reusing the placement
                    # time would shorten the retention window for postponed matches — a match
                    # placed 29 days ago would be pruned the very next save after resolution.
                    "timestamp": int(time.time())
                }

                # Clean up pending
                if eid in self.ledger["pending_bets"]:
                    del self.ledger["pending_bets"][eid]

                self.save_ledger()
                self.sync_leaderboard()
        except Exception as e:
            log_dbg("Referee processing error for {}: {}".format(eid, e))

    def sync_leaderboard(self):
        device_id = get_device_id()
        url = "{}/leaderboard/{}.json".format(FIREBASE_URL, device_id)

        # Calculate accuracy safely
        total_preds = int(self.ledger.get("total_predictions", 0))
        correct_preds = int(self.ledger.get("correct_predictions", 0))
        accuracy = (float(correct_preds) / total_preds * 100.0) if total_preds > 0 else 0.0
        total_score = self.ledger.get("total_score", 0)

        # Compute this player's current badge so other users see it on their
        # leaderboard without having to recalculate it client-side.
        badge = get_rank_badge(total_score, accuracy)

        payload = json.dumps({
            "score": total_score,
            "name": self.voter_name,
            "accuracy": round(accuracy, 1),
            "total_bets": total_preds,
            "sports": self.ledger.get("sport_stats", {}),
            "badge": badge,
            "timestamp": int(time.time())
        })
        push_to_firebase_threaded(url, payload)

    def _register_install(self):
        """Push a registration record to /installs/{device_id} in Firebase.
        first_seen is written only once (guarded by install_registered flag).
        last_seen and name are updated on every call.
        Runs in a background thread — never blocks the UI.
        """
        device_id = get_device_id()
        url = "{}/installs/{}.json".format(FIREBASE_URL, device_id)
        now = int(time.time())

        payload = {
            "name":       self.voter_name,
            "last_seen":  now,
            "version":    VERSION,
        }

        # Write first_seen only on the very first registration
        if not self.install_registered:
            payload["first_seen"] = now
            self.install_registered = True
            self.save_config()

        push_to_firebase_threaded(url, json.dumps(payload))
        log_dbg("[Install] Registration pushed for device {}".format(device_id))

    # ... (Helpers omitted for brevity, assuming standard methods exist) ...
    def toggle_theme(self):
        if self.theme_mode == "default": self.theme_mode = "ucl"
        else: self.theme_mode = "default"
        self.save_config(); return self.theme_mode
    def toggle_filter(self):
        # Two modes only: Live(1) <-> Today(2). Today strictly shows only
        # matches whose date is today (plus anything currently live).
        if self.filter_mode == 1:
            self.filter_mode = 2
        else:
            self.filter_mode = 1
        log_diag("MONITOR.toggle_filter: switched to {}".format(self.filter_mode))
        self.save_config(); return self.filter_mode

    def _build_dated_url(self, url):
        """
        Append ?dates=YYYYMMDD-YYYYMMDD to an ESPN scoreboard URL when ch_day_offset != 0
        to cover timezone-shifted matches (fetching 1 day before to the target day).
        EuroLeague URLs (euroleague://) are passed through unchanged.
        Tennis, MMA, and Racing URLs are passed through unchanged because ESPN's API
        for those sports returns 0 events when the dates parameter is appended.
        They use tournament-level/week-level date ranges and have their own internal filtering.
        """
        if url.startswith('euroleague://') or url.startswith('epl://'):
            return url

        # Tennis, MMA/Boxing, and Racing APIs break with ?dates= parameter — skip them
        url_lower = url.lower()
        if '/tennis/' in url_lower or '/mma/' in url_lower or '/boxing/' in url_lower or '/racing/' in url_lower:
            return url

        # Query target and target - 1 day to cover all possible local-day timezone shifts.
        offset = self.ch_day_offset
        target = datetime.date.today() + datetime.timedelta(days=offset)
        t_prev = target - datetime.timedelta(days=1)
        
        date_range = "{}-{}".format(t_prev.strftime('%Y%m%d'), target.strftime('%Y%m%d'))
        sep = '&' if '?' in url else '?'
        return url + sep + 'dates=' + date_range


    def navigate_day(self, delta):
        """
        Shift ch_day_offset by delta (+1 = CH+, -1 = CH-).
        Clamps to [-7, +7]. Clears the event cache so a fresh fetch goes out
        immediately for the target date.
        Returns the new offset value (used by the screen for the hint label).
        """
        MAX_OFFSET = 7
        self.cancel_active_requests()   # Stop any in-flight fetch & lazy processing for the day we're leaving
        self.ch_day_offset = max(-MAX_OFFSET, min(MAX_OFFSET,
                                                  self.ch_day_offset + delta))
        # Flush stale cache — we're looking at a different day now
        self.cached_events    = []
        self.event_map        = {}
        self.match_snapshots  = {}
        self.status_message   = "Loading..."
        self._trigger_callbacks(False, bypass_debounce=True, force_refresh=True)      # show loading state immediately
        self.check_goals(from_ui=True)      # fire the dated request right away

        # Schedule a 2-second delayed forced secondary refresh pass to ensure UI renders
        try:
            from twisted.internet import reactor
            reactor.callLater(2.0, self._force_day_navigation_refresh)
        except Exception:
            pass

        return self.ch_day_offset

    def _force_day_navigation_refresh(self):
        """Forced secondary UI refresh pass 2 seconds after toggling days."""
        try:
            log_diag("[SportsMonitor] 2-second day navigation forced refresh pass (cached_events={})".format(len(self.cached_events)))
            self._trigger_callbacks(True, bypass_debounce=True, force_refresh=True)
        except Exception as e:
            log_dbg("[SportsMonitor] Day nav forced refresh error: " + str(e))

    def cancel_active_requests(self):
        """Cancel all in-flight Twisted Deferred requests."""
        if hasattr(self, 'active_deferreds') and self.active_deferreds:
            log_dbg("[SportsMonitor] Cancelling {} in-flight requests".format(len(self.active_deferreds)))
            for d in list(self.active_deferreds):
                try:
                    if not d.called:
                        d.cancel()
                except:
                    pass
            self.active_deferreds = []
        self.active_requests.clear()
        self.batch_is_active = False
        if self.batch_timer.isActive():
            self.batch_timer.stop()

        self.processing_queue = []
        if hasattr(self, 'lazy_processor') and self.lazy_processor and self.lazy_processor.active():
            try:
                self.lazy_processor.cancel()
            except:
                pass
            self.lazy_processor = None
        self.processing_active = False

    def _on_single_request_finished(self, result, url, d):
        self.active_requests.discard(url)
        if hasattr(self, 'active_deferreds') and d in self.active_deferreds:
            self.active_deferreds.remove(d)
        return result

    def _on_batch_request_finished(self, result, url, d):
        self.active_requests.discard(url)
        if hasattr(self, 'active_deferreds') and d in self.active_deferreds:
            self.active_deferreds.remove(d)
        return result

    def _fire_batch_request(self, name, url):
        # Guard: if the batch is no longer active (cancelled because user moved to another day), abort!
        if not self.batch_is_active:
            return

        # EuroLeague uses its own non-ESPN API; route through dedicated fetcher
        if url.startswith("euroleague://"):
            sentinel = "euroleague://api"
            if sentinel not in self.active_requests:
                self._fetch_euroleague_data(name)
            else:
                self.batch_remaining -= 1
            return

        # Egyptian Premier League uses official portal scraper; route through dedicated fetcher
        if url.startswith("epl://"):
            sentinel = "epl://api"
            if sentinel not in self.active_requests:
                self._fetch_epl_data(name)
            else:
                self.batch_remaining -= 1
            return

        fetch_url = self._build_dated_url(url)
        self.active_requests.add(url)
        try:
            d = self.agent.request(b'GET', fetch_url.encode('utf-8'), self.default_headers)
        except Exception as e:
            log_dbg("[SportsMonitor] Request failed immediately: " + str(e))
            self.batch_remaining -= 1
            return

        if not hasattr(self, 'active_deferreds'):
            self.active_deferreds = []
        self.active_deferreds.append(d)

        d.addCallback(readBody)
        d.addCallback(self.collect_batch_response_incremental, name, url)
        d.addErrback(self.collect_batch_error, url)
        d.addBoth(self._on_batch_request_finished, url, d)

        # 10-second per-request timeout
        timeout_call = reactor.callLater(10, d.cancel)
        d.addBoth(lambda x, tc=timeout_call: tc.cancel() if tc.active() else None)

    def set_discovery_mode(self, mode):
        """Set discovery mode directly: 0=OFF, 1=VISUAL, 2=SOUND."""
        old = self.discovery_mode
        self.discovery_mode = mode

        # FIX: active flag only controlled by mode, but timer checks reminders too
        self.active = (self.discovery_mode > 0)
        log_diag("MONITOR.set_discovery_mode: {} -> {} (0=OFF,1=VISUAL,2=SOUND) active={}".format(old, self.discovery_mode, self.active))

        # FIX: Clear pending notifications immediately when toggling OFF
        # This prevents queued notifications from showing after disabling Goal Alert
        if self.discovery_mode == 0:
            self.notification_queue = []
            self.notification_active = False

        self.ensure_timer_state()
        self.save_config()
        self._trigger_callbacks(True) # Ensure immediate UI update (button label)
        return self.discovery_mode

    def cycle_discovery_mode(self):
        new_mode = (self.discovery_mode + 1) % 3
        return self.set_discovery_mode(new_mode)

    def toggle_activity(self): return self.cycle_discovery_mode()

    def _get_timer_interval(self, live_count=0):
        """Return timer interval in ms."""
        # UI is active or Background-Live: 30s
        if len(self.callbacks) > 0 or live_count > 0:
            return 30000

        # Idle background: 300s (5 mins)
        return 300000

    def ensure_timer_state(self):
        # Timer should run if:
        # 1. Active (Discovery Mode ON)
        # 2. OR Reminders exist
        # 3. OR UI is active (callbacks registered) to ensure main screen updates
        should_run = self.active or (len(self.reminders) > 0) or (len(self.callbacks) > 0)

        if should_run:
            new_interval = self._get_timer_interval()
            if not self.timer.isActive():
                # ENSURE: single_shot=False (2nd param) to repeat automatically
                self.timer.start(new_interval, False)
                # If we just started, run a check immediately
                self.check_goals()
            else:
                # Timer already running - refresh interval ONLY if it changed (e.g. Screen opened)
                if getattr(self, '_last_interval', None) != new_interval:
                    self.timer.start(new_interval, False)
            self._last_interval = new_interval
        else:
            if self.timer.isActive():
                self.timer.stop()

