# FAVORITE TEAMS SCREENS
# ==============================================================================

class FavoriteTeamsManagerScreen(Screen):
    """Entry point from Settings → My Favorite Teams.
    Shows current saved teams; GREEN = add, RED = remove."""

    def __init__(self, session):
        Screen.__init__(self, session)
        if global_sports_monitor.theme_mode == "ucl":
            self.skin = scale_skin_xml("""
            <screen position="center,center" size="950,800" title="My Favorite Teams" backgroundColor="#00000000" flags="wfNoBorder">
                <eLabel position="0,0" size="950,800" backgroundColor="#0d1b2e" zPosition="-1" />
                <eLabel position="0,0" size="950,4" backgroundColor="#c9a020" zPosition="1" />
                <eLabel position="0,796" size="950,4" backgroundColor="#c9a020" zPosition="1" />
                <eLabel position="0,0" size="4,800" backgroundColor="#c9a020" zPosition="1" />
                <eLabel position="946,0" size="4,800" backgroundColor="#c9a020" zPosition="1" />
                <widget name="header" position="30,20" size="890,50" font="SimplySportFont;38" foregroundColor="#c9a020" backgroundColor="#0d1b2e" transparent="1" halign="center" />
                <eLabel position="30,75" size="890,2" backgroundColor="#1a3a6b" />
                <widget name="list" position="30,90" size="890,600" scrollbarMode="showOnDemand" transparent="1" />
                <eLabel position="30,700" size="890,2" backgroundColor="#1a3a6b" />
                <widget name="info" position="30,715" size="890,30" font="SimplySportFont;24" foregroundColor="#c9a020" backgroundColor="#0d1b2e" transparent="1" halign="center" valign="center" />
                <eLabel position="30,750" size="890,2" backgroundColor="#1a3a6b" />
                <widget name="key_red" position="30,760" size="200,30" font="SimplySportFont;26" foregroundColor="#FFFFFF" backgroundColor="#F44336" transparent="0" zPosition="1" halign="center" valign="center" />
                <widget name="key_green" position="720,760" size="200,30" font="SimplySportFont;26" foregroundColor="#000000" backgroundColor="#00FF85" transparent="0" zPosition="1" halign="center" valign="center" />
            </screen>
            """)
        else:
            self.skin = scale_skin_xml("""
            <screen position="center,center" size="950,800" title="My Favorite Teams" backgroundColor="#38003C" flags="wfNoBorder">
                <eLabel position="0,0" size="950,800" backgroundColor="#38003C" zPosition="-1" />
                <eLabel position="0,0" size="950,4" backgroundColor="#00FF85" zPosition="1" />
                <eLabel position="0,796" size="950,4" backgroundColor="#00FF85" zPosition="1" />
                <eLabel position="0,0" size="4,800" backgroundColor="#00FF85" zPosition="1" />
                <eLabel position="946,0" size="4,800" backgroundColor="#00FF85" zPosition="1" />
                <widget name="header" position="30,20" size="890,50" font="SimplySportFont;38" foregroundColor="#00FF85" backgroundColor="#38003C" transparent="1" halign="center" />
                <eLabel position="30,75" size="890,2" backgroundColor="#505050" />
                <widget name="list" position="30,90" size="890,600" scrollbarMode="showOnDemand" transparent="1" />
                <eLabel position="30,700" size="890,2" backgroundColor="#505050" />
                <widget name="info" position="30,715" size="890,30" font="SimplySportFont;24" foregroundColor="#9E9E9E" backgroundColor="#38003C" transparent="1" halign="center" valign="center" />
                <eLabel position="30,750" size="890,2" backgroundColor="#505050" />
                <widget name="key_red" position="30,760" size="200,30" font="SimplySportFont;26" foregroundColor="#FFFFFF" backgroundColor="#F44336" transparent="0" zPosition="1" halign="center" valign="center" />
                <widget name="key_green" position="720,760" size="200,30" font="SimplySportFont;26" foregroundColor="#000000" backgroundColor="#00FF85" transparent="0" zPosition="1" halign="center" valign="center" />
            </screen>
            """)
        self["header"]    = Label(_t("My Favorite Teams"))
        self["list"]      = MenuList([], enableWrapAround=True, content=eListboxPythonMultiContent)
        self["list"].l.setFont(0, gFont("SimplySportFont", sf(28)))   # team name
        self["list"].l.setFont(1, gFont("SimplySportFont", sf(21)))   # league name (smaller)
        self["list"].l.setItemHeight(sy(60))                           # two-line rows
        self["key_red"]   = Label(_t("Remove"))
        self["key_green"] = Label(_t("Add Another Team"))
        self["info"]      = Label("")
        self["actions"]   = ActionMap(
            ["OkCancelActions", "ColorActions", "DirectionActions"],
            {
                "cancel": self.close,
                "red":    self.remove_selected,
                "green":  self.open_league_selector,
                "ok":     self.remove_selected,
                "up":     self["list"].up,
                "down":   self["list"].down,
            }, -1
        )
        # One-shot timer: refresh list after logos finish downloading
        self._logo_refresh_timer = eTimer()
        safe_connect(self._logo_refresh_timer, self._on_logo_timer)
        self._logo_refresh_pending = False
        self.onLayoutFinish.append(self.refresh_list)

    def _on_logo_timer(self):
        """Called ~3 s after refresh_list found missing logos — redraw with newly cached art."""
        self._logo_refresh_timer.stop()
        self._logo_refresh_pending = False
        self.refresh_list()

    def refresh_list(self):
        teams = global_sports_monitor.favorite_teams
        count = len(teams)
        self["info"].setText("{}/10 {}".format(count, _t("teams")))

        needs_logo_refresh = False
        items = []

        for t in teams:
            team_name   = t.get("team_name",  "?")
            league_name = _league_name(t.get("league_name", "?"))   # translated
            team_id     = t.get("team_id",    "")
            logo_url    = t.get("logo_url",   "")
            cache_key   = "soccer_fav_" + str(team_id)
            logo_cache  = global_sports_monitor.logo_path_cache

            # ── resolve logo path ────────────────────────────────────────────
            logo_path = logo_cache.get(cache_key)
            if not logo_path:
                # Check disk directly (in case prefetch finished but cache not updated)
                candidate = "/tmp/simplysports/logos/{}.png".format(cache_key)
                if os.path.exists(candidate) and os.path.getsize(candidate) > 0:
                    logo_path = candidate
                    logo_cache[cache_key] = candidate
                    GLOBAL_VALID_LOGO_PATHS.add(candidate)
                elif logo_url and team_id:
                    # Kick off async download; refresh the list after a short delay
                    global_sports_monitor.prefetch_logo(logo_url, cache_key)
                    needs_logo_refresh = True

            # ── build row ────────────────────────────────────────────────────
            row = [(team_name, False)]

            logo_ok = False
            if logo_path:
                # Validate before attempting to render
                if logo_path not in GLOBAL_VALID_LOGO_PATHS:
                    if os.path.exists(logo_path) and os.path.getsize(logo_path) > 0:
                        GLOBAL_VALID_LOGO_PATHS.add(logo_path)
                if logo_path in GLOBAL_VALID_LOGO_PATHS:
                    try:
                        pix = get_scaled_pixmap(logo_path, 40, 40)
                        if pix:
                            row.append((eListboxPythonMultiContent.TYPE_PIXMAP_ALPHATEST,
                                        15, 10, 40, 40, pix))
                            logo_ok = True
                    except Exception:
                        pass

            text_x = 65 if logo_ok else 15

            if not logo_ok:
                # Gold star placeholder when logo is absent / still downloading
                row.append((eListboxPythonMultiContent.TYPE_TEXT,
                             15, 10, 40, 40, 0,
                             RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                             u"\u2605", 0xCCAA00, 0xCCAA00, None, None))

            # Line 1 — team name (font 0, 28 px)
            row.append((eListboxPythonMultiContent.TYPE_TEXT,
                         text_x, 4, 860 - text_x, 28, 0,
                         RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                         team_name, 0xFFFFFF, 0xFFFFFF, None, None))

            # Line 2 — league name, translated (font 1, 21 px)
            row.append((eListboxPythonMultiContent.TYPE_TEXT,
                         text_x, 34, 860 - text_x, 22, 1,
                         RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                         league_name, 0x9E9E9E, 0x9E9E9E, None, None))

            items.append(row)

        if not items:
            row = [(_t("No teams added yet."), False)]
            row.append((eListboxPythonMultiContent.TYPE_TEXT,
                         15, 10, 860, 40, 0,
                         RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                         _t("No teams added yet."), 0x9E9E9E, 0x9E9E9E, None, None))
            items.append(row)

        self["list"].setList(items)

        # Schedule one deferred refresh so logos that finish downloading appear
        if needs_logo_refresh and not self._logo_refresh_pending:
            self._logo_refresh_pending = True
            self._logo_refresh_timer.start(3000, True)

    def remove_selected(self):
        idx   = self["list"].getSelectedIndex()
        teams = global_sports_monitor.favorite_teams
        # Guard: idx can be None on some Enigma2 builds; also guard empty list
        if idx is None or not teams or idx >= len(teams):
            return
        removed = teams.pop(idx)
        global_sports_monitor.save_config()
        self.refresh_list()
        self.session.open(
            MessageBox,
            removed.get("team_name", "Team") + " " + _t("Team removed from favorites"),
            MessageBox.TYPE_INFO, timeout=2
        )

    def open_league_selector(self):
        if len(global_sports_monitor.favorite_teams) >= 10:
            self.session.open(MessageBox, _t("Favorites limit reached (10)"),
                              MessageBox.TYPE_INFO, timeout=3)
            return
        self.session.openWithCallback(self.on_team_added, FavoriteTeamLeagueSelector)

    def on_team_added(self, result=None):
        self.refresh_list()


