    def cancel(self):
        self.close(None)

    def assign_key_8(self):
        idx = self["list"].getSelectedIndex()
        if idx is None or idx < 0:
            return
        if hasattr(self, '_list_to_sorted') and self._list_to_sorted:
            if idx >= len(self._list_to_sorted): return
            sorted_idx = self._list_to_sorted[idx]
            if sorted_idx < 0 or sorted_idx >= len(self.sorted_indices): return
            original_idx = self.sorted_indices[sorted_idx]
        elif hasattr(self, 'sorted_indices') and self.sorted_indices:
            if idx >= len(self.sorted_indices): return
            original_idx = self.sorted_indices[idx]
        else:
            return

        if original_idx < 0 or original_idx >= len(DATA_SOURCES):
            return

        league_name = DATA_SOURCES[original_idx][0]
        global_sports_monitor.key8_league_index = original_idx
        global_sports_monitor.save_config()
        msg = (_t("League assigned to Key 8: ") + _league_name(league_name))
        self.session.open(MessageBox, msg, MessageBox.TYPE_INFO, timeout=3)

    def get_league_priority(self, league_name):
        """Return priority value for sorting (lower = higher priority)"""
        # Use exact matching only to avoid "Premier League" matching "Canadian Premier League"
        for i, major in enumerate(self.MAJOR_LEAGUES):
            if league_name == major:
                return i
        return 1000  # Non-major leagues go last

    # Sport group ordering (lower = higher in the list)
    SPORT_GROUP_ORDER = {
        'soccer': 0, 'basketball': 1, 'football': 2, 'hockey': 3,
        'baseball': 4, 'racing': 5, 'tennis': 6, 'rugby': 7,
        'rugby-league': 8, 'cricket': 9, 'golf': 10,
        'boxing': 11, 'mma': 12, 'lacrosse': 13
    }

    def _get_sport_from_url(self, url):
        """Extract sport name from API URL for grouping."""
        # EuroLeague sentinel URL — classify as basketball
        if url.startswith("euroleague://"):
            return 'basketball'
        # Egyptian Premier League sentinel URL — classify as soccer
        if url.startswith("epl://"):
            return 'soccer'
        try:
            parts = url.split('/sports/')
            if len(parts) > 1:
                return parts[1].split('/')[0]
        except: pass
        return 'other'

    def _is_women_league(self, name, url):
        """Check if league is a women's league from name or URL."""
        name_lower = name.lower()
        url_lower = url.lower()
        women_markers = ["women", "woman", "wnba", ".w.", ".w/", "wsl", "nwsl", "wchampions"]
        for m in women_markers:
            if m in name_lower or m in url_lower:
                return True
        return False

    def load_list(self):
        # Multi mode reads saved_custom_league_indices so the Custom Leagues editor
        # always reflects the actual custom selection, even if Favorite Leagues has
        # temporarily overwritten custom_league_indices for display.
        current_indices = (
            global_sports_monitor.saved_custom_league_indices
            if self.mode == "multi"
            else global_sports_monitor.custom_league_indices
        )

        # Load saved favourites from file for heart display
        saved_fav_names = set()
        self._favorites_data = []
        try:
            if os.path.exists(FAVORITE_LEAGUES_FILE):
                with open(FAVORITE_LEAGUES_FILE, "r") as _f:
                    _fdata = json.load(_f)
                    self._favorites_data = _fdata.get("favorite_leagues", [])
                    for _entry in self._favorites_data:
                        saved_fav_names.add(_entry.get("name", ""))
        except Exception:
            pass

        # Create list of (original_idx, name, is_selected, priority, sport, is_women) for sorting
        league_items = []
        for i in range(len(DATA_SOURCES)):
            name = DATA_SOURCES[i][0]
            url = DATA_SOURCES[i][1]
            # In multi mode: filter out racing leagues (they only work in single-league)
            if self.mode == "multi" and get_sport_type(url) == SPORT_TYPE_RACING:
                continue
            # In multi mode: also filter out EuroLeague (uses its own API, single-league only)
            if self.mode == "multi" and url.startswith("euroleague://"):
                continue
            is_selected = i in current_indices
            priority = self.get_league_priority(name)
            sport = self._get_sport_from_url(url)
            is_women = self._is_women_league(name, url)
            league_items.append((i, name, is_selected, priority, sport, is_women))

        # Sort: sport group order → women last within group → major leagues first → alphabetical
        league_items.sort(key=lambda x: (
            self.SPORT_GROUP_ORDER.get(x[4], 99),  # Sport group order
            1 if x[5] else 0,                       # Women's leagues at end of group
            x[3],                                   # Priority (major leagues first)
            x[1]                                    # Alphabetical name
        ))

        # Store sorted order
        self.sorted_indices = [item[0] for item in league_items]
        self.selections = [item[2] for item in league_items]
        # Store sport info for group headers
        self._league_sports = [item[4] for item in league_items]
        self._league_women = [item[5] for item in league_items]

        # Build heart_selections: True if this league is in saved favourites
        self.heart_selections = []
        for orig_idx in self.sorted_indices:
            league_name = DATA_SOURCES[orig_idx][0]
            self.heart_selections.append(league_name in saved_fav_names)

        # Pre-seed bundled & cached logos before initial render for instant display
        for sorted_idx, orig_idx in enumerate(self.sorted_indices):
            url = DATA_SOURCES[orig_idx][1]
            logo_id = "league_{}".format(orig_idx)
            logo_file = self.logo_path + logo_id + ".png"
            if is_epl_logo_request(url, None):
                bundled_epl = get_bundled_epl_logo_path()
                if bundled_epl:
                    try:
                        if not os.path.exists(self.logo_path): os.makedirs(self.logo_path)
                        if not os.path.exists(logo_file) or os.path.getsize(logo_file) < 100:
                            import shutil
                            shutil.copyfile(bundled_epl, logo_file)
                        self.league_logos[sorted_idx] = logo_file
                    except Exception: pass
            elif os.path.exists(logo_file) and os.path.getsize(logo_file) > 100:
                self.league_logos[sorted_idx] = logo_file

        # Instant initial render (< 50ms)
        self.refresh_list()

        # Defer background logo check and downloads until screen is visible
        self._logo_bg_timer = eTimer()
        safe_connect(self._logo_bg_timer, self.download_league_logos)
        self._logo_bg_timer.start(100, True)

    def download_league_logos(self):
        """Asynchronously load and download league logos in background without blocking screen opening"""
        from twisted.web.client import downloadPage
        needs_refresh = False
        for sorted_idx, original_idx in enumerate(self.sorted_indices):
            url = DATA_SOURCES[original_idx][1]
            logo_id = "league_{}".format(original_idx)
            logo_file = self.logo_path + logo_id + ".png"

            # -----------------------------------------------------------------
            # CHOICE 1 (PRIMARY): Use bundled epl_logo.png for Egyptian Premier League
            # -----------------------------------------------------------------
            if is_epl_logo_request(url, None):
                bundled_epl = get_bundled_epl_logo_path()
                if bundled_epl:
                    try:
                        if not os.path.exists(self.logo_path): os.makedirs(self.logo_path)
                        if not os.path.exists(logo_file) or os.path.getsize(logo_file) < 100:
                            import shutil
                            shutil.copyfile(bundled_epl, logo_file)
                        if self.league_logos.get(sorted_idx) != logo_file:
                            self.league_logos[sorted_idx] = logo_file
                            needs_refresh = True
                        continue
                    except Exception:
                        pass

            # -----------------------------------------------------------------
            # CHOICE 2 (FALLBACK): Existing valid disk cache
            # -----------------------------------------------------------------
            if os.path.exists(logo_file) and os.path.getsize(logo_file) > 0:
                if self.league_logos.get(sorted_idx) != logo_file:
                    self.league_logos[sorted_idx] = logo_file
                    needs_refresh = True
            else:
                # -------------------------------------------------------------
                # CHOICE 3 & 4 (FALLBACK): Network download & SSL fallback
                # -------------------------------------------------------------
                try:
                    logo_url = self.get_league_logo_url(url, original_idx)
                    if logo_url:
                        headers = {b'User-Agent': b'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
                        downloadPage(logo_url.encode('utf-8'), logo_file, headers=headers, timeout=10).addCallback(
                            self.logo_downloaded, sorted_idx, logo_file).addErrback(self.logo_error, sorted_idx, logo_file, logo_url)
                except: pass

        if needs_refresh:
            self.refresh_list()

    def get_league_logo_url(self, api_url, idx):
        """Generate ESPN logo URL from API endpoint"""
        # EuroLeague uses its own API — no ESPN logo is available
