    def logo_downloaded(self, result, idx, logo_file):
        self.league_logos[idx] = logo_file
        # Debounce refresh so we don't rebuild the entire list for each individual image
        if not hasattr(self, '_batch_logo_timer'):
            self._batch_logo_timer = eTimer()
            safe_connect(self._batch_logo_timer, self.refresh_list)
        self._batch_logo_timer.start(350, True)

    def logo_error(self, error, sorted_idx=None, logo_file=None, logo_url=None):
        if logo_url and "egyptianproleague" in str(logo_url) and logo_file and sorted_idx is not None:
            def _thread_fallback():
                try:
                    import urllib.request as _urllib, ssl as _ssl
                    _ctx = _ssl.create_default_context()
                    _ctx.check_hostname = False
                    _ctx.verify_mode = _ssl.CERT_NONE
                    _req = _urllib.Request(logo_url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'})
                    with _urllib.urlopen(_req, context=_ctx, timeout=8) as _resp:
                        _data = _resp.read()
                        if _data and len(_data) > 100:
                            with open(logo_file, 'wb') as _f: _f.write(_data)
                            reactor.callFromThread(self.logo_downloaded, _data, sorted_idx, logo_file)
                except Exception:
                    pass
            _t = threading.Thread(target=_thread_fallback)
            _t.daemon = True
            _t.start()

    # Display names for sport groups
    SPORT_DISPLAY_NAMES = {
        'soccer': 'SOCCER', 'basketball': 'BASKETBALL', 'football': 'AMERICAN FOOTBALL',
        'hockey': 'ICE HOCKEY', 'baseball': 'BASEBALL', 'racing': 'RACING',
        'tennis': 'TENNIS', 'rugby': 'RUGBY UNION', 'rugby-league': 'RUGBY LEAGUE',
        'cricket': 'CRICKET', 'golf': 'GOLF', 'boxing': 'BOXING',
        'mma': 'MMA', 'lacrosse': 'LACROSSE'
    }

    def refresh_list(self):
        list_content = []
        # Map from list index -> sorted_idx (skipping headers for toggle)
        self._list_to_sorted = []
        current_sport = None

        theme = global_sports_monitor.theme_mode
        c_header_bg = 0x0d1b2e if theme == 'ucl' else 0x2a0030
        c_header_fg = 0xc9a020 if theme == 'ucl' else 0x00FF85

        for sorted_idx, original_idx in enumerate(self.sorted_indices):
            # Insert sport group header when sport changes
            sport = self._league_sports[sorted_idx] if hasattr(self, '_league_sports') else None
            if sport and sport != current_sport:
                current_sport = sport
                sport_label = _t(self.SPORT_DISPLAY_NAMES.get(sport, sport.upper()))
                # Check if this group also starts women's section
                is_women_start = self._league_women[sorted_idx] if hasattr(self, '_league_women') else False
                if is_women_start:
                    sport_label += u" " + _t("(WOMEN)")
                # Create header entry (non-selectable)
                header = [('__GROUP__', False)]
                header.append((eListboxPythonMultiContent.TYPE_TEXT, 0, 0, 890, 50, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, "", c_header_bg, c_header_bg, None, None))
                header.append((eListboxPythonMultiContent.TYPE_TEXT, 15, 0, 860, 50, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, u"\u25B6 " + sport_label, c_header_fg, c_header_fg, None, None))
                header.append((eListboxPythonMultiContent.TYPE_TEXT, 15, 46, 860, 4, 0, RT_HALIGN_LEFT, "", c_header_fg, c_header_fg, None, None))
                list_content.append(header)
                self._list_to_sorted.append(-1)  # -1 = header, not selectable
            elif sport == current_sport and hasattr(self, '_league_women'):
                # Check for women transition within same sport
                is_women = self._league_women[sorted_idx]
                prev_women = self._league_women[sorted_idx - 1] if sorted_idx > 0 else False
                if is_women and not prev_women:
                    sport_label = _t(self.SPORT_DISPLAY_NAMES.get(sport, sport.upper())) + u" " + _t("(WOMEN)")
                    header = [('__GROUP__', False)]
                    header.append((eListboxPythonMultiContent.TYPE_TEXT, 0, 0, 890, 50, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, "", c_header_bg, c_header_bg, None, None))
                    header.append((eListboxPythonMultiContent.TYPE_TEXT, 15, 0, 860, 50, 0, RT_HALIGN_LEFT|RT_VALIGN_CENTER, u"\u25B6 " + sport_label, c_header_fg, c_header_fg, None, None))
                    header.append((eListboxPythonMultiContent.TYPE_TEXT, 15, 46, 860, 4, 0, RT_HALIGN_LEFT, "", c_header_fg, c_header_fg, None, None))
                    list_content.append(header)
                    self._list_to_sorted.append(-1)

            name = _league_name(DATA_SOURCES[original_idx][0])
            is_selected = self.selections[sorted_idx]
            logo_path = self.league_logos.get(sorted_idx, None)
            # Determine heart state for single mode
            heart = None
            if self.mode == "single" and hasattr(self, 'heart_selections') and sorted_idx < len(self.heart_selections):
                heart = self.heart_selections[sorted_idx]
            list_content.append(SelectionListEntry(name, is_selected, logo_path, mode=self.mode, heart=heart))
            self._list_to_sorted.append(sorted_idx)
        self["list"].setList(list_content)

    def toggle(self):
        list_idx = self["list"].getSelectedIndex()
        if list_idx is None: return
        # Map list index to sorted index (skip group headers)
        if not hasattr(self, '_list_to_sorted') or list_idx >= len(self._list_to_sorted):
            return
        sorted_idx = self._list_to_sorted[list_idx]
        if sorted_idx < 0: return  # Group header, skip

        if self.mode == "multi":
            self.selections[sorted_idx] = not self.selections[sorted_idx]
            self.refresh_list()
            # Restore cursor position after refresh
            try: self["list"].moveToIndex(list_idx)
            except: pass
        else:
            # Single mode: immediately return the selected original index
            original_idx = self.sorted_indices[sorted_idx]
            self.close((DATA_SOURCES[original_idx][0], original_idx))

    def save(self):
        if self.mode != "multi": return
        new_indices = []
        for sorted_idx, is_selected in enumerate(self.selections):
            if is_selected:
                # Map back to original DATA_SOURCES index
                original_idx = self.sorted_indices[sorted_idx]
                new_indices.append(original_idx)

        if not new_indices:
            self.session.open(MessageBox, "Please select at least one league.", MessageBox.TYPE_ERROR)
        else:
            global_sports_monitor.set_custom_leagues(new_indices)
            self.close(True)

    # ------------------------------------------------------------------
    # FAVOURITE LEAGUES — heart toggle & persistence
    # ------------------------------------------------------------------

    def toggle_heart(self):
        """RED button in single mode: toggle the heart on the focused item."""
        list_idx = self["list"].getSelectedIndex()
        if list_idx is None: return
        if not hasattr(self, '_list_to_sorted') or list_idx >= len(self._list_to_sorted):
            return
        sorted_idx = self._list_to_sorted[list_idx]
        if sorted_idx < 0: return  # group header

        self.heart_selections[sorted_idx] = not self.heart_selections[sorted_idx]
        self.refresh_list()
        try: self["list"].moveToIndex(list_idx)
        except: pass

    def save_favorites(self):
        """GREEN button in single mode: persist all hearts to FAVORITE_LEAGUES_FILE."""
        favorites = []
        for sorted_idx, original_idx in enumerate(self.sorted_indices):
            if self.heart_selections[sorted_idx]:
                name = DATA_SOURCES[original_idx][0]
                url  = DATA_SOURCES[original_idx][1]
                favorites.append({"name": name, "url": url, "active": True})

        try:
            with open(FAVORITE_LEAGUES_FILE, "w") as ffile:
                json.dump({"favorite_leagues": favorites}, ffile, indent=2)
            self["info"].setText(_t("Favorites saved!"))
        except Exception as e:
            self["info"].setText("Error saving: " + str(e))

    def apply_favorites(self):
        """GREEN button in favorite mode: activate checked favourite leagues."""
        # Update active flags in the JSON file and apply to monitor
        active_names = set()
        for sorted_idx, is_sel in enumerate(self.selections):
            original_idx = self.sorted_indices[sorted_idx]
            name = DATA_SOURCES[original_idx][0]
            url  = DATA_SOURCES[original_idx][1]
            if is_sel or url.startswith("euroleague://"):
                active_names.add(name)

        # Rebuild favorites list with updated active flags
        try:
            fav_list = []
            if os.path.exists(FAVORITE_LEAGUES_FILE):
                with open(FAVORITE_LEAGUES_FILE, "r") as ff:
                    fav_list = json.load(ff).get("favorite_leagues", [])
            for entry in fav_list:
                entry["active"] = entry.get("locked", False) or (entry.get("name", "") in active_names)
            with open(FAVORITE_LEAGUES_FILE, "w") as ff:
                json.dump({"favorite_leagues": fav_list}, ff, indent=2)
        except Exception:
            pass

        # Map active favourite names to DATA_SOURCES indices
        new_indices = []
        for sorted_idx, original_idx in enumerate(self.sorted_indices):
            name = DATA_SOURCES[original_idx][0]
            if name in active_names:
                new_indices.append(original_idx)

        if not new_indices:
            self.session.open(MessageBox, "Please select at least one favourite league.", MessageBox.TYPE_ERROR)
        else:
            global_sports_monitor.set_custom_leagues(new_indices)
            self.close(True)


    def check_for_updates(self):
        """Red button in multi mode: check for newly discovered leagues from the remote catalog."""
        self["info"].setText(_t("Checking for updates..."))
        self["key_red"].setText(_t("Checking..."))
        # Use callLater to allow the UI label to repaint before the blocking fetch
        from twisted.internet import reactor
        reactor.callLater(0.1, self._do_catalog_fetch)

    def _do_catalog_fetch(self):
        """Synchronous fetch of the remote leagues catalog (called after a short UI delay)."""
        try:
            import ssl
            try:
                from urllib.request import Request, urlopen
            except ImportError:
                from urllib2 import Request, urlopen
            url = "{}/leagues_catalog.json".format(FIREBASE_URL)
            req = Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            try:
                context = ssl._create_unverified_context()
                response = urlopen(req, timeout=8, context=context)
            except AttributeError:
                response = urlopen(req, timeout=8)
            raw = response.read()
            if isinstance(raw, bytes):
                raw = raw.decode('utf-8', errors='ignore')
            if not raw or raw == "null":
                self["info"].setText(_t("No updates available"))
                self["key_red"].setText(_t("Update Leagues"))
                return
            catalog = json.loads(raw)
            if not isinstance(catalog, list):
                self["info"].setText(_t("No updates available"))
                self["key_red"].setText(_t("Update Leagues"))
                return

            existing_slugs = set(get_slug_from_url(u) for _, u in DATA_SOURCES)
            new_entries = []
            for entry in catalog:
                c_name = entry.get("name", "")
                c_url  = entry.get("url", "")
                c_slug = get_slug_from_url(c_url)
                if c_slug and c_slug not in existing_slugs and c_name and c_url:
                    new_entries.append({"name": c_name, "url": c_url})

            if new_entries:
                names_preview = "\n".join("  \u2022 " + e["name"] for e in new_entries[:10])
                if len(new_entries) > 10:
                    names_preview += "\n  ... and {} more".format(len(new_entries) - 10)
                self.session.openWithCallback(
                    lambda confirmed: self._apply_discovered(new_entries) if confirmed else None,
                    MessageBox,
                    _t("{} new leagues found:\n\n{}\n\nAdd to your leagues list?").format(len(new_entries), names_preview),
                    MessageBox.TYPE_YESNO
                )
                self["info"].setText(_t("{} new leagues found!").format(len(new_entries)))
            else:
                self["info"].setText(_t("All leagues up to date!"))
            self["key_red"].setText(_t("Update Leagues"))
        except Exception as e:
            log_dbg("[UpdateLeagues] Fetch failed: " + str(e))
            self["info"].setText(_t("Could not reach server"))
            self["key_red"].setText(_t("Update Leagues"))

    def _apply_discovered(self, new_entries):
        """Persist newly discovered leagues and reload the list."""
        global SLUG_TO_IDX, IDX_TO_SLUG
        try:
            # Load existing discovered entries
            existing = []
            if os.path.exists(DISCOVERED_LEAGUES_FILE):
                with open(DISCOVERED_LEAGUES_FILE, "r") as _df:
                    existing = json.load(_df)
            if not isinstance(existing, list):
                existing = []
            # Merge new entries (deduplicate by slug)
            existing_slugs = set(get_slug_from_url(e.get("url", "")) for e in existing)
            for entry in new_entries:
                e_slug = get_slug_from_url(entry.get("url", ""))
                if e_slug not in existing_slugs:
                    existing.append(entry)
                    existing_slugs.add(e_slug)
            # Persist to disk
            with open(DISCOVERED_LEAGUES_FILE, "w") as _df:
                json.dump(existing, _df, indent=2)
            # Extend DATA_SOURCES in memory
            ds_slugs = set(get_slug_from_url(u) for _, u in DATA_SOURCES)
            for entry in new_entries:
                e_slug = get_slug_from_url(entry.get("url", ""))
                if e_slug not in ds_slugs:
                    DATA_SOURCES.append((entry["name"], entry["url"]))
                    if "/sports/soccer/" in entry["url"]:
                        SOCCER_DATA_SOURCES.append((entry["name"], entry["url"]))
                    ds_slugs.add(e_slug)
            # Rebuild slug maps
            SLUG_TO_IDX, IDX_TO_SLUG = _build_slug_maps()
            # Reload the selector list so new leagues appear immediately
            self.load_list()
            self["info"].setText(_t("{} leagues added!").format(len(new_entries)))
        except Exception as e:
            self["info"].setText(_t("Error saving: ") + str(e)[:40])


