def smart_match_team(name1, name2):
    if not name1 or not name2:
        return False
    try:
        if isinstance(name1, dict):
            name1 = name1.get('displayName') or name1.get('name') or str(name1)
        elif not isinstance(name1, (str, type(u""))):
            name1 = str(name1)
        if isinstance(name2, dict):
            name2 = name2.get('displayName') or name2.get('name') or str(name2)
        elif not isinstance(name2, (str, type(u""))):
            name2 = str(name2)

        n1 = name1.strip().lower()
        n2 = name2.strip().lower()
    except Exception:
        return False

    try:
        if isinstance(n1, bytes):
            n1 = n1.decode('utf-8', 'ignore')
    except:
        pass
    try:
        if isinstance(n2, bytes):
            n2 = n2.decode('utf-8', 'ignore')
    except:
        pass

    n1 = _ascii_fold(n1)
    n2 = _ascii_fold(n2)

    if n1 == n2:
        return True

    n1 = _TEAM_SYNONYMS.get(n1, n1)
    n2 = _TEAM_SYNONYMS.get(n2, n2)
    if n1 == n2:
        return True

    for char in ["-", "'", ".", ",", "(", ")"]:
        n1 = n1.replace(char, " ")
        n2 = n2.replace(char, " ")
    tokens1 = [w for w in n1.split() if w]
    tokens2 = [w for w in n2.split() if w]
    if not tokens1 or not tokens2:
        return False

    s_tok1 = set(tokens1)
    s_tok2 = set(tokens2)

    # Check special modifiers (women, youth, B-teams)
    special_modifiers = {"women", "w", "femeni", "femenino", "ladies", "frauen", "b", "ii", "2", "u19", "u21", "u23", "jong", "nxt", "futures", "castilla", "youth", "reserves"}
    m1 = s_tok1.intersection(special_modifiers)
    m2 = s_tok2.intersection(special_modifiers)
    if m1 != m2:
        return False

    # Check derby / distinct club specifier conflicts
    derby_specifiers = {"city", "united", "utd", "rovers", "wednesday", "victory", "town", "county", "albion", "wanderers", "hotspur", "forest", "villa", "crystal", "athletic", "ath", "real", "atletico", "sporting", "racing", "inter", "sparta", "spartak", "slavia", "dinamo", "dynamo", "lokomotiv", "olympic", "olympique"}
    d1 = s_tok1.intersection(derby_specifiers)
    d2 = s_tok2.intersection(derby_specifiers)
    if d1 and d2 and d1 != d2:
        return False

    safe_stop_words = {
        "and", "of", "the", "for", "de", "la", "le", "el", "al", "del", "los", "las", "da", "do", "dos", "das", "di", "du",
        "fc", "cf", "sc", "ac", "cd", "sk", "fk", "afc", "c.f.", "f.c.", "club", "clube", "association", "football", "soccer", "futbol", "futebol"
    }

    f1 = [w for w in tokens1 if w not in safe_stop_words]
    f2 = [w for w in tokens2 if w not in safe_stop_words]
    if not f1 or not f2:
        return False

    if f1 == f2 or set(f1) == set(f2):
        return True

    return False


def find_player_image(country_name, player_name, shirt_no=""):
    try:
        images_root = resolveFilename(SCOPE_PLUGINS,
            "Extensions/SimplySports/WorldCup_players_Images/")
        fallback = os.path.join(images_root, "player.png")
        if not os.path.exists(fallback):
            fallback = os.path.join(images_root, "player.jpg")
        if not os.path.isdir(images_root):
            return fallback

        lookup_name = country_name.strip()
        country_folder = os.path.join(images_root, lookup_name)
        if not os.path.isdir(country_folder):
            try:
                matched = False
                best_dist, best_path = 99, None
                lookup_folded = _ascii_fold(lookup_name.lower())
                for entry in os.listdir(images_root):
                    entry_path = os.path.join(images_root, entry)
                    if not os.path.isdir(entry_path):
                        continue
                    # Pass 1: semantic match (synonyms, tokens, abbreviations)
                    if smart_match_team(lookup_name, entry):
                        country_folder = entry_path
                        matched = True
                        break
                    # Pass 2: Levenshtein edit-distance <= 2 on folded names
                    entry_folded = _ascii_fold(entry.lower())
                    la, lb = len(lookup_folded), len(entry_folded)
                    if abs(la - lb) <= 2:
                        prev = list(range(lb + 1))
                        for ca in lookup_folded:
                            curr = [prev[0] + 1]
                            for j, cb in enumerate(entry_folded):
                                curr.append(min(prev[j] + (0 if ca == cb else 1),
                                               curr[j] + 1, prev[j + 1] + 1))
                            prev = curr
                        dist = prev[lb]
                        if dist < best_dist:
                            best_dist, best_path = dist, entry_path
                if not matched:
                    if best_dist <= 2 and best_path:
                        country_folder = best_path
                    else:
                        return fallback
            except Exception:
                return fallback

        try:
            files = [f for f in os.listdir(country_folder)
                     if f.lower().endswith(('.png', '.jpg', '.jpeg'))]
        except Exception:
            return fallback

        # Strategy 1: shirt number (unique per squad)
        if shirt_no:
            for fname in files:
                parts = os.path.splitext(fname)[0].split('_')
                if len(parts) >= 3 and parts[-2] == str(shirt_no):
                    return os.path.join(country_folder, fname)

        # Strategy 2: full name token match
        norm_name = _ascii_fold((player_name or '').lower()).replace('.', '').replace("'", '').replace('-', ' ')
        name_tokens = [t for t in norm_name.split() if len(t) > 2]
        if name_tokens:
            for fname in files:
                fname_norm = _ascii_fold(os.path.splitext(fname)[0].lower()).replace('_', ' ')
                if all(tok in fname_norm for tok in name_tokens):
                    return os.path.join(country_folder, fname)
            # Strategy 3: last name only
            last = name_tokens[-1]
            for fname in files:
                fname_norm = _ascii_fold(os.path.splitext(fname)[0].lower()).replace('_', ' ')
                if last in fname_norm:
                    return os.path.join(country_folder, fname)

        return fallback
    except Exception:
        try:
            images_root = resolveFilename(SCOPE_PLUGINS,
                "Extensions/SimplySports/WorldCup_players_Images/")
            fallback = os.path.join(images_root, "player.png")
            if not os.path.exists(fallback):
                fallback = os.path.join(images_root, "player.jpg")
            return fallback
        except Exception:
            return None


def get_formation_layout(players):
    groups = {'GK': [], 'DEF': [], 'MID': [], 'FWD': []}
    for p in players:
        pos = (p.get('position') or '').upper().strip()
        if pos in _POS_GK:
            groups['GK'].append(p)
        elif pos in _POS_DEF:
            groups['DEF'].append(p)
        elif pos in _POS_MID:
            groups['MID'].append(p)
        elif pos in _POS_FWD:
            groups['FWD'].append(p)
        else:
            if not groups['GK']:
                groups['GK'].append(p)
            elif len(groups['FWD']) <= len(groups['MID']) - 2:
                groups['FWD'].append(p)
            else:
                groups['MID'].append(p)
    formation = '{}-{}-{}'.format(
        len(groups['DEF']), len(groups['MID']), len(groups['FWD']))
    return groups, formation


