    def _start_stagger_reveal(self, list_content, new_match_ids, selected_id):
        """Reveal a freshly-rebuilt match list a few rows at a time (~35ms apart)
        instead of populating everything in one frame. Only runs when the row
        set actually changed (initial load, filter/day change, favourites
        re-sort) - the frequent in-place refresh path is untouched. This is a
        bounded one-shot timer chain, not a continuous animation loop, so it
        stays cheap on ARM hardware."""
        total = len(list_content)
        self.current_match_ids = new_match_ids
        self._reset_selection_glow()
        if total <= 1:
            self["list"].setList(list_content)
            self._finish_stagger_cursor(new_match_ids, selected_id)
            return

        self._stagger_content = list_content
        self._stagger_ids = new_match_ids
        self._stagger_selected_id = selected_id
        # Cap total reveal time (~700ms) regardless of list length by revealing
        # more rows per tick on long lists.
        self._stagger_step = max(1, (total // 20) + 1)
        self._stagger_index = min(total, self._stagger_step)
        self["list"].setList(list_content[:self._stagger_index])

        if not hasattr(self, '_stagger_timer'):
            self._stagger_timer = eTimer()
            safe_connect(self._stagger_timer, self._stagger_tick)
        else:
            try:
                self._stagger_timer.stop()
            except Exception:
                pass

        if self._stagger_index < total:
            self._stagger_timer.start(35, True)
        else:
            self._finish_stagger_cursor(new_match_ids, selected_id)

    def _stagger_tick(self):
        total = len(self._stagger_content)
        self._stagger_index = min(total, self._stagger_index + self._stagger_step)
        self["list"].setList(self._stagger_content[:self._stagger_index])
        if self._stagger_index < total:
            self._stagger_timer.start(35, True)
        else:
            self._finish_stagger_cursor(self._stagger_ids, self._stagger_selected_id)

    def _finish_stagger_cursor(self, new_match_ids, selected_id):
        if selected_id:
            try:
                new_index = new_match_ids.index(selected_id)
                self["list"].moveToIndex(new_index)
            except ValueError:
                pass

    def _nav_up(self):
        self._reset_idle_hint()
        old_idx = self["list"].getSelectedIndex()
        self["list"].up()
        self._update_selection_glow(old_idx, self["list"].getSelectedIndex())

    def _nav_down(self):
        self._reset_idle_hint()
        old_idx = self["list"].getSelectedIndex()
        self["list"].down()
        self._update_selection_glow(old_idx, self["list"].getSelectedIndex())

    # --- Sliding selection glow ---
    # eListboxPythonMultiContent has no notion of animating between two rows -
    # each row is static content and focus is just an instant colour swap
    # (which we already use for the border). To get an actual sliding glow
    # without risky assumptions about the engine's internal scroll state, we
    # track the overlay's position ourselves using *relative* deltas (a
    # single-step move is always exactly one itemHeight away on screen) and
    # only ever trust that tracking when we're confident no scroll happened -
    # i.e. the old index had at least a full screen of rows as buffer on both
    # sides. Everywhere else (near the top/bottom edge, page jumps, list
    # rebuilds) we simply hide the overlay and fall back to the always-correct
    # native border-colour glow, rather than risk showing it in the wrong spot.
    _GLOW_ITEM_H = 136
    _GLOW_LIST_TOP_Y = 128
    _GLOW_CARD_MARGIN = 3
    _GLOW_VISIBLE_ROWS = 6
    _GLOW_X = 22

    def _reset_selection_glow(self):
        """Call this whenever the list is rebuilt (not just re-selected) -
        any relative tracking from before the rebuild is no longer trustworthy."""
        self._glow_idx = None
        self._glow_y = None
        try:
            self["nav_glow"].hide()
        except Exception:
            pass

    def _update_selection_glow(self, old_idx, new_idx):
        if not getattr(self, 'is_vnext_theme', False):
            return
        try:
            if new_idx is None:
                return

            if new_idx == 0:
                # Always a known-safe baseline: top of the list, no scroll possible.
                target_y = self._GLOW_LIST_TOP_Y + self._GLOW_CARD_MARGIN
                self._glow_idx = 0
                self._glow_y = target_y
                self._show_glow_at(target_y, instant=True)
                return

            total = len(self.current_match_ids) if self.current_match_ids else 0
            buf = self._GLOW_VISIBLE_ROWS - 1
            safe = (
                old_idx is not None and self._glow_y is not None and self._glow_idx == old_idx
                and abs(new_idx - old_idx) == 1
                and old_idx >= buf and old_idx <= (total - 1) - buf
            )
            if safe:
                start_y = self._glow_y
                target_y = start_y + self._GLOW_ITEM_H * (new_idx - old_idx)
                self._glow_idx = new_idx
                self._glow_y = target_y
                self._animate_glow(start_y, target_y)
            else:
                self._reset_selection_glow()
        except Exception:
            pass

    def _show_glow_at(self, y, instant=False):
        try:
            w = self["nav_glow"]
            if not w.instance:
                return
            w.instance.move(ePoint(self._GLOW_X, y))
            w.show()
        except Exception:
            pass

    def _animate_glow(self, start_y, target_y):
        """Quick ease-out slide, ~5 steps over ~90ms total - a bounded one-shot
        chain, not a continuous loop, so it stays cheap on ARM hardware."""
        try:
            steps = 5

            def _step(i):
                t = i / float(steps)
                t = 1 - (1 - t) ** 3  # ease-out cubic
                y = int(start_y + (target_y - start_y) * t)
                self._show_glow_at(y)
                if i < steps:
                    timer = eTimer()
                    safe_connect(timer, lambda: _step(i + 1))
                    if not hasattr(self, '_glow_anim_timers'):
                        self._glow_anim_timers = []
                    self._glow_anim_timers.append(timer)
                    self._glow_anim_timers = self._glow_anim_timers[-4:]
                    timer.start(18, True)

            _step(0)
        except Exception:
            pass

    def _reset_idle_hint(self):
        """Any real user activity postpones the idle nav hint by another window."""
        if not getattr(self, 'is_vnext_theme', False) or not hasattr(self, '_idle_hint_timer'):
            return
        try:
            self._idle_hint_timer.start(6000, True)
        except Exception:
            pass

    def _show_idle_hint(self):
        """One-shot left-to-right 'wave' across the bottom nav pills, reusing the
        same focus-pill/active-icon assets as a real press. Purely a passive
        visual cue (no navigation happens) - capped at a few times per session."""
        if not getattr(self, 'is_vnext_theme', False):
            return
        if getattr(self, '_idle_hint_shown_count', 0) >= 4:
            return
        self._idle_hint_shown_count = self._idle_hint_shown_count + 1
        order = ['red', 'green', 'yellow', 'blue', 'epg']
        icon_map = {'red': 'nav_leagues', 'green': 'nav_minibar', 'yellow': 'nav_arena', 'blue': 'nav_watchparty', 'epg': 'nav_epg'}

        def _step(i):
            if i > 0:
                # revert the previous pill
                prev_key = order[i - 1]
                try:
                    self['navfocus_bg_' + prev_key].hide()
                    normal_path = self.vnext_asset('nav', icon_map[prev_key] + '.png')
                    if os.path.exists(normal_path) and self['navicon_' + prev_key].instance:
                        self['navicon_' + prev_key].instance.setPixmapFromFile(normal_path)
                except Exception:
                    pass
            if i >= len(order):
                return
            key = order[i]
            try:
                pill_path = self.vnext_asset('nav', 'nav_pill_focus_340x64.png')
                active_path = self.vnext_asset('nav', icon_map[key] + '_active.png')
                bgw = self['navfocus_bg_' + key]; iconw = self['navicon_' + key]
                if os.path.exists(pill_path) and bgw.instance:
                    bgw.instance.setPixmapFromFile(pill_path); bgw.show()
                if os.path.exists(active_path) and iconw.instance:
                    iconw.instance.setPixmapFromFile(active_path)
            except Exception:
                pass
            t = eTimer()
            safe_connect(t, lambda: _step(i + 1))
            if not hasattr(self, '_idle_hint_timers'):
                self._idle_hint_timers = []
            self._idle_hint_timers.append(t)
            self._idle_hint_timers = self._idle_hint_timers[-8:]
            t.start(140, True)

        _step(0)
        self._reset_idle_hint()

    def _delay_after_flash(self, callback):
        """Run *callback* ~160ms later instead of immediately. The nav press-flash
        (icon swap + focus pill) was being started and then instantly painted over
        by the new screen opening in the same tick, so it never had a chance to
        actually render. This gives one GUI frame or two of breathing room first."""
        if not getattr(self, 'is_vnext_theme', False):
            callback()
            return
        t = eTimer()
        safe_connect(t, callback)
        if not hasattr(self, '_nav_delay_timers'):
            self._nav_delay_timers = []
        self._nav_delay_timers.append(t)
        self._nav_delay_timers = self._nav_delay_timers[-8:]  # keep a handful alive, drop old ones
        t.start(160, True)

    def _flash_nav(self, key):
        """Briefly show the focus-pill background + active-coloured icon behind a
        bottom-nav item when its remote key is pressed, then revert. No-op if the
        vNext icon set isn't installed or this is the UCL theme."""
        self._reset_idle_hint()
        if not getattr(self, 'is_vnext_theme', False):
            return
        icon_map = {'red': 'nav_leagues', 'green': 'nav_minibar', 'yellow': 'nav_arena', 'blue': 'nav_watchparty', 'epg': 'nav_epg'}
        base = icon_map.get(key)
        if not base:
            return
        try:
            pill_path = self.vnext_asset('nav', 'nav_pill_focus_340x64.png')
            active_path = self.vnext_asset('nav', base + '_active.png')
            normal_path = self.vnext_asset('nav', base + '.png')
            bgw = self['navfocus_bg_' + key]
            iconw = self['navicon_' + key]
            if os.path.exists(pill_path) and bgw.instance:
                bgw.instance.setPixmapFromFile(pill_path)
                bgw.show()
            if os.path.exists(active_path) and iconw.instance:
                iconw.instance.setPixmapFromFile(active_path)

            def _revert():
                try:
                    bgw.hide()
                    if os.path.exists(normal_path) and iconw.instance:
                        iconw.instance.setPixmapFromFile(normal_path)
                except Exception:
                    pass

            t = eTimer()
            safe_connect(t, _revert)
            t.start(380, True)
            # Keep a reference so the timer isn't garbage-collected before it fires
            if not hasattr(self, '_nav_flash_timers'):
                self._nav_flash_timers = []
            self._nav_flash_timers.append(t)
            self._nav_flash_timers = self._nav_flash_timers[-8:]
        except Exception:
            pass

    def _load_vnext_pixmaps(self):
        """Load the static PNG assets for the vNext theme onto their named Pixmap
        widgets. Every file is optional - a missing icon just leaves the flat
        skin colour/accent showing through, so partial asset drops are safe."""
        try:
            va = self.vnext_asset
            loads = [
                ("logo_mark", va("header", "logo_mark.png")),
                ("badge_alert_bg", va("header", "badge_pill_small.png")),
                ("badge_ai_bg", va("header", "badge_pill_small.png")),
                ("badge_updated_bg", va("header", "badge_pill_wide.png")),
                ("nav_glow", va("card", "select_glow_1876x130.png")),
                ("badge_bell_icon", va("header", "badge_bell_off.png")),
                ("badge_ai_icon", va("header", "badge_ai_active.png")),
                ("badge_refresh_icon", va("header", "badge_refresh_0.png")),
            ]
            nav_map = {"navicon_red": "nav_leagues.png", "navicon_green": "nav_minibar.png",
                       "navicon_yellow": "nav_arena.png", "navicon_blue": "nav_watchparty.png",
                       "navicon_epg": "nav_epg.png"}
            for wname, fname in nav_map.items():
                loads.append((wname, va("nav", fname)))

            for wname, path in loads:
                try:
                    if os.path.exists(path) and wname in self and self[wname].instance:
                        self[wname].instance.setPixmapFromFile(path)
                        self[wname].instance.setScale(1)
                except Exception:
                    pass

            # AI badge icon only shown once AI is actually enabled (toggled in update_top_status)
            try:
                if "badge_ai_icon" in self:
                    self["badge_ai_icon"].hide()
            except Exception:
                pass
            try:
                self["nav_glow"].hide()
            except Exception:
                pass

            # Optional stadium-atmosphere background photo + low-opacity line texture,
            # per the "Background Design" section of the renovation brief. Falls back
            # to the flat charcoal eLabel underneath if the files aren't present.
            try:
                is_black_theme = (getattr(self.monitor, "main_bg_color", "default") == "black")
                if not is_black_theme:
                    bg_path = va("backgrounds", "bg_stadium_blur_1920x1080.png")
                    if os.path.exists(bg_path) and "main_bg_photo" in self and self["main_bg_photo"].instance:
                        self["main_bg_photo"].instance.setPixmapFromFile(bg_path)
                        self["main_bg_photo"].show()
                    tex_path = va("backgrounds", "bg_texture_lines_1920x1080.png")
                    if os.path.exists(tex_path) and "main_bg_texture" in self and self["main_bg_texture"].instance:
                        self["main_bg_texture"].instance.setPixmapFromFile(tex_path)
                        self["main_bg_texture"].show()
                else:
                    if "main_bg_photo" in self:
                        self["main_bg_photo"].hide()
                    if "main_bg_texture" in self:
                        self["main_bg_texture"].hide()
            except Exception:
                pass

            self._nav_flash_timers = []
            self._refresh_spin_frame = 0
        except Exception:
            pass

    def update_clock(self):
        """Update clock display (HH:MM:SS) and the last-refreshed age in top_status."""
        try:
            now = datetime.datetime.now()
            self["clock"].setText(now.strftime("%H:%M:%S"))

            if self._last_refreshed is None:
                self.update_age_text = u"\u21bb " + _t("Waiting for data…")
                self.last_update_text = u"  |  " + self.update_age_text
            else:
                delta_sec = int((now - self._last_refreshed).total_seconds())
                if delta_sec < 60:
                    age_str = u"{}s ago".format(delta_sec)
                elif delta_sec < 3600:
                    age_str = u"{}m {}s ago".format(delta_sec // 60, delta_sec % 60)
                else:
                    age_str = u"{}h {}m ago".format(delta_sec // 3600, (delta_sec % 3600) // 60)
                self.update_age_text = u"\u21bb {}".format(age_str)
                self.last_update_text = u"  |  \u21bb (updated {})".format(age_str)

            self["key_menu"].setText(_t("MENU: Settings  |  1-8: Leagues  |  9: Custom  |  0: Lineups"))
            self.update_top_status()
            if now.second % 3 == 0:
                try:
                    self["list"].invalidate()
                except Exception:
                    pass
        except Exception:
            pass

    def start_ui(self):
        log_diag("SCREEN.start_ui: is_custom={} filter_mode={} discovery_mode={} active={}".format(
            self.monitor.is_custom_mode, self.monitor.filter_mode, self.monitor.discovery_mode, self.monitor.active))
        self.update_clock()  # Initial clock update
        # ENSURE: single_shot=False (2nd param) for repeating update
        self.clock_timer.start(1000, False)  # Update every second
        # Clear list immediately to prevent stale cache flash from previous session
        self["list"].setList([])
        self["list_title"].setText("Loading...")
        self.update_top_status()
        self.update_header(); self.update_filter_button(); self._update_ch_hint(); self.fetch_data()
        try:
            self.check_for_updates(silent=True)
        except Exception:
            pass

        # Remote Config fetch
        try:
            t = threading.Thread(target=self.bg_fetch_remote_config)
            t.daemon = True
            t.start()
        except Exception as e:
            log_dbg("[RemoteConfig] Thread start failed: " + str(e))

    def bg_fetch_remote_config(self):
        self.monitor.fetch_remote_config()
        reactor.callFromThread(self.apply_remote_config)

    def apply_remote_config(self):
        if getattr(self, '_is_closed', False) or not self.session:
            return
        config = self.monitor.remote_config
        
        # 1. Maintenance Mode
        if config.get("maintenance_mode", False):
            from Screens.MessageBox import MessageBox
            self.session.openWithCallback(
                self.close, 
                MessageBox, 
                _t("SimplySport is currently under maintenance. Please try again later."), 
                MessageBox.TYPE_ERROR
            )
            return

        # 2. Announcement Message
        if config.get("show_announcement", False) and config.get("announcement_message"):
            last_msg = getattr(self.monitor, '_last_announcement', '')
            curr_msg = config.get("announcement_message")
            if last_msg != curr_msg:
                self.monitor._last_announcement = curr_msg
                from Screens.MessageBox import MessageBox
                self.session.open(MessageBox, curr_msg, MessageBox.TYPE_INFO)

    def cleanup(self):
        if hasattr(self, '_stagger_timer') and self._stagger_timer:
            try:
                self._stagger_timer.stop()
            except Exception:
                pass
        self.clock_timer.stop()
        self.logo_refresh_timer.stop()
        self.ai_ticker_timer.stop()
        self.monitor.unregister_callback(self.refresh_ui)

    def receive_ai_ticker(self, messages):
        """Receive AI-generated messages and start cycling them in the title bar."""
        self._ai_ticker_messages = messages
        self._ai_ticker_idx = 0
        if not self.ai_ticker_timer.isActive():
            self.ai_ticker_timer.start(8000, False)   # 8 s per message

    def _advance_ai_ticker(self):
        """Cycle through AI ticker messages, then restore normal title."""
        if not self._ai_ticker_messages:
            self.ai_ticker_timer.stop()
            return
        msg = self._ai_ticker_messages[
            self._ai_ticker_idx % len(self._ai_ticker_messages)
        ]
        self["list_title"].setText(msg)
        self._ai_ticker_idx += 1
        if self._ai_ticker_idx >= len(self._ai_ticker_messages):
            self.ai_ticker_timer.stop()
            self._ai_ticker_messages = []
            # Restore normal title after ticker finishes
            self.update_header()

    def update_top_status(self):
        """Update the top-bar status info: Goal Alert Mode and AI Mode."""
        try:
            d_mode = self.monitor.discovery_mode
            if d_mode == 0: alert_txt = _t("OFF")
            elif d_mode == 1: alert_txt = _t("VISUAL")
            else: alert_txt = _t("SOUND")
            
            ai_status = _t("ON") if self.monitor.ai_enabled else _t("OFF")
            
            # Combine info: Goal Alert: MODE | AI: STATUS
            status_str = u"{} {} : {}  |  AI: {}".format(u"\u2022", _t("Goal Alert"), alert_txt, ai_status)
            if hasattr(self, 'last_update_text') and self.last_update_text:
                status_str += self.last_update_text
            self["top_status"].setText(status_str)

            # vNext header badges (goal alert / AI / last-updated pills)
            try:
                alert_on = d_mode != 0
                self["badge_alert"].setText(u"{}: {}".format(_t("ALERT"), alert_txt))
                self["badge_alert"].instance.setForegroundColor(gRGB(0x00D9FF if alert_on else 0x6E7885))
                if getattr(self, 'is_vnext_theme', False):
                    bell_file = "badge_bell_on.png" if alert_on else "badge_bell_off.png"
                    bell_path = self.vnext_asset("header", bell_file)
                    if os.path.exists(bell_path) and self["badge_bell_icon"].instance:
                        self["badge_bell_icon"].instance.setPixmapFromFile(bell_path)
            except Exception:
                pass
            try:
                ai_on = bool(self.monitor.ai_enabled)
                self["badge_ai"].setText(u"AI: {}".format(ai_status))
                self["badge_ai"].instance.setForegroundColor(gRGB(0x00AFFF if ai_on else 0x6E7885))
                if getattr(self, 'is_vnext_theme', False):
                    if ai_on:
                        self["badge_ai_icon"].show()
                    else:
                        self["badge_ai_icon"].hide()
            except Exception:
                pass
            try:
                self["badge_updated"].setText(getattr(self, 'update_age_text', ''))
                if getattr(self, 'is_vnext_theme', False):
                    self._advance_refresh_spinner()
            except Exception:
                pass
        except Exception:
            pass

    def _advance_refresh_spinner(self):
        """Cycle the 4-frame 'updated Xs ago' spinner icon each time the clock ticks."""
        try:
            frame = getattr(self, '_refresh_spin_frame', 0)
            path = self.vnext_asset("header", "badge_refresh_{}.png".format(frame % 4))
            if os.path.exists(path) and self["badge_refresh_icon"].instance:
                self["badge_refresh_icon"].instance.setPixmapFromFile(path)
            self._refresh_spin_frame = (frame + 1) % 4
        except Exception:
            pass

    # ... (Keep Header, Filter, Download helpers unchanged) ...
    def update_header(self, count=None, count_live=0, count_fin=0, count_sch=0):
        if self.monitor.is_favorite_mode: self["league_title"].setText(_t("Favorite League View"))
        elif self.monitor.is_custom_mode: self["league_title"].setText(_t("Custom League View"))
        else:
            try: item = DATA_SOURCES[self.monitor.current_league_index]; self["league_title"].setText(_league_name(item[0]))
            except: pass
            
        mode = self.monitor.filter_mode
        title_str = ""
        if mode == 0: title_str = _t("Yesterday's Matches")
        elif mode == 1: title_str = _t("Live Matches")
        elif mode == 2:
            offset = self.monitor.ch_day_offset
            if offset == 0:
                title_str = _t("Today's Matches")
            elif offset == 1:
                title_str = _t("Tomorrow's Matches")
            elif offset == -1:
                title_str = _t("Yesterday's Matches")
            else:
                title_str = _t("Matches")
        elif mode == 3: title_str = _t("Tomorrow's Matches")
        elif mode == 4: title_str = _t("All Matches")
        
        if count is not None and title_str:
            breakdown = "{}".format(count)
            parts = []
            if count_live > 0: parts.append("{} {}".format(count_live, _t("Live")))
            if count_fin > 0: parts.append("{} {}".format(count_fin, _t("Fin")))
            if count_sch > 0: parts.append("{} {}".format(count_sch, _t("Sch")))
            # Reverse order for RTL (Arabic) so it reads naturally right-to-left
            if PLUGIN_LANGUAGE == "ar":
                parts.reverse()
            if parts:
                breakdown += " - " + " / ".join(parts)
            title_str = "{}  ({})".format(title_str, breakdown)
            
        # Inject browsed-date prefix when using CH+/CH-
        offset = self.monitor.ch_day_offset
        if offset != 0:
            target     = datetime.date.today() + datetime.timedelta(days=offset)
            day_name   = _t(target.strftime("%A"))
            month_name = _t(target.strftime("%B"))
            day_num    = target.strftime("%d")
            if PLUGIN_LANGUAGE == "ar":
                date_label = u"{} {} {}".format(day_name, day_num, month_name)
            else:
                date_label = u"{}, {} {}".format(day_name[:3], day_num, month_name[:3])
            # e.g.  "Sat 07 Jun  •  All Matches  (12)"
            if title_str:
                title_str = u"{}  \u2022  {}".format(date_label, title_str)
            else:
                title_str = date_label

        self["list_title"].setText(title_str)
        try:
            if count_live and count_live > 0:
                self["live_indicator"].setText(u"\u25CF {} {}".format(count_live, _t("LIVE NOW")))
                if getattr(self, 'is_vnext_theme', False):
                    self["live_indicator"].instance.setForegroundColor(gRGB(VN_LIVE_GREEN))
            elif getattr(self, '_next_match_label', ''):
                self["live_indicator"].setText(self._next_match_label)
                if getattr(self, 'is_vnext_theme', False):
                    self["live_indicator"].instance.setForegroundColor(gRGB(VN_TEXT_SEC))
            else:
                self["live_indicator"].setText("")
        except Exception:
            pass
        # Green button: show 'Driver Position' for racing, 'Mini Bar' otherwise
        try:
            if not self.monitor.is_custom_mode:
                url = DATA_SOURCES[self.monitor.current_league_index][1]
                if get_sport_type(url) == SPORT_TYPE_RACING:
                    self["key_green"].setText(_t("Driver Position"))
                else:
                    self["key_green"].setText(_t("Mini Bar"))
            else:
                self["key_green"].setText(_t("Mini Bar"))
        except: self["key_green"].setText(_t("Mini Bar"))
        self["key_blue"].setText(_t("Watch Party"))
        self.update_top_status()

    def update_filter_button(self):
        self["key_yellow"].setText(_t("SimplySports Arena"))
        self.update_header()

    def fetch_data(self):
        self.monitor.check_goals(from_ui=True)

    @profile_function("SimpleSportsScreen")
    def get_logo_path(self, url, team_id):
        """Get logo path using team ID naming (aligned with GameInfoScreen approach)"""
        if not url: return None

        # Fallback ID generation if missing (e.g. some tennis players)
        if not team_id:
            import hashlib
            # Create a short hash of the URL to use as ID
            team_id = hashlib.md5(url.encode('utf-8')).hexdigest()[:10]

        target_path = self.logo_path + str(team_id) + ".png"

        # -----------------------------------------------------------------
        # CHOICE 1 (PRIMARY): Use bundled epl_logo.png for Egyptian Premier League
        # -----------------------------------------------------------------
        if is_epl_logo_request(url, team_id):
            bundled_epl = get_bundled_epl_logo_path()
            if bundled_epl:
                try:
                    if not os.path.exists(self.logo_path): os.makedirs(self.logo_path)
                    if not os.path.exists(target_path) or os.path.getsize(target_path) < 100:
                        import shutil
                        shutil.copyfile(bundled_epl, target_path)
                    GLOBAL_VALID_LOGO_PATHS.add(target_path)
                    self.monitor.logo_path_cache[team_id] = target_path
                    self.monitor.missing_logo_cache.discard(team_id)
                    return target_path
                except Exception:
                    pass

        # -----------------------------------------------------------------
        # CHOICE 2 (FALLBACK): Fast Set / Memory Cache / Disk Cache Bypass
        # -----------------------------------------------------------------
        if target_path in GLOBAL_VALID_LOGO_PATHS:
            self.monitor.logo_path_cache[team_id] = target_path
            self.monitor.missing_logo_cache.discard(team_id)
            return target_path

        # Check disk first - if downloaded by prefetch or detail screen, clear missing_logo_cache!
        if os.path.exists(target_path) and os.path.getsize(target_path) > 100:
            GLOBAL_VALID_LOGO_PATHS.add(target_path)
            self.monitor.logo_path_cache[team_id] = target_path
            self.monitor.missing_logo_cache.discard(team_id)
            return target_path

        # Negative Cache bypass for missing files
        if team_id in self.monitor.missing_logo_cache: return None

        # Queue download if not cached
        self.monitor.missing_logo_cache.add(team_id)
        self.queue_download(url, target_path, team_id)
        return None

    def queue_download(self, url, target_path, filename):
        if filename in self.active_downloads or filename in self.monitor.pending_logos: return
        # Check if recently failed
        if hasattr(self, 'failed_downloads') and filename in self.failed_downloads: return

        # Limit concurrent downloads to prevent network congestion
        MAX_CONCURRENT = 5
        if len(self.active_downloads) >= MAX_CONCURRENT:
            # Add to pending queue - will be processed when current downloads finish
            if not hasattr(self, 'pending_downloads'): self.pending_downloads = []

            # CRITICAL FIX: Prevent duplicate pending entries
            for i in range(len(self.pending_downloads)):
                if self.pending_downloads[i][2] == filename:
                    return # Already pending

            self.pending_downloads.append((url, target_path, filename))
            return
        self.active_downloads.add(filename)
        from twisted.web.client import downloadPage
        headers = {b'User-Agent': b'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        downloadPage(url.encode('utf-8'), target_path, headers=headers, timeout=10).addCallback(self.download_finished, filename, target_path).addErrback(self.download_failed, filename)

    def download_finished(self, data, filename, target_path):
        self.active_downloads.discard(filename)
        self.monitor.missing_logo_cache.discard(filename)
        if os.path.exists(target_path) and os.path.getsize(target_path) > 100:
            try:
                with open(target_path, 'rb') as _f:
                    _magic = _f.read(4)
                if _magic != b'\x89PNG':
                    os.remove(target_path)
                    self._process_pending_downloads()
                    return
            except: pass
            GLOBAL_VALID_LOGO_PATHS.add(target_path)
            self.monitor.logo_path_cache[filename] = target_path
            # Batch UI updates - wait for more downloads before refreshing
            if not self.logo_refresh_timer.isActive(): self.logo_refresh_timer.start(1500, True)
        # Process pending downloads
        self._process_pending_downloads()

    def download_failed(self, error, filename):
        self.active_downloads.discard(filename)
        # Track failures to prevent infinite retry loops
        # Use a short-lived cache or persistent set? Persistent for session is safest.
        if not hasattr(self, 'failed_downloads'): self.failed_downloads = set()
        self.failed_downloads.add(filename)

        # -----------------------------------------------------------------
        # CHOICE 4 (FALLBACK): Unverified SSL fallback thread for Egyptian Premier League
        # -----------------------------------------------------------------
        if is_epl_logo_request(None, filename):
            target_path = self.logo_path + str(filename) + ".png"
            def _thread_fallback():
                try:
                    import urllib.request as _urllib, ssl as _ssl
                    _ctx = _ssl.create_default_context()
                    _ctx.check_hostname = False
                    _ctx.verify_mode = _ssl.CERT_NONE
                    _epl_url = "https://egyptianproleague.com/assets/images/logo.png"
                    _req = _urllib.Request(_epl_url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'})
                    with _urllib.urlopen(_req, context=_ctx, timeout=8) as _resp:
                        _data = _resp.read()
                        if _data and len(_data) > 100:
                            reactor.callFromThread(self.download_finished, _data, filename, target_path)
                            return
                except Exception:
                    pass
            _t = threading.Thread(target=_thread_fallback)
            _t.daemon = True
            _t.start()

        self._process_pending_downloads()

    def _process_pending_downloads(self):
        """Process queued downloads when there's capacity"""
        if not hasattr(self, 'pending_downloads') or not self.pending_downloads: return
        MAX_CONCURRENT = 5
        while self.pending_downloads and len(self.active_downloads) < MAX_CONCURRENT:
            url, target_path, filename = self.pending_downloads.pop(0)
            if filename not in self.active_downloads and filename not in self.monitor.logo_path_cache:
                self.active_downloads.add(filename)
                from twisted.web.client import downloadPage
                headers = {b'User-Agent': b'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
                downloadPage(url.encode('utf-8'), target_path, headers=headers, timeout=10).addCallback(self.download_finished, filename, target_path).addErrback(self.download_failed, filename)

    def check_epg_availability(self, home, away):
        epg = eEPGCache.getInstance()
        if not epg: return False

        h_terms = get_search_keywords(home)
        a_terms = get_search_keywords(away)

        # Check primary keywords for discovery
        queries = []
        if h_terms: queries.append(normalize_text(h_terms[0]))
        if a_terms: queries.append(normalize_text(a_terms[0]))

        for kw in queries:
            if not kw: continue
            try:
                # Fast global search
                results = epg.search((kw, 2, 0, 10))
                if results:
                    for entry in results:
                        title = normalize_text(entry[2] or "")
                        # Verification: Name must be in title
                        if kw in title: return True
            except: pass
        return False

    def open_broadcasting(self, forced_event=None):
        if forced_event is None:
            self._flash_nav('epg')
            self._delay_after_flash(lambda: self._open_broadcasting_impl(None))
            return
        self._open_broadcasting_impl(forced_event)

    def _open_broadcasting_impl(self, forced_event=None):
        log_dbg("open_broadcasting called. Forced Event: {}".format(forced_event is not None))
        target_event = forced_event
        selected_id = None

        if not target_event:
            idx = self["list"].getSelectedIndex()
            log_dbg("open_broadcasting: List Index = {}".format(idx))
            if idx is None or idx < 0 or idx >= len(self.current_match_ids):
                log_dbg("open_broadcasting: Invalid Index or ID list empty")
                return
            selected_id = self.current_match_ids[idx]
            log_dbg("open_broadcasting: Selected ID = {}".format(selected_id))

        # Re-find event or process target
        events_to_scan = [target_event] if target_event else self.monitor.cached_events
        log_dbg("open_broadcasting: Scanning {} events...".format(len(events_to_scan)))
        for event in events_to_scan:
            try:
                # 1. Define comps/status
                comps = event.get('competitions', [{}])[0].get('competitors', [])
                status = event.get('status', {}); state = status.get('type', {}).get('state', 'pre')
                ev_date_str = event.get('date', '')
                league_name = event.get('league_name', '')

                # 2. Calculate Timestamp
                match_time_ts = 0

                try:
                    if ev_date_str:
                        # Harden Parsing: Standardize separator and remove Z/fractions
                        clean_date = ev_date_str.replace("Z", "").replace("T", " ")
                        if "." in clean_date:
                            clean_date = clean_date.split(".")[0]

                        dt = None
                        # Try formats: with seconds, without seconds
                        for fmt in ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"]:
                            try:
                                dt = datetime.datetime.strptime(clean_date, fmt)
                                break
                            except ValueError: continue

                        if dt:
                            match_time_ts = calendar.timegm(dt.timetuple())
                except: pass

                # FALLBACK: If date parse failed or missing, use CURRENT TIME
                # This assumes the user wants EPG for what's happening NOW.
                if match_time_ts == 0:
                    match_time_ts = int(time.time())

                # Define safe defaults for EPG search variables before the loop to avoid UnboundLocalError
                epg_home = ""; epg_away = ""; epg_league = league_name

                if len(comps) > 2:
                    left = event.get('shortName', 'Race'); right = "Event"
                    mid = left + right
                    # For Racing/Golf, use Event Name as "Home" and nothing as "Away"
                    epg_home = event.get('shortName') or event.get('name') or "Event"
                    epg_away = ""
                else:
                    team_h = next((t for t in comps if t.get('homeAway') == 'home'), comps[0] if comps else None)
                    team_a = next((t for t in comps if t.get('homeAway') == 'away'), comps[1] if len(comps)>1 else None)

                    home = "Home"; away = "Away"
                    if team_h:
                        if 'athlete' in team_h: home = team_h.get('athlete', {}).get('shortName', 'P1')
                        else: home = team_h.get('team', {}).get('displayName', 'Home')
                    if team_a:
                        if 'athlete' in team_a: away = team_a.get('athlete', {}).get('shortName', 'P2')
                        else: away = team_a.get('team', {}).get('displayName', 'Away')
                    mid = home + "_" + away

                    # Set EPG search terms
                    epg_home = home; epg_away = away

                # Check ID match only if not forced
                # FIX: Check both numeric ID (from API) and name-based MID (legacy/backup)
                ev_id = str(event.get('id', ''))
                if target_event or ev_id == str(selected_id) or mid == selected_id:
                    if not target_event: target_event = event
                    # Extract names and Time for Smart Search
                    log_dbg("open_broadcasting: Match Found. Search Terms: Home='{}', Away='{}'".format(epg_home, epg_away))
                    self.search_and_display_epg(epg_home, epg_away, epg_league, match_time_ts, target_event)
                    return
            except: continue

    def search_and_display_epg(self, home, away, league, match_time_ts, target_event=None):
        from Screens.MessageBox import MessageBox
        import os
        from enigma import eServiceReference, eEPGCache

        epg = eEPGCache.getInstance()
        if not epg:
            log_dbg("search_and_display_epg: CRITICAL - eEPGCache instance missing")
            self.session.open(MessageBox, "Critical Error: eEPGCache instance is missing.", MessageBox.TYPE_ERROR)
            return

        # --- DIAGNOSTIC: Check EPG File (Expanded Paths) ---
        epg_paths = [
            "/etc/enigma2/epg.dat", "/media/hdd/epg.dat", "/media/usb/epg.dat", "/data/epg.dat", "/hdd/epg.dat",
            "/mnt/egamiboot/epg.dat", "/usr/share/enigma2/epg.dat", "/share/enigma2/epg.dat", "/tmp/epg.dat"
        ]
        found_epg_path = "None"
        for p in epg_paths:
            if os.path.exists(p):
                found_epg_path = "%s (%.2f MB)" % (p, os.path.getsize(p)/1024.0/1024.0)
                break
        # --- DIAGNOSTIC END ---

        # 1. Prepare Target Words
        h_norm = [normalize_text(kw) for kw in get_search_keywords(home)]
        a_norm = [normalize_text(kw) for kw in get_search_keywords(away)]
        l_norm = [normalize_text(kw) for kw in get_search_keywords(league)]

        # 2. Get Channels
        if not self.service_cache:
            self.service_cache = get_all_services()

        log_dbg("search_and_display_epg: Service Cache Size = {}".format(len(self.service_cache) if self.service_cache else 0))

        if not self.service_cache:
            self.session.open(MessageBox, "No channels found in bouquets.", MessageBox.TYPE_INFO)
            return

        c_count = len(self.service_cache)

        # --- DIAGNOSTIC: Safe Probe (Multi-Channel + Time) ---
        probe_result = "Skipped (No valid ch)"
        sys_time_str = "Unknown"
        if c_count > 0:
            try:
                import time
                import datetime
                cur_time = int(time.time())
                sys_time_str = datetime.datetime.fromtimestamp(cur_time).strftime('%Y-%m-%d %H:%M')



                # Probe first few channels
                checked_count = 0
                for s in self.service_cache:
                    if checked_count >= 5: break
                    s_ref_str = s[0]
                    if s_ref_str.startswith("1:0:1:") or s_ref_str.startswith("1:0:19:"):
                        checked_count += 1
                        p_evt = epg.lookupEventTime(eServiceReference(s_ref_str), cur_time)
                        if p_evt:
                            probe_result = "Success (%s) on %s" % (p_evt.getEventName() or "Unknown", s[1])
                            break
                        else:
                            probe_result = "No Data on %s" % s[1]
            except Exception as e: probe_result = "Error: %s" % str(e)
        # -------------------------------------
        unique_services = {}
        for s in self.service_cache:
            unique_services[str(s[0])] = s

        from twisted.internet import threads
        import time

        def _bg_search(services, m_time, h_words, a_words, l_words):
            bg_results = []
            search_offsets = [900, 0, 3600, -900]
            now = int(time.time())
            use_fallback_now = True

            if m_time > (now + 21600):
                use_fallback_now = False

            for sref_str, s_info in services.items():
                sref_raw = s_info[0]
                ch_name = s_info[1]
                try:
                    evt = None
                    sref_obj = eServiceReference(sref_raw)

                    for offset in search_offsets:
                        probe_time = m_time + offset
                        candidate = epg.lookupEventTime(sref_obj, probe_time)
                        if candidate:
                            evt = candidate
                            break

                    if not evt and use_fallback_now:
                         if abs(m_time - now) < 7200:
                             evt = epg.lookupEventTime(sref_obj, now)

                    if not evt and (sref_raw.startswith("4097:") or sref_raw.startswith("5001:")):
                        parts = sref_raw.split(':')
                        if len(parts) > 10:
                            dvb_ref_str = "1:0:1:%s:%s:%s:%s:0:0:0" % (parts[3], parts[4], parts[5], parts[6])
                            dvb_obj = eServiceReference(dvb_ref_str)
                            for offset in search_offsets:
                                probe_time = m_time + offset
                                evt = epg.lookupEventTime(dvb_obj, probe_time)
                                if evt: break
                            if not evt and use_fallback_now and abs(m_time - now) < 7200:
                                evt = epg.lookupEventTime(dvb_obj, now)

                    if evt:
                        title = evt.getEventName() or ""
                        desc = evt.getShortDescription() or ""
                        ext = evt.getExtendedDescription() or ""

                        blob = normalize_text(title + " " + desc + " " + ext + " " + ch_name)

                        STOP_WORDS = ['al', 'el', 'the', 'fc', 'sc', 'fk', 'sk', 'club', 'sport', 'sports', 'vs', 'live', 'hd', 'fhd', '4k', 'uhd']

                        def match_sig_score(keywords, text_blob, require_all=True):
                            sig = [w for w in keywords if w not in STOP_WORDS and len(w) > 1]
                            if not sig: sig = keywords

                            found_count = 0
                            for w in sig:
                                if w in text_blob: 
                                    found_count += 1

                            return found_count, len(sig)

                        h_found, h_total = match_sig_score(h_words, blob)
                        a_found, a_total = match_sig_score(a_words, blob) if a_words else (0, 0)
                        l_found, l_total = match_sig_score(l_words, blob)

                        h_ratio = h_found / float(h_total) if h_total > 0 else 0.0
                        a_ratio = a_found / float(a_total) if a_total > 0 else 0.0
                        l_ratio = l_found / float(l_total) if l_total > 0 else 0.0

                        score = 0.0
                        score += (h_ratio * 40)
                        score += (a_ratio * 40)
                        score += (l_ratio * 20)

                        if h_ratio == 1.0: score += 10
                        if a_ratio == 1.0: score += 10
                        if h_ratio == 1.0 and (a_ratio == 1.0 or not a_words): score += 30
                        score += (h_found + a_found + l_found)

                        try:
                            evt_start = evt.getBeginTime()
                            diff_min = abs(evt_start - m_time) / 60.0

                            if diff_min <= 15: score += 20
                            elif diff_min <= 45: score += 10
                            elif diff_min <= 90: score += 5
                            elif diff_min > 120: score -= 15
                        except: diff_min = 999

                        valid_match = False
                        if h_ratio == 1.0 and (a_ratio == 1.0 or not a_words): valid_match = True
                        elif h_ratio >= 0.5 and a_ratio >= 0.5: valid_match = True
                        elif (h_ratio == 1.0 or a_ratio == 1.0) and l_ratio >= 0.5: valid_match = True

                        if valid_match and score > 40:
                            cat_color = 0xffffff
                            if score >= 100: cat_color = 0x00FF00
                            elif score >= 80: cat_color = 0xFFFF00

                            sat_pos = get_sat_position(sref_raw)
                            full_name = ch_name + ((" (" + sat_pos + ")") if sat_pos else "")
                            time_info = "T+0" if diff_min < 1 else "T-%d" % int(diff_min) if evt_start < m_time else "T+%d" % int(diff_min)
                            display_title = "[%d|%s] %s" % (int(score), time_info, title)
                            bg_results.append((sref_raw, full_name, display_title, cat_color, score))
                except:
                    pass

            bg_results.sort(key=lambda x: x[4], reverse=True)
            return [(r[0], r[1], r[2], r[3]) for r in bg_results[:200]]

        def _on_search_done(final_list):
            # Always open BroadcastingChannelsScreen - user can still use Red/Green buttons
            self.session.open(BroadcastingChannelsScreen, final_list or [], match_time_ts=match_time_ts, target_event=target_event)

        # Execute heavy loop in background thread to prevent UI lockup
        threads.deferToThread(_bg_search, unique_services, match_time_ts, h_norm, a_norm, l_norm).addCallback(_on_search_done)

    @profile_function("SimpleSportsScreen")
    def refresh_logos_only(self):
        """Timer callback to batch UI logo refreshes and prevent flicker"""
        if getattr(self, "list", None) and hasattr(self["list"], "l"):
            self["list"].l.invalidate()

    def _update_wc_background(self):
        """Swap the WC background image to match the current day offset.

        Images:       wc1.jpg … wc8.jpg  (offset%8 + 1 mapping)
        Fallback:     wc.jpg in the plugin root directory
        """
        if self.monitor.theme_mode != "ucl":
            return
        try:
            plugin_dir = os.path.dirname(__file__)
            bg_dir     = os.path.join(plugin_dir, "backgrounds")
            offset     = self.monitor.ch_day_offset
            mode       = offset % 8
            img_name   = "wc{}.jpg".format(mode + 1)       # wc1-wc8
            img_path   = os.path.join(bg_dir, img_name)

            # Fallback chain: backgrounds/wcN.jpg → wc.jpg → resolveFilename wc.jpg
            if not os.path.exists(img_path):
                img_path = os.path.join(plugin_dir, "wc.jpg")
            if not os.path.exists(img_path):
                img_path = resolveFilename(SCOPE_PLUGINS, "Extensions/SimplySports/wc.jpg")
            if not os.path.exists(img_path):
                return

            if "main_bg" in self and self["main_bg"].instance:
                if hasattr(self["main_bg"].instance, "setPixmapFromFile"):
                    self["main_bg"].instance.setPixmapFromFile(img_path)
                elif LoadPixmap:
                    self._wc_bg_ptr = LoadPixmap(cached=True, path=img_path)
                    if self._wc_bg_ptr:
                        self["main_bg"].instance.setPixmap(self._wc_bg_ptr)
                self["main_bg"].instance.setScale(1)
                self["main_bg"].show()
        except Exception as e:
            print("[SimplySports] _update_wc_background error:", e)

    @profile_function("SimpleSportsScreen")
    def refresh_ui(self, success, force_refresh=False):
        log_diag("REFRESH_UI: success={} force={} filter_mode={} is_custom={} cached_events={} status='{}'".format(
            success, force_refresh, self.monitor.filter_mode, self.monitor.is_custom_mode, len(self.monitor.cached_events), self.monitor.status_message))
        # Guard: Don't refresh UI during loading states UNLESS forced or displaying a Loading status
        if not success and not force_refresh:
            if not is_loading_status(self.monitor.status_message):
                log_diag("REFRESH_UI: SKIPPED (not success, not forced)")
                return

        # Swap WC background image to match current filter mode
        self._update_wc_background()

        events = self.monitor.cached_events

        # --- CURSOR PRESERVATION LOGIC START ---
        selected_id = None
        current_idx = self["list"].getSelectedIndex()
        if 0 <= current_idx < len(self.current_match_ids):
            selected_id = self.current_match_ids[current_idx]

        new_match_ids = []
        # ----------------------------------------

        if not events:
            # If we already have matches and loading is in progress, keep old list to avoid flicker
            if self.current_match_ids and is_loading_status(self.monitor.status_message):
                log_diag("REFRESH_UI: SKIPPED (loading in progress, keeping old data)")
                return
            log_diag("REFRESH_UI: No events - showing '{}'".format(self.monitor.status_message or 'No Matches Found'))
            msg = self.monitor.status_message or "No Matches Found"
            dummy_entry = ("INFO", "", msg, "", "", "", False, "", None, None, 0, 0, False, 0x202020, "")
            if self.monitor.theme_mode == "ucl": self["list"].setList([UCLListEntry(dummy_entry)])
            else: self["list"].setList([VNextListEntry(dummy_entry)])
            self.current_match_ids = []
            return

        mode = 2 if self.monitor.ch_day_offset != 0 else self.monitor.filter_mode
        raw_entries = []  # Store (entry_data, match_id, is_live) for sorting
        predictor_fetches_started = 0  # cap new ESPN prediction fetches per refresh cycle

        # Pre-compute dates once per render pass
        now = datetime.datetime.now()
        if self.monitor.ch_day_offset != 0:
            now = now + datetime.timedelta(days=self.monitor.ch_day_offset)
        today_str = now.strftime("%Y-%m-%d")
        tomorrow_str = (now + datetime.timedelta(days=1)).strftime("%Y-%m-%d")
        yesterday_str = (now - datetime.timedelta(days=1)).strftime("%Y-%m-%d")

        for event in events:
            try:
                snap = self.monitor.match_snapshots.get(str(event.get('id', '')))
                if not snap: continue
                if not snapshot_passes_filter(snap, mode, today_str, tomorrow_str, yesterday_str): continue

                # Racing: Only show in single-league mode, skip in custom/multi-league
                if snap['sport_type'] == SPORT_TYPE_RACING and self.monitor.is_custom_mode: continue

                # Logo paths from shared cache
                h_png = self.get_logo_path(snap['h_logo_url'], snap['h_logo_id'])
                a_png = self.get_logo_path(snap['a_logo_url'], snap['a_logo_id'])
                l_png = self.get_logo_path(snap['l_logo_url'], snap['l_logo_id'])

                comps = event.get('competitions', [{}])[0].get('competitors', [])
                is_racing_event = (snap['sport_type'] == SPORT_TYPE_RACING) or (len(comps) > 2)

                if is_racing_event:
                    # Racing: Enhanced row with race name, track, status
                    race_name = event.get('shortName', '') or event.get('name', 'Race')
                    track_info = ''
                    try:
                        circuit = event.get('circuit', {})
                        if circuit:
                            track_name = circuit.get('fullName', '')
                            addr = circuit.get('address', {})
                            city = addr.get('city', '')
                            country = addr.get('country', '')
                            loc_parts = [p for p in [city, country] if p]
                            if track_name and loc_parts:
                                track_info = "{} - {}".format(track_name, ", ".join(loc_parts))
                            elif track_name:
                                track_info = track_name
                            elif loc_parts:
                                track_info = ", ".join(loc_parts)
                        if not track_info:
                            comp_venue = event.get('competitions', [{}])[0].get('venue', {})
                            track_info = comp_venue.get('fullName', '') or comp_venue.get('address', {}).get('city', '')
                    except:
                        pass
                    left_text = race_name
                    right_text = track_info if track_info else 'Event'
                    score_text = ""; goal_side = None; is_live = False
                    display_time = snap['time_str']
                    h_score_int = 0; a_score_int = 0

                    # Determine overall event status from most recent active session
                    all_comps = event.get('competitions', [])
                    has_live_session = False
                    has_finished_session = False
                    for comp in all_comps:
                        comp_state = comp.get('status', {}).get('type', {}).get('state', 'pre')
                        if comp_state == 'in': has_live_session = True
                        elif comp_state == 'post': has_finished_session = True

                    if has_live_session:
                        score_text = "LIVE"; is_live = True; display_time = "LIVE"
                    elif has_finished_session:
                        # Check if all sessions are done or just some
                        all_done = all(c.get('status', {}).get('type', {}).get('state', 'pre') == 'post' for c in all_comps)
                        if all_done:
                            score_text = "FIN"
                        else:
                            score_text = "ONGOING"

                    match_id = snap['event_id']
                else:
                    # Team/Tennis/Combat: Read all data from snapshot
                    def truncate_name(name, max_len=25):
                        if len(name) > max_len: return name[:max_len - 2] + ".."
                        return name

                    _fav_set = set(f["team_id"] for f in self.monitor.favorite_teams)
                    _h_star  = u"\u2605 " if snap.get('h_team_id') in _fav_set and _fav_set else ""
                    _a_star  = u"\u2605 " if snap.get('a_team_id') in _fav_set and _fav_set else ""
                    left_text  = _h_star + truncate_name(snap.get('h_name_disp') or _team_name(snap['h_name']), 25 - len(_h_star))
                    right_text = _a_star + truncate_name(snap.get('a_name_disp') or _team_name(snap['a_name']), 25 - len(_a_star))
                    score_text = snap['score_str']
                    h_score_int = snap['h_score_int']
                    a_score_int = snap['a_score_int']
                    is_live = snap['is_live']
                    display_time = snap['time_str']
                    match_id = snap['event_id']
                    goal_side = self.monitor.goal_flags.get(match_id, {}).get('team')

                status_short = snap['status_short']

                has_epg = False
                # Check for recent goals to create a 'heat' effect on the score box
                _score_preset = get_main_bg_preset(getattr(self.monitor, "main_bg_color", "default"))
                c_score_bg = _score_preset["navy_int"] if self.monitor.theme_mode != "ucl" else 0x060e1c
                goal_glow_side = None  # brief (90s) gold edge tint on the scoring side's card border
                # "Recently updated" pulse alpha (2s fade, separate from the 5-min heatmap)
                pulse_alpha = 0.0
                pulse_ts = self.monitor.score_update_timestamps.get(match_id, 0)
                if pulse_ts > 0:
                    pulse_age = time.time() - pulse_ts
                    if pulse_age <= 2.0:
                        pulse_alpha = 1.0 - (pulse_age / 2.0)  # linear fade 1.0 -> 0.0

                if snap['state'] == 'in' and match_id in self.monitor.goal_flags:
                    goal_time = self.monitor.goal_flags[match_id].get('time', 0)
                    time_since_goal = time.time() - goal_time

                    if time_since_goal <= 90:
                        goal_glow_side = self.monitor.goal_flags[match_id].get('team')

                    if time_since_goal <= 300: # 5 minutes
                        total_goals = h_score_int + a_score_int

                        # Base color and target hot color sets based on total goals
                        if total_goals >= 5:  # Extremely hot (lots of goals)
                            start_color = [255, 60, 0]  # #FF3C00 (Vibrant Red-Orange)
                        elif total_goals >= 3: # Hot
                            start_color = [255, 120, 0]  # #FF7800 (Pure Orange)
                        else:  # Warm (1-2 goals)
                            start_color = [200, 40, 60]  # #C8283C (Deep Pink-Red)

                        # Fade progress (0.0 = just scored, 1.0 = 5 minutes ago)
                        progress = time_since_goal / 300.0

                        # Target base color (cool) - matches the theme's score-box background
                        if self.monitor.theme_mode != "ucl":
                            _sn = _score_preset["navy_int"]
                            end_color = [(_sn >> 16) & 0xFF, (_sn >> 8) & 0xFF, _sn & 0xFF]
                        else:
                            end_color = [5, 16, 48]

                        # Interpolate
                        r = int(start_color[0] + (end_color[0] - start_color[0]) * progress)
                        g = int(start_color[1] + (end_color[1] - start_color[1]) * progress)
                        b = int(start_color[2] + (end_color[2] - start_color[2]) * progress)

                        # Convert back to hex
                        c_score_bg = (r << 16) | (g << 8) | b

                # --- ESPN game-prediction lookup (scheduled matches only) ---
                h_pred_pct = 0.0; a_pred_pct = 0.0; pred_is_estimate = 0
                if status_short not in ("LIVE", "FIN", "PPD", "SUS", "CAN"):
                    # 1. Extract directly from event object (instant & complete)
                    h_pred_pct, a_pred_pct = extract_win_prediction_from_event(event)

                    # 2. Fallback to cached async predictor if event odds unpopulated
                    if h_pred_pct <= 0 and a_pred_pct <= 0:
                        cached = self.monitor.predictor_cache.get(match_id)
                        if cached:
                            h_pred_pct = cached.get('h_pct', 0.0)
                            a_pred_pct = cached.get('a_pct', 0.0)
                            pred_is_estimate = 1 if cached.get('source') == 'spread_estimate' else 0
                        elif (match_id not in self.monitor.predictor_inflight
                              and predictor_fetches_started < 3):
                            predictor_fetches_started += 1
                            self.monitor.fetch_predictor_async(match_id, snap.get('league_url', ''), snap.get('event_id', match_id))

                # Only extract key moments / match news for Today's matches (ch_day_offset == 0)
                if getattr(self.monitor, 'ch_day_offset', 0) == 0:
                    km_text = extract_key_moments_summary(event)
                else:
                    km_text = []
                entry_data = (status_short, get_league_abbr(snap['league_name']), str(left_text), str(score_text), str(right_text), str(display_time), goal_side, is_live, h_png, a_png, h_score_int, a_score_int, has_epg, c_score_bg, l_png, snap.get('h_red_cards', 0), snap.get('a_red_cards', 0), snap.get('h_poss', 0.0), snap.get('a_poss', 0.0), snap.get('h_pct_stats', []), snap.get('a_pct_stats', []), snap.get('h_shots', 0), snap.get('a_shots', 0), snap.get('h_on_target', 0), snap.get('a_on_target', 0), snap.get('h_form', ''), snap.get('a_form', ''), h_pred_pct, a_pred_pct, pred_is_estimate, goal_glow_side, pulse_alpha, km_text)

                # Store raw data for sorting (include event for excitement calculation)
                raw_entries.append((entry_data, match_id, is_live, event))
            except Exception as e:
                with open("/tmp/simplysport_render_error.log", "a") as err_log:
                    err_log.write("Error in refresh_ui loop at %s: %s\n" % (datetime.datetime.now(), str(e)))
                continue

        # Sort: LIVE matches by excitement (highest first), then FIN, then SCH
        # AND Priority for SOCCER within each group
        def sort_key(item):
            entry_data, match_id, is_live, event = item
            status = entry_data[0]  # status_short is index 0

            # Football Priority: 0=Soccer, 1=Others
            l_url = event.get('league_url', '')
            sport_prio = 0 if 'soccer' in l_url else 1
            sport_prio = 0 if 'soccer' in l_url else 1

            if status == "LIVE":
                excitement = self.monitor.calculate_excitement(event)
                return (0, sport_prio, -excitement)
            elif status == "FIN":
                return (1, sport_prio, 0)
            else:
                return (2, sport_prio, 0)  # SCH

        raw_entries.sort(key=sort_key)

        # ── Favorite Teams: float matches to top ─────────────────────────────
        fav_ids = set(f["team_id"] for f in self.monitor.favorite_teams)
        if fav_ids:
            def _snap_has_fav(snap):
                return (snap.get("h_team_id") in fav_ids or
                        snap.get("a_team_id") in fav_ids)

            fav_entries   = []
            other_entries = []
            for item in raw_entries:
                _ed, _mid, _il, _ev = item
                _snap = self.monitor.match_snapshots.get(str(_ev.get("id", "")), {})
                if _snap_has_fav(_snap):
                    fav_entries.append(item)
                else:
                    other_entries.append(item)

            # Within favourites: LIVE first, then scheduled, then finished
            def _fav_sort_key(item):
                _, _, _, _ev2 = item
                _sn = self.monitor.match_snapshots.get(str(_ev2.get("id", "")), {})
                state = _sn.get("state", "pre")
                if state == "in":  return 0
                if state == "pre": return 1
                return 2

            fav_entries.sort(key=_fav_sort_key)
            raw_entries = fav_entries + other_entries
        # ── End favourite pinning ─────────────────────────────────────────────

        # Convert to list entries after sorting
        list_content = []
        new_match_ids = []
        for i, (entry_data, match_id, is_live, event) in enumerate(raw_entries):
            # Use RacingListEntry for racing events
            ev_url = event.get('league_url', '')
            if get_sport_type(ev_url) == SPORT_TYPE_RACING:
                # Header row (event name + circuit + overall status)
                list_content.append(RacingListEntry(entry_data + (i,), self.monitor.theme_mode))
                new_match_ids.append(match_id)

                # Iterate ALL sessions (FP1, FP2, FP3, Qual, Race, Sprint etc.)
                all_competitions = event.get('competitions', [])
                for comp_idx, comp in enumerate(all_competitions):
                    sess_type = comp.get('type', {}).get('abbreviation', 'Session {}'.format(comp_idx + 1))
                    sess_state = comp.get('status', {}).get('type', {}).get('state', 'pre')
                    sess_broadcast = comp.get('broadcast', '')
                    sess_start = comp.get('startDate', '')

                    # Status label for session
                    if sess_state == 'in': sess_status = 'LIVE'
                    elif sess_state == 'post': sess_status = 'FIN'
                    else: sess_status = 'SCH'

                    # Time display
                    sess_time = get_local_time_str(sess_start) if sess_start else ''

                    # Session sub-header row
                    sess_row = RacingSessionRow(sess_type, sess_status, sess_broadcast, sess_time, self.monitor.theme_mode)
                    if sess_row:
                        list_content.append(sess_row)
                        new_match_ids.append(match_id + '_ses_' + str(comp_idx))

                    # For LIVE/FINISHED sessions: expand driver result rows
                    if sess_state in ('in', 'post'):
                        comps_list = comp.get('competitors', [])
                        for drv in comps_list:
                            athlete = drv.get('athlete', {})
                            d_name = athlete.get('displayName', '') or athlete.get('shortName', 'Driver')
                            d_country = athlete.get('flag', {}).get('alt', '')
                            d_winner = drv.get('winner', False)
                            d_rank = drv.get('order', 0)
                            # Get team logo path (cached via get_logo_path mechanism)
                            d_team_logo = None
                            team_obj = drv.get('team', {})
                            team_id = team_obj.get('id', '')
                            team_logo_url = extract_team_logo(team_obj, 'racing', team_id)
                            if team_logo_url and team_id:
                                sport_prefix = get_sport_id_prefix(ev_url)
                                d_team_logo = self.get_logo_path(team_logo_url, sport_prefix + str(team_id))
                            row = RacingDriverRow(d_rank, d_name, d_country, d_winner, d_team_logo, self.monitor.theme_mode)
                            if row:
                                list_content.append(row)
                                new_match_ids.append(match_id + '_ses_' + str(comp_idx) + '_drv_' + str(d_rank))
            elif self.monitor.theme_mode == "ucl":
                list_content.append(UCLListEntry(entry_data))
                new_match_ids.append(match_id)
            else:
                list_content.append(VNextListEntry(entry_data))
                new_match_ids.append(match_id)

        # Count match states for header breakdown
        count_live = 0; count_fin = 0; count_sch = 0
        for entry_data, match_id, is_live, event in raw_entries:
            status_val = entry_data[0] if entry_data else ""
            if status_val == "LIVE": count_live += 1
            elif status_val == "FIN": count_fin += 1
            else: count_sch += 1

        # --- "Next match" countdown (shown in the header when nothing is live) ---
        self._next_match_label = ""
        try:
            best_delta = None
            best_home = None
            best_away = None
            for entry_data, match_id, is_live, event in raw_entries:
                status_val = entry_data[0] if entry_data else ""
                if status_val in ("LIVE", "FIN", "PPD", "SUS", "CAN"):
                    continue
                kdt = get_local_datetime(event.get('date', ''))
                if not kdt:
                    continue
                delta = (kdt - now).total_seconds()
                if delta <= 0:
                    continue
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_home = entry_data[2] if len(entry_data) > 2 else ""
                    best_away = entry_data[4] if len(entry_data) > 4 else ""
            if best_delta is not None:
                def _clean_name(n):
                    n = (n or "").replace(u"\u2605 ", "").strip()
                    return n if len(n) <= 16 else n[:14] + u"\u2026"
                self._next_match_label = u"{}: {} {} {} {}".format(
                    _t("Next"), _clean_name(best_home), _t("vs"), _clean_name(best_away), format_countdown(best_delta))
        except Exception:
            pass

        if not list_content:
            self.update_header(0, count_live, count_fin, count_sch)
            # Guard: internal error strings must not be shown when cached_events exist
            # but the active filter produced no rows — that is a normal no-matches state.
            _INTERNAL_ERRORS = ("JSON Parse Error", "Connection Error")
            _raw_status = self.monitor.status_message or ""
            msg = _t("No Matches Found") if (_raw_status in _INTERNAL_ERRORS or not _raw_status) else _raw_status
            dummy_entry = ("INFO", "", msg, "", "", "", False, "", None, None, 0, 0)
            if self.monitor.theme_mode == "ucl": self["list"].setList([UCLListEntry(dummy_entry)])
            else: self["list"].setList([VNextListEntry(dummy_entry)])
            self.current_match_ids = []
            # Still stamp the refresh time — the fetch itself succeeded, just no matches
            self._last_refreshed = datetime.datetime.now()
        else:
            self.update_header(len(list_content), count_live, count_fin, count_sch)
            if getattr(self["list"], "list", None) is not None and self.current_match_ids == new_match_ids and len(self["list"].list) == len(list_content):
                # Optimization: In-place update prevents cursor jumping and UI flickering
                for i in range(len(list_content)):
                    self["list"].list[i] = list_content[i]
                self["list"].l.setList(self["list"].list)
            else:
                if hasattr(self, '_stagger_timer') and self._stagger_timer:
                    try:
                        self._stagger_timer.stop()
                    except Exception:
                        pass

                # Direct single setList update (bypasses stagger-reveal to prevent native listbox C++ crashes)
                self["list"].setList(list_content)
                self.current_match_ids = new_match_ids

                # --- CURSOR RESTORE ---
                if selected_id:
                    try:
                        new_index = new_match_ids.index(selected_id)
                        self["list"].moveToIndex(new_index)
                    except ValueError: pass

            # Stamp the exact moment this render completed
            self._last_refreshed = datetime.datetime.now()

