    def open_goal_alert_selector(self):
        """Open a ChoiceBox to let the user pick the Goal Alert mode directly."""
        current = self.monitor.discovery_mode
        labels = [
            (_t("Goal Alert: OFF"),    0),
            (_t("Goal Alert: VISUAL"), 1),
            (_t("Goal Alert: SOUND"),  2),
        ]
        options = []
        for label, mode_val in labels:
            if mode_val == current:
                label = u"\u2713 " + label  # checkmark on current
            options.append((label, mode_val))
        self.session.openWithCallback(
            self.goal_alert_selected,
            ChoiceBox,
            title=_t("Select Goal Alert Mode"),
            list=options
        )

    def goal_alert_selected(self, selection):
        if selection is None:
            return
        chosen_mode = selection[1]
        if chosen_mode != self.monitor.discovery_mode:
            self.monitor.set_discovery_mode(chosen_mode)
            self.update_header()

    def open_language_selector(self):
        lang_options = [
            ("English", "en"),
            (u"\u0627\u0644\u0639\u0631\u0628\u064a\u0629  (Arabic)", "ar"),
        ]
        self.session.openWithCallback(
            self.language_selected,
            ChoiceBox,
            title=u"Select Language / \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0629",
            list=lang_options
        )

    def open_goal_sound_selector(self):
        """
        Scans the plugin directory for pop*.mp3 files and lets the user pick one.
        Also offers 'No Sound' to disable the goal alert sound completely.
        """
        plugin_dir = resolveFilename(SCOPE_PLUGINS, "Extensions/SimplySports/")
        sound_files = []
        try:
            for fname in sorted(os.listdir(plugin_dir)):
                if fname.lower().startswith("pop") and fname.lower().endswith(".mp3"):
                    sound_files.append(fname)
        except Exception as e:
            log_dbg("[GoalSound] dir scan error: {}".format(e))

        if not sound_files:
            self.session.open(MessageBox, _t("No sound files found"), MessageBox.TYPE_INFO, timeout=3)
            return

        current = self.monitor.goal_sound_file or "pop.mp3"
        options = []
        for fname in sound_files:
            label = fname
            if fname == current:
                label = u"\u2713 " + fname   # checkmark on current
            options.append((label, fname))
        options.append((_t("No Sound"), ""))

        self.session.openWithCallback(
            self.goal_sound_selected,
            ChoiceBox,
            title=_t("Select Goal Sound"),
            list=options
        )

    def goal_sound_selected(self, selection):
        if selection is None:
            return
        chosen = selection[1]  # filename or "" for no sound
        self.monitor.goal_sound_file = chosen
        self.monitor.save_config()
        # Play a quick preview so the user hears the new sound immediately
        if chosen:
            self.monitor.play_sound()

    def language_selected(self, selection):
        if not selection:
            return
        global PLUGIN_LANGUAGE, _TEAM_NAME_CACHE
        new_lang = selection[1]
        if new_lang == PLUGIN_LANGUAGE:
            return
        PLUGIN_LANGUAGE = new_lang
        _TEAM_NAME_CACHE.clear()
        try:
            for snap in self.monitor.match_snapshots.values():
                snap['h_name_disp'] = _team_name(snap.get('h_name', ''))
                snap['a_name_disp'] = _team_name(snap.get('a_name', ''))
        except Exception:
            pass
        self.monitor.save_config()
        if PLUGIN_LANGUAGE == "ar":
            msg = u"\u062a\u0645 \u062a\u063a\u064a\u064a\u0631 \u0627\u0644\u0644\u063a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0639\u0631\u0628\u064a\u0629.\n\u0633\u064a\u062a\u0645 \u0625\u0639\u0627\u062f\u0629 \u0641\u062a\u062d \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0622\u0646."
        else:
            msg = u"Language changed to English.\nThe screen will now reload."
        self.session.open(MessageBox, msg, MessageBox.TYPE_INFO, timeout=3)
        from twisted.internet import reactor
        reactor.callLater(3.2, self._reopen_after_lang_change)

    def _reopen_after_lang_change(self):
        try:
            self.close(True)
        except Exception:
            pass

    def run_notification_test(self):
        """Sequentially display every notification type using dummy match data."""
        dummy_id = "notif_test_dummy"
        # Inject a temporary match snapshot so GoalToast can render logos/names
        self.monitor.match_snapshots[dummy_id] = {
            'league_name': 'Notifications Demo',
            'league_url': 'https://site.api.espn.com/apis/site/v2/sports/soccer/esp.1/scoreboard',
            'h_name': 'Real Madrid',
            'a_name': 'Barcelona',
            'l_logo_url': 'https://a.espncdn.com/i/leaguelogos/soccer/500/15.png',
            'h_logo_url': 'https://a.espncdn.com/i/teamlogos/soccer/500/86.png',
            'a_logo_url': 'https://a.espncdn.com/i/teamlogos/soccer/500/83.png',
            'l_logo_id': 'test_l', 'h_logo_id': 'test_h', 'a_logo_id': 'test_a',
            'state': 'in', 'score_str': '1-1', 'time_str': '45\'', 'clock': '45\''
        }
        # Define test sequence: (event_type, score, scorer_text, scoring_team, label)
        self._notif_test_queue = [
            ("start",            "0 - 0", "Kick Off!",                      None,   "Match Start"),
            ("goal",             "1 - 0", "Ronaldo (23')",                  "home", "Goal (Home)"),
            ("goal",             "1 - 1", "Messi (35')",                    "away", "Goal (Away)"),
            ("red_card",         "1 - 1", "Ramos",                          "away", "Red Card"),
            ("var_decision",     "1 - 1", "VAR Review - Penalty Check",     None,   "VAR Decision"),
            ("goal_disallowed",  "1 - 1", "Goal Disallowed - Offside",      "home", "Goal Disallowed"),
            ("ht_end",           "1 - 1", "Half Time",                      None,   "Half Time"),
            ("ht_start",         "1 - 1", "Second Half Begins",             None,   "2nd Half Kick-off"),
            ("end",              "2 - 1", "Full Time",                      None,   "Full Time"),
            ("ai_toast",         "",      "",                               None,   "AI Toast"),
            ("fav_toast",        "",      "",                               None,   "Favourite Team Reminder"),
        ]
        self._notif_test_dummy_id = dummy_id
        self._show_next_test_notification()

    def _show_next_test_notification(self, *args):
        """Pop the next test notification and display it, or clean up when done."""
        if not getattr(self, '_notif_test_queue', None):
            # All done — clean up dummy snapshot
            dummy_id = getattr(self, '_notif_test_dummy_id', None)
            if dummy_id and dummy_id in self.monitor.match_snapshots:
                del self.monitor.match_snapshots[dummy_id]
            return

        event_type, score, scorer, scoring_team, label = self._notif_test_queue.pop(0)

        if event_type == "ai_toast":
            # Show AI Toast as the final demo item
            self.session.openWithCallback(
                self._show_next_test_notification, AIToast,
                "This is an AI-powered sports update notification demo!",
                5000
            )
        elif event_type == "fav_toast":
            import time as _time
            self.session.openWithCallback(
                self._show_next_test_notification, FavTeamToast,
                "Real Madrid",             # team_name
                "Real Madrid",             # home_name
                "Barcelona",               # away_name
                "La Liga",                 # league_name
                int(_time.time()) + 3600,  # kick_off_ts — 1 hour from now
                "",                        # channel_name — empty (no EPG)
                "https://a.espncdn.com/i/teamlogos/soccer/500/86.png",  # h_logo_url
                "https://a.espncdn.com/i/teamlogos/soccer/500/83.png",  # a_logo_url
                "test_h",                  # h_logo_id
                "test_a",                  # a_logo_id
            )
            self.monitor.play_fav_sound()
        else:
            dummy_id = getattr(self, '_notif_test_dummy_id', 'notif_test_dummy')
            self.session.openWithCallback(
                self._show_next_test_notification, GoalToast,
                dummy_id, score, scorer, event_type, scoring_team
            )

    def open_ai_mode_menu(self):
        """AI Mode settings via ChoiceBox sub-menu (proven navigation pattern)."""
        m = self.monitor
        if not m.ai_enabled:
            # AI is OFF — offer to turn it on
            options = [
                (_t("Turn AI Mode ON"), "toggle_on"),
            ]
        else:
            # AI is ON — show full config menu
            masked_key = "(not set)" if not m.ai_api_key else ("****" + m.ai_api_key[-4:] if len(m.ai_api_key) > 4 else "****")
            provider_label = m.ai_provider
            for code, label in AI_PROVIDERS:
                if code == m.ai_provider:
                    provider_label = label
                    break
            options = [
                (_t("Turn AI Mode OFF"), "toggle_off"),
                (_t("API Key: ") + masked_key, "api_key"),
                (_t("Provider: ") + provider_label, "provider"),
                (_t("Language: ") + m.ai_language, "language"),
                (_t("Frequency: Every {} min").format(m.ai_frequency), "frequency"),
                (_t("WP Commentary: Every {} min").format(m.wp_commentary_interval), "wp_commentary"),
                (_t("Test AI Now"), "test"),
            ]
        self.session.openWithCallback(self.ai_mode_callback, ChoiceBox, title=_t("AI Mode Settings"), list=options)

