# ---------------------------------------------------------------------------
# World Cup 2026 — Host City → ISO2 country code
# Covers all 16 official venues across USA, Canada, Mexico.
# Keys are lower-cased city names as ESPN's venue.address.city returns them.
# ---------------------------------------------------------------------------
WC_HOST_CITY_FLAGS = {
    # United States (11 venues)
    'new york':        'us', 'east rutherford':  'us', 'new jersey':  'us',
    'los angeles':     'us', 'inglewood':         'us',
    'san francisco':   'us', 'santa clara':       'us', 'bay area':   'us',
    'dallas':          'us', 'arlington':          'us',
    'houston':         'us',
    'atlanta':         'us',
    'seattle':         'us',
    'kansas city':     'us',
    'philadelphia':    'us',
    'miami':           'us', 'miami gardens':      'us',
    'foxborough':      'us', 'boston':             'us',
    # Canada (2 venues)
    'toronto':         'ca',
    'vancouver':       'ca',
    # Mexico (3 venues)
    'mexico city':     'mx', 'ciudad de mexico':  'mx', 'ciudad de méxico': 'mx',
    'guadalajara':     'mx',
    'monterrey':       'mx',
}


def get_wc_stage_info():
    """Return (stage_short, multiplier) for the current WC 2026 tournament stage.

    Mirrors the date brackets in _on_summary_resolved so both scoring and
    the leaderboard badge always agree on the current stage.
    """
    cur_md = time.strftime("%m-%d")
    if   "06-11" <= cur_md <= "06-27": return ("GROUP", 2)
    elif "06-28" <= cur_md <= "07-03": return ("R32",   3)
    elif "07-04" <= cur_md <= "07-07": return ("R16",   4)
    elif "07-08" <= cur_md <= "07-11": return ("QF",    5)
    elif "07-14" <= cur_md <= "07-15": return ("SF",    6)
    elif "07-18" <= cur_md <= "07-19": return ("FINAL", 8)
    else:                               return ("WC",    1)


def get_rank_badge(score, accuracy):
    """Returns a dynamic title badge based on score and accuracy.

    Tiers are evaluated from highest to lowest; the first match wins.
    Each tier has a base badge (score-only) and an optional accuracy-bonus
    badge that unlocks a prestige title at the same score level.

    Tier map:
        500+ pts  & acc > 80% -> Prophet   (elite + surgical)
        500+ pts               -> Legend    (elite volume)
        300+ pts  & acc > 75% -> Visionary (master + razor-sharp)
        300+ pts               -> Master    (high volume)
        150+ pts  & acc > 70% -> Strategist(expert + sharp)
        150+ pts               -> Expert    (solid volume)
         75+ pts  & acc > 65% -> Tactician (veteran + precise)
         75+ pts               -> Veteran   (solid volume)
         50+ pts  & acc > 60% -> Oracle    (early accuracy reward, as specified)
         11-49 pts             -> Scout
          0-10 pts             -> Rookie
    """
    score = int(score)
    accuracy = float(accuracy)

    if score >= 500 and accuracy > 80:
        return "Prophet"
    if score >= 500:
        return "Legend"
    if score >= 300 and accuracy > 75:
        return "Visionary"
    if score >= 300:
        return "Master"
    if score >= 150 and accuracy > 70:
        return "Strategist"
    if score >= 150:
        return "Expert"
    if score >= 75 and accuracy > 65:
        return "Tactician"
    if score >= 75:
        return "Veteran"
    if score >= 50 and accuracy > 60:
        return "Oracle"
    if score >= 11:
        return "Scout"
    return "Rookie"


# Badge tier → hex colour (used by both leaderboard and profile entry builders)
BADGE_COLORS = {
    "Prophet":    0xFFFFAA,   # near-white gold
    "Legend":     0xFFD700,   # gold
    "Visionary":  0xFF44AA,   # pink
    "Master":     0xFF6633,   # orange-red
    "Strategist": 0xAA88FF,   # soft purple
    "Expert":     0xFFAA00,   # amber
    "Tactician":  0x00DDBB,   # bright teal
    "Veteran":    0x00AAAA,   # teal
    "Oracle":     0x00CC66,   # green
    "Scout":      0x4488FF,   # blue
    "Rookie":     0x888888,   # dim gray
}


def get_badge_color(badge):
    return BADGE_COLORS.get(badge, 0x888888)


def LeaderboardListEntry(rank, name, badge, score, accuracy, total_bets, theme_mode="default", wc_stage=None):
    """One coloured row for the global leaderboard list.

    Column layout (1600 px wide, item height 74 px):
      x=0   w=70   rank number / medal symbol
      x=70  w=4    thin accent bar
      x=90  w=460  player name (bold)
      x=570 w=210  badge title (tier colour) + WC stage ×N when wc_stage set
      x=800 w=140  score  label + value
      x=960 w=220  accuracy bar + value
      x=1200 w=200 total bets
      x=1570 w=2   right border
    """
    try:
        # ── Palette ────────────────────────────────────────────────────────────
        if theme_mode == "ucl":
            c_bg   = 0x091442;  c_sel  = 0xc9a020;  c_accent = 0xc9a020
            c_dim  = 0x7799cc;  c_text = 0xeeeeff;  c_gold   = 0xc9a020
        else:
            c_bg   = 0x111118;  c_sel  = 0x00FF85;  c_accent = 0x00FF85
            c_dim  = 0x778899;  c_text = 0xffffff;  c_gold   = 0xFFD700

        c_silver  = 0xC0C0C0
        c_bronze  = 0xCD7F32
        c_won     = 0x33DD77
        c_lost    = 0xFF4455

        # Medal colour for top 3
        if rank == 1:
            rank_color = c_gold
        elif rank == 2:
            rank_color = c_silver
        elif rank == 3:
            rank_color = c_bronze
        else:
            rank_color = c_dim

        badge_color = get_badge_color(badge)

        h = sy(74)
        # rank symbol
        rank_txt = u"#{:d}".format(rank) if rank > 3 else [u"1st", u"2nd", u"3rd"][rank - 1]

        entry_data = ("LB", rank, name, badge, score, accuracy, total_bets, theme_mode)
        res = [entry_data]

        # ── Rank ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    0, 0, sx(70), h, 1,
                    RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                    rank_txt, rank_color, c_sel))

        # ── Thin accent bar (left edge of name column) ──
        bar_color = rank_color if rank <= 3 else c_accent
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(71), sy(8), sx(4), h - sy(16), 0,
                    RT_HALIGN_CENTER,
                    u"", bar_color, bar_color))

        # ── Player name ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(84), 0, sx(470), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    name, c_text, c_sel))

        # ── Badge title (top half) + WC stage multiplier (bottom half) ──
        if wc_stage:
            stage_short, multiplier = wc_stage
            # Badge in top half
            res.append((eListboxPythonMultiContent.TYPE_TEXT,
                        sx(570), 0, sx(210), sy(38), 0,
                        RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                        u"[{}]".format(badge), badge_color, c_sel))
            # Stage multiplier in bottom half — gold, smaller font
            res.append((eListboxPythonMultiContent.TYPE_TEXT,
                        sx(570), sy(38), sx(210), sy(36), 0,
                        RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                        u"\xd7{} {}".format(multiplier, stage_short), 0xc9a020, c_sel))
        else:
            res.append((eListboxPythonMultiContent.TYPE_TEXT,
                        sx(570), 0, sx(210), h, 0,
                        RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                        u"[{}]".format(badge), badge_color, c_sel))

        # ── Score ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(800), 0, sx(60), h, 0,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    u"Pts", c_dim, c_sel))
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(845), 0, sx(120), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    str(score), c_won if score > 0 else c_dim, c_sel))

        # ── Accuracy ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(990), 0, sx(60), h, 0,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    u"Acc", c_dim, c_sel))
        acc_color = c_won if accuracy >= 60 else c_lost if accuracy > 0 else c_dim
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(1038), 0, sx(160), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    u"{:.1f}%".format(accuracy), acc_color, c_sel))

        # ── Total bets ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(1215), 0, sx(70), h, 0,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    u"Bets", c_dim, c_sel))
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(1265), 0, sx(120), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    str(total_bets), c_text, c_sel))

        # ── Bottom separator ──
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    0, h - sy(2), sx(1600), sy(2), 0,
                    RT_HALIGN_CENTER,
                    u"", 0x222230, 0x222230))

        return res
    except Exception as e:
        print("[LB Entry] Error:", e)
        return []


def ProfileListEntry(outcome, h_name, a_name, picked, score_str, date_str, theme_mode="default"):
    """One coloured row for the Personal Profile bet history.

    outcome: "WON", "LOST", or "PENDING"
    Column layout (1600 px wide, item height 74 px):
      x=0   w=4    accent bar (green/red/yellow)
      x=12  w=130  outcome tag  [WON] / [LOST] / [PENDING]
      x=155 w=530  match name   Arsenal vs Chelsea
      x=700 w=80   "Picked:" label
      x=790 w=280  picked team
      x=1085 w=60  "FT:" label  (hidden for PENDING)
      x=1155 w=180 score        (hidden for PENDING)
      x=1390 w=180 date
    """
    try:
        if theme_mode == "ucl":
            c_bg   = 0x091442;  c_sel  = 0xc9a020;  c_accent = 0xc9a020
            c_dim  = 0x7799cc;  c_text = 0xeeeeff
        else:
            c_bg   = 0x111118;  c_sel  = 0x00FF85;  c_accent = 0x00FF85
            c_dim  = 0x778899;  c_text = 0xffffff

        c_won     = 0x33DD77
        c_lost    = 0xFF4455
        c_pending = 0xFFAA00

        if outcome == "WON":
            bar_color = c_won;     tag_color = c_won;     tag_txt = u"[" + _t("WON") + u"]"
        elif outcome == "LOST":
            bar_color = c_lost;    tag_color = c_lost;    tag_txt = u"[" + _t("LOST") + u"]"
        else:
            bar_color = c_pending; tag_color = c_pending; tag_txt = u"[" + _t("PENDING") + u"]"

        match_txt = u"{} vs {}".format(h_name, a_name)

        h = sy(74)
        entry_data = ("PF", outcome, h_name, a_name, picked, score_str, date_str, theme_mode)
        res = [entry_data]

        # Accent bar
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    0, sy(8), sx(4), h - sy(16), 0,
                    RT_HALIGN_CENTER,
                    u"", bar_color, bar_color))

        # Outcome tag
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(12), 0, sx(130), h, 1,
                    RT_HALIGN_CENTER | RT_VALIGN_CENTER,
                    tag_txt, tag_color, c_sel))

        # Match name
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(155), 0, sx(530), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    match_txt, c_text, c_sel))

        # "Picked:" label
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(700), 0, sx(80), h, 0,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    u"Picked:", c_dim, c_sel))

        # Picked team
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(792), 0, sx(280), h, 1,
                    RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                    picked, c_text, c_sel))

        # FT + score (resolved only)
        if outcome != "PENDING":
            res.append((eListboxPythonMultiContent.TYPE_TEXT,
                        sx(1085), 0, sx(50), h, 0,
                        RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                        u"FT:", c_dim, c_sel))
            res.append((eListboxPythonMultiContent.TYPE_TEXT,
                        sx(1140), 0, sx(180), h, 1,
                        RT_HALIGN_LEFT | RT_VALIGN_CENTER,
                        score_str, c_text, c_sel))

        # Date
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(1390), 0, sx(190), h, 0,
                    RT_HALIGN_RIGHT | RT_VALIGN_CENTER,
                    date_str, c_dim, c_sel))

        # Bottom separator
        res.append((eListboxPythonMultiContent.TYPE_TEXT,
                    sx(12), h - sy(2), sx(1570), sy(2), 0,
                    RT_HALIGN_CENTER,
                    u"", 0x222230, 0x222230))

        return res
    except Exception as e:
        print("[Profile Entry] Error:", e)
        return []


