    def _setup_list(self):
        self["list"].l.setFont(0, gFont("Regular", sf(22)))
        self["list"].l.setFont(1, gFont("Regular", sf(24)))
        self["list"].l.setItemHeight(sy(74))

    def cursor_up(self):
        self["list"].up()

    def cursor_down(self):
        self["list"].down()

    def open_profile(self):
        self.session.open(PersonalProfileScreen)

    def fetch_leaderboard(self):
        import threading
        import time
        url = "{}/leaderboard.json?r={}".format(FIREBASE_URL, int(time.time()))

        def _fetch():
            try:
                try:
                    import urllib2 as request_module
                except ImportError:
                    import urllib.request as request_module

                req = request_module.Request(url)
                response = request_module.urlopen(req, timeout=5)
                html = response.read()

                from twisted.internet import reactor
                reactor.callFromThread(self.on_data_received, html)
            except Exception as e:
                print("[SimplySports] Leaderboard fetch failed:", e)

        threading.Thread(target=_fetch).start()

    def on_data_received(self, html):
        import json
        try:
            if isinstance(html, bytes):
                html = html.decode('utf-8')
            if not html or html.strip() == "null":
                self["loading"].setText(_t("No scores recorded yet."))
                return

            data = json.loads(html)
            self.users_data = []
            sports_set = set()  # Automatically find all sports the community has voted on

            if isinstance(data, dict):
                for device_id, info in data.items():
                    user_sports = info.get("sports", {})
                    for s in user_sports.keys():
                        sports_set.add(s)

                    stored_score    = int(info.get("score", 0))
                    stored_accuracy = float(info.get("accuracy", 0.0))

                    # Use the badge stored by the remote client if present;
                    # otherwise compute it live so older clients that pre-date
                    # the badge feature still get a correct title.
                    stored_badge = info.get("badge")
                    if not stored_badge:
                        stored_badge = get_rank_badge(stored_score, stored_accuracy)

                    self.users_data.append({
                        "name": info.get("name", "Anonymous"),
                        "score": stored_score,
                        "accuracy": stored_accuracy,
                        "total_bets": int(info.get("total_bets", 0)),
                        "sports": user_sports,
                        "badge": stored_badge
                    })

            # Build the navigation list with Top 5 European Leagues & World Cup priority
            preferred_order = [
                "Global",
                "Premier League",
                "La Liga",
                "Serie A",
                "Bundesliga",
                "Ligue 1",
                "Champions League",
                "World Cup"
            ]
            nav_list = []
            for item in preferred_order:
                if item == "Global" or item in sports_set:
                    nav_list.append(item)

            # Ensure all Top 5 European leagues + World Cup are always accessible in the navigation
            for item in preferred_order:
                if item not in nav_list:
                    nav_list.append(item)

            # Append any other sports / leagues present in the database
            for s in sorted(list(sports_set)):
                if s not in nav_list:
                    nav_list.append(s)

            self.available_sports = nav_list
            self.apply_sort()

        except Exception as e:
            print("[SimplySports] Parse error:", e)

    # --- NAVIGATION METHODS ---
    def next_sport(self):
        self.current_sport_idx = (self.current_sport_idx + 1) % len(self.available_sports)
        self.apply_sort()

    def prev_sport(self):
        self.current_sport_idx = (self.current_sport_idx - 1) % len(self.available_sports)
        self.apply_sort()

    def sort_by_score(self):
        self.current_sort = "score"
        self.apply_sort()

    def sort_by_accuracy(self):
        self.current_sort = "accuracy"
        self.apply_sort()

    # --- CORE FILTERING AND SORTING ENGINE ---
    def extract_stats(self, user, sport):
        """Extracts either Global stats or specific Sport stats for the math"""
        if sport == "Global":
            return user['score'], user['accuracy'], user['total_bets']
        else:
            sd = user['sports'].get(sport, {})
            sc = sd.get("score", 0)
            tot = sd.get("total", 0)
            cor = sd.get("correct", 0)
            acc = (float(cor) / tot * 100.0) if tot > 0 else 0.0
            return sc, acc, tot

    def apply_sort(self):
        if not self.users_data:
            return

        current_sport = self.available_sports[self.current_sport_idx]

        # 1. Sport / League filter label
        if current_sport == "Global":
            self["sport_label"].setText(u"◄  {}  ►".format(_t("Global Ranking")))
        else:
            trans = _t(current_sport)
            disp_title = trans if trans != current_sport else current_sport
            self["sport_label"].setText(u"◄  {}  ►".format(disp_title))

        # 2. Filter
        filtered_users = [
            u for u in self.users_data
            if current_sport == "Global" or current_sport in u['sports']
        ]

        # 3. Sort
        if self.current_sort == "score":
            sorted_users = sorted(
                filtered_users,
                key=lambda k: (self.extract_stats(k, current_sport)[0],
                               self.extract_stats(k, current_sport)[1]),
                reverse=True)
        else:
            sorted_users = sorted(
                filtered_users,
                key=lambda k: (self.extract_stats(k, current_sport)[1],
                               self.extract_stats(k, current_sport)[0]),
                reverse=True)

        # 4. Render with coloured multiContent rows
        # --- SUGGESTION 4: WC stage multiplier ---
        # When the user is viewing "World Cup" predictions, each leaderboard row
        # shows the current tournament stage and its points multiplier in the
        # badge column (e.g. ×5 QF).  get_wc_stage_info() reuses the same date
        # brackets as _on_summary_resolved so the values always agree.
        is_wc_view = (current_sport == "World Cup")
        wc_stage   = get_wc_stage_info() if is_wc_view else None

        # Update badge column header to show context
        try:
            if is_wc_view:
                stage_short, multiplier = wc_stage
                self["col_badge"].setText(u"Badge  \xd7{}{}".format(
                    multiplier, u" {}".format(stage_short)))
            else:
                self["col_badge"].setText(_t("Badge"))
        except Exception:
            pass

        rows = []
        for idx, user in enumerate(sorted_users):
            rank = idx + 1
            sc, acc, tot = self.extract_stats(user, current_sport)
            badge = get_rank_badge(sc, acc)
            row = LeaderboardListEntry(
                rank, user['name'], badge, sc, acc, tot, self._theme,
                wc_stage=wc_stage)
            if row:
                rows.append(row)

        if not rows:
            rows.append(([("EMPTY",)],))

        self["list"].setList(rows)
        # Hide the loading label once data is rendered
        try:
            self["loading"].setText("")
        except Exception:
            pass


